/* map q11 (425 mục) — engine-API đợt 2411-2440 Ch.2440 */
window.__LIBQ=window.__LIBQ||{};window.__LIBQ["pham-nhan-tu-tien"]=window.__LIBQ["pham-nhan-tu-tien"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q11"]=window.__LIBQ["pham-nhan-tu-tien"]["q11"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q11"]["map"]={"updatedAt":"2026-08-03","count":425,"nodes":[{"id":"day-nui-giua-lanh-tho-nhan-toc-va-yeu-toc","name":"Dãy núi giữa lãnh thổ Nhân tộc và Yêu tộc","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Dãy núi hẻo lánh được Hàn Lập chọn làm nơi xây động phủ và bế quan bí mật.","detail":"Khu vực nằm giữa lãnh thổ Nhân tộc và Yêu tộc, không có người trong phạm vi mấy vạn dặm theo sự dò xét của Hàn Lập. Địa thế vắng vẻ giúp hắn mở động phủ trong lòng núi và bố trí cấm chế che giấu.","theLucLienQuan":["Nhân tộc","Yêu tộc"],"nguon":["@c2171"]},{"id":"dong-phu-bi-mat-cua-han-lap","name":"Động phủ bí mật của Hàn Lập","cn":"","capDo":"khac","parentId":"day-nui-giua-lanh-tho-nhan-toc-va-yeu-toc","blurb":"Động phủ trong lòng núi được Hàn Lập xây dựng để bế quan lâu dài.","detail":"Động phủ do hơn mười khôi lỗi hình vượn đào dựng, có phòng luyện đan, vườn thuốc và nhiều gian phòng. Bên ngoài được nhiều tầng cấm chế lợi hại che kín; Ngân Nguyệt tu luyện trong căn phòng sát mật thất của Hàn Lập.","theLucLienQuan":["Nhân tộc","Yêu tộc"],"nguon":["@c2171"]},{"id":"gian-phong-be-quan-cua-han-lap","name":"Gian phòng bế quan của Hàn Lập","cn":"","capDo":"khac","parentId":"dong-phu-bi-mat-cua-han-lap","blurb":"Gian phòng nơi Hàn Lập hấp thu Dị Ma Kim, củng cố pháp lực và tu luyện Bách Mạch Luyện Bảo Quyết.","detail":"Hàn Lập bế quan tại đây hơn bốn mươi năm. Cửa đá của gian phòng có cấm chế năm màu và từng bị giao long xanh do bảo quyết tạo thành đánh trúng.","theLucLienQuan":[],"nguon":["@c2172"]},{"id":"gian-phong-bi-mat-cua-ngan-nguyet","name":"Gian phòng bí mật của Ngân Nguyệt","cn":"","capDo":"khac","parentId":"dong-phu-bi-mat-cua-han-lap","blurb":"Nơi Ngân Nguyệt tu luyện trong thời gian Hàn Lập bế quan.","detail":"Gian phòng nằm đủ gần nơi Hàn Lập tu luyện để Ngân Nguyệt nghe tiếng rồng gầm, sấm động và cảm nhận mặt đất rung chuyển.","theLucLienQuan":[],"nguon":["@c2172"]},{"id":"vung-dat-bang-phang-cach-dong-phu-van-dam","name":"Vùng đất bằng phẳng cách động phủ vạn dặm","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực rộng lớn được Hàn Lập chọn làm nơi chuẩn bị đột phá Đại Thừa.","detail":"Vùng đất nằm cách động phủ của Hàn Lập khoảng vạn dặm, địa hình rộng và bằng phẳng, xa xa mới có vài ngọn núi. Hàn Lập dựng đại trận che giấu thiên tượng và Phiên Thiên Thai tại đây để giảm nguy cơ bị phát hiện.","theLucLienQuan":[],"nguon":["@c2174"]},{"id":"khu-vuc-phien-thien-thai","name":"Khu vực Phiên Thiên Thai","cn":"","capDo":"khac","parentId":"vung-dat-bang-phang-cach-dong-phu-van-dam","blurb":"Trung tâm khu vực Hàn Lập bố trí cho lần đánh sâu vào chướng ngại Đại Thừa.","detail":"Phiên Thiên Thai rộng khoảng một mẫu và cao hơn ba mươi trượng, nằm giữa các tầng trận pháp che giấu. Trong phạm vi trăm trượng quanh pháp đài còn có hơn ngàn kiếm ảnh ẩn trong không gian.","theLucLienQuan":[],"nguon":["@c2174"]},{"id":"vung-dat-trung","name":"Vùng đất trũng","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Hàn Lập đặt bệ đài và tiến hành dẫn động thiên địa linh khí.","detail":"Thiên địa linh khí trong phạm vi mấy vạn dặm hội tụ về vùng đất trũng thành linh triều vô biên. Cơn lốc vàng do Phạm Thánh pháp tướng tạo ra có lúc chiếm gần một phần ba khu vực.","theLucLienQuan":[],"nguon":["@c2175","@c2179"]},{"id":"day-nui-quanh-vung-dat-trung","name":"Dãy núi quanh vùng đất trũng","cn":"","capDo":"khac","parentId":"vung-dat-trung","blurb":"Dãy núi bao quanh khu vực Hàn Lập đang độ thiên kiếp. Ngân Nguyệt, Chu Quả Nhi và Giải Đạo Nhân đứng trên những đỉnh núi khác nhau để quan sát.","detail":"Từ các đỉnh núi trong khu vực, những người bảo vệ Hàn Lập theo dõi quá trình độ kiếp và phát hiện nhóm người lạ đang tiến đến gần.","theLucLienQuan":[],"nguon":["@c2178"]},{"id":"khong-trung-cach-vung-dat-trung-van-dam","name":"Không trung cách vùng đất trũng khoảng vạn dặm","cn":"","capDo":"khac","parentId":"vung-dat-trung","blurb":"Khu vực không trung nơi nhóm thiếu nữ áo lam bị đội ngũ Ma tộc đuổi kịp. Hai Ma tộc Hóa Thần hậu kỳ chặn đường, khiến nhóm Nhân tộc bị bao vây.","detail":"Địa điểm này nằm trên hướng bay thẳng về vùng đất trũng nơi Hàn Lập đang độ kiếp, khiến cuộc truy sát có nguy cơ tiến vào khu vực thiên kiếp.","theLucLienQuan":["Nhân tộc","Ma tộc"],"nguon":["@c2178"]},{"id":"khu-vuc-ngoai-vi-quanh-dat-trung","name":"Khu vực ngoại vi quanh đất trũng","cn":"","capDo":"khac","parentId":"vung-dat-trung","blurb":"Vành đai bên ngoài khu đất trũng, được giao cho nhóm tu sĩ Hứa gia tuần tra.","detail":"Theo lệnh Ngân Nguyệt, các tu sĩ Hứa gia chia thành nhiều đội tuần tra khu vực này và ngăn mọi người lạ tiếp cận khu vực trung tâm.","theLucLienQuan":["Hứa gia"],"nguon":["@c2179"]},{"id":"khong-gian-xa-la","name":"Không gian xa lạ","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian Hàn Lập thấy mình xuất hiện sau khi bị khuôn mặt xám trắng của Thiên Ngoại Ma Đầu tác động.","detail":"Nhận thức của Hàn Lập chuyển đến nơi này khi thân thể hắn nhẹ bẫng và tâm thần trở nên mơ màng. Bản chất cùng vị trí của không gian chưa được giải thích.","theLucLienQuan":[],"nguon":["@c2181"]},{"id":"khong-gian-tam-ma-kiep","name":"Không gian Tâm Ma Kiếp","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian kỳ dị có bầu trời xám xịt, nơi nguyên thần Hàn Lập đối đầu Thiên Ngoại Ma Quân trong lúc vượt Tâm Ma Kiếp.","detail":"Hàn Lập xuất hiện tại đây dưới hình dáng thiếu niên và không mang theo các vật đeo bên ngoài. Sau khi hắn dọa lui Thiên Ngoại Ma Quân, vô số con mắt xám phát ánh sáng năm màu kéo hắn vào một tầng ảo cảnh ký ức.","theLucLienQuan":[],"nguon":["@c2182"]},{"id":"thon-lang-que-nha-trong-ao-canh","name":"Thôn làng quê nhà trong ảo cảnh","cn":"","capDo":"khac","parentId":"khong-gian-tam-ma-kiep","blurb":"Thôn nhỏ gần núi xanh nước biếc, mang mùi bùn đất và tái hiện quê nhà thời thơ ấu của Hàn Lập.","detail":"Trong ảo cảnh này, Hàn Lập trở thành đứa trẻ sáu, bảy tuổi mặc quần áo vá và chơi cùng Cẩu Oa, Hắc Đản cùng Thiết Tru. Tâm Ma Kiếp khiến hắn quên hiện tại, hoàn toàn hòa vào ký ức trước khi vui mừng nhận ra Tiểu muội.","theLucLienQuan":["Nhân tộc"],"nguon":["@c2182"]},{"id":"khong-gian-ben-ngoai-tam-ma-kiep","name":"Không gian bên ngoài Tâm Ma Kiếp","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian nơi thân thể và Nguyên Anh của Hàn Lập ngồi bất động trong lúc thần thức vượt Tâm Ma Kiếp.","detail":"Ma khí trong khu vực ngày càng dày đặc và liên tục sinh ra những ma vật mạnh hơn. Hồ quang điện vàng quanh Hàn Lập vẫn đánh lui chúng, nhưng số lượng cùng tần suất công kích không ngừng gia tăng.","theLucLienQuan":[],"nguon":["@c2183"]},{"id":"can-phong-tan-hon-trong-thon","name":"Căn phòng tân hôn trong thôn","cn":"","capDo":"khac","parentId":"thon-lang-que-nha-trong-ao-canh","blurb":"Căn phòng tân hôn thuộc huyễn cảnh phàm tục đầu tiên mà Hàn Lập trải qua trong Tâm Ma Kiếp.","detail":"Căn phòng có khăn đỏ, giường gỗ sơn hồng và một tân nương giả. Khung cảnh được dựng nên để khiến Hàn Lập chấp nhận việc cưới vợ, sinh con, sống cùng gia đình và già đi như một phàm nhân.","theLucLienQuan":[],"nguon":["@c2183"]},{"id":"mac-phu","name":"Mặc phủ","cn":"","capDo":"khac","parentId":"khong-gian-tam-ma-kiep","blurb":"Mặc phủ được tâm ma tái dựng thành huyễn cảnh thứ hai nhằm kéo Hàn Lập trở lại một ký ức sâu sắc trong quá khứ.","detail":"Huyễn cảnh mang hình dáng dinh thự của một gia đình giàu có, có hoa cỏ, đường đá và cổng vòm. Tại đây, Mặc Thải Hoàn đứng chờ Hàn Lập và diễn lại cuộc gặp gỡ năm xưa trong lúc nhận thức hiện tại của hắn bị áp chế.","theLucLienQuan":["Mặc phủ"],"nguon":["@c2183"]},{"id":"dai-nui-noi-hai-yeu-vuong-bi-chan","name":"Dải núi nơi hai Yêu Vương bị chặn","cn":"","capDo":"khac","parentId":null,"blurb":"Dải núi xuất hiện hiện tượng thiên văn, nơi hai Đại Yêu Vương bị Giải Đạo Nhân chặn lại.","detail":"Hắc Phượng Vương và Động Thiên Thử Vương vừa tới khu vực này đã bị khí tức Đại Thừa của Giải Đạo Nhân áp chế và buộc phải chờ tại chỗ.","theLucLienQuan":["Yêu tộc"],"nguon":["@c2184"]},{"id":"dai-nui-noi-ngan-nguyet-giao-chien","name":"Dải núi nơi Ngân Nguyệt giao chiến","cn":"","capDo":"khac","parentId":null,"blurb":"Dải núi nơi Ngân Nguyệt giao chiến với một nhóm Ma tộc.","detail":"Ngân Nguyệt triệu xuất pháp tướng sói bạc tại đây, nhưng bị Cổ Ma hai đầu bốn tay phá tan pháp tướng và dồn vào hiểm cảnh trước khi một lưỡi dao bí ẩn can thiệp.","theLucLienQuan":["Ma tộc"],"nguon":["@c2184"]},{"id":"cung-dien-tren-dinh-nui-trong-tam-ma-kiep","name":"Cung điện trên đỉnh núi trong Tâm Ma Kiếp","cn":"","capDo":"khac","parentId":"khong-gian-tam-ma-kiep","blurb":"Đại điện yến tiệc do Tâm Ma Kiếp dựng nên với bối cảnh Thất Huyền môn.","detail":"Hàn Lập gặp ảo ảnh Lệ Phi Vũ tại đây, phát hiện chén rượu có vấn đề và chém gã áo lục khiến toàn bộ cung điện biến mất.","theLucLienQuan":["Thất Huyền môn"],"nguon":["@c2185"]},{"id":"kinh-chau","name":"Kinh Châu","cn":"","capDo":"chau","parentId":"nhan-gioi","blurb":"Vùng đất được nhắc trong cảnh luân hồi Thất Huyền môn.","detail":"Ảo ảnh Lệ Phi Vũ tuyên bố hắn và Hàn Lập đã thống lĩnh Thất Huyền môn, xưng bá Kinh Châu sau vài năm.","theLucLienQuan":["Thất Huyền môn"],"nguon":["@c2185"]},{"id":"lanh-dia-moc-toc","name":"Lãnh địa Mộc tộc","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Khu vực của Mộc tộc từng bị Ma tộc chiếm lĩnh trong thời gian xâm nhập Linh giới.","detail":"Ma tộc đã từ bỏ lãnh địa Mộc tộc khi quân chủ lực rút khỏi Linh giới, nhưng nguyên nhân cụ thể liên quan đến thệ ước bí mật vẫn chưa được làm rõ.","theLucLienQuan":["Mộc tộc","Ma tộc"],"nguon":["@c2187"]},{"id":"cam-dia-hac-phuong-toc","name":"Cấm địa Hắc Phượng tộc","cn":"","capDo":"khac","parentId":null,"blurb":"Cấm địa thuộc Hắc Phượng tộc, được dùng làm nơi bế quan cho các hậu bối quan trọng khi ma kiếp bắt đầu.","detail":"Hắc Phượng Vương đưa Đại Nhi cùng một số đệ tử Hắc Phượng tộc tới đây bế quan tu luyện. Tới khi Hàn Lập hỏi thăm, Đại Nhi vẫn chưa xuất quan nhưng không gặp nguy hiểm.","theLucLienQuan":["Tộc Hắc Phượng"],"nguon":["@c2188"]},{"id":"ngoai-thien","name":"Ngoại thiên","cn":"","capDo":"khac","parentId":"hu-khong","blurb":"Khu vực trên không trung cao hàng vạn trượng, nơi gió lốc và phong nhận không gian trở nên đặc biệt dữ dội.","detail":"Nguyên Anh Hàn Lập tiến vào ngoại thiên khi thi triển Thần Du Vạn Dặm. Càng bay lên cao, gió lốc càng mạnh, phong nhận tạo ra nhiều khe nứt không gian có sức hút nguy hiểm.","theLucLienQuan":[],"nguon":["@c2189"]},{"id":"khe-khong-gian","name":"Khe không gian","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Phàn Bào Tử ẩn náu sau trận chiến với Thất Thủ Kiêu.","detail":"Phàn Bào Tử ẩn trong khe không gian để dưỡng thương sau khi tranh đoạt bảo vật với Thất Thủ Kiêu. Hắn quyết định rời nơi này sau khi Hàn Lập phát hiện sự tồn tại của mình.","theLucLienQuan":["Chân Long nhất tộc"],"nguon":["@c2190"]},{"id":"chan-long-dao","name":"Chân Long đảo","cn":"","capDo":"khac","parentId":null,"blurb":"Địa điểm dự kiến tổ chức Quảng Linh quả đại hội sau vài trăm năm.","detail":"Người tham dự cần có thiếp mời hoặc được Long đảo chủ trực tiếp mời. Khi đại hội sắp mở, lân phiến thiếp mời sẽ hiển thị bản đồ cùng thời gian và vị trí chính xác của đảo.","theLucLienQuan":["Chân Long nhất tộc"],"nguon":["@c2190"]},{"id":"canh-noi-nhan-toc","name":"Cảnh nội Nhân tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực thuộc Nhân tộc nơi Phàn Bào Tử tạm thời ẩn náu dưỡng thương.","detail":"Phàn Bào Tử không muốn tiếp tục lưu lại khu vực này vì lo Thất Thủ Kiêu lần theo dấu vết và trút giận lên toàn thể Nhân tộc.","theLucLienQuan":["Nhân tộc"],"nguon":["@c2190"]},{"id":"cong-thien-uyen-thanh","name":"Cổng Thiên Uyên thành","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Cổng thành cao gần trăm trượng, nơi trưởng lão hội tập trung chờ ba sứ giả Thánh Đảo.","detail":"Nhiều tu sĩ Hợp Thể kỳ và hơn trăm giáp sĩ xếp hàng bên ngoài cổng Thiên Uyên thành. Tại đây, họ nhìn thấy chiếc ngọc thuyền chở Hàn Lập trở về thay vì phái đoàn Thánh Đảo đang được chờ đợi.","theLucLienQuan":["Trưởng lão hội Thiên Uyên thành","Thánh Đảo"],"nguon":["@c2192"]},{"id":"dai-sanh-toa-thap-da","name":"Đại sảnh tòa tháp đá","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Nơi Hàn Lập, các trưởng lão Thiên Uyên thành và ba sứ giả Thánh đảo bắt đầu thương nghị.","detail":"Sau khi được Cốc trưởng lão mời vào thành, các bên an tọa tại đại sảnh của một tòa tháp đá. Hàn Lập trực tiếp hỏi nguyên nhân Thánh đảo cử ba sứ giả đến và liệu sự việc có liên quan đến mình hay không.","theLucLienQuan":["Trưởng lão hội Thiên Uyên thành","Thánh đảo"],"nguon":["@c2193"]},{"id":"dien-thi-dau","name":"Điện thi đấu","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Nơi Hàn Lập và Đỗ Vũ giải quyết tranh chấp bằng giao ước một chiêu.","detail":"Hàn Lập xé rách hư không để tới đây, sau đó những người còn lại cũng di chuyển theo. Cuộc đối đầu diễn ra tại quảng trường rộng bên trong cung điện.","theLucLienQuan":["Thiên Uyên Thành","Thánh Đảo"],"nguon":["@c2195"]},{"id":"quang-truong-trong-cung-dien","name":"Quảng trường trong cung điện","cn":"","capDo":"khac","parentId":"dien-thi-dau","blurb":"Quảng trường nơi Hàn Lập triển khai pháp tướng khổng lồ để áp chế Đỗ Vũ.","detail":"Quảng trường rộng mấy trăm trượng và hơn nửa diện tích được màn sáng bao phủ. Hàn Lập cùng Đỗ Vũ đối mặt trên không trung bên trong màn sáng.","theLucLienQuan":["Thiên Uyên Thành","Thánh Đảo"],"nguon":["@c2195"]},{"id":"thanh-thien-uyen","name":"Thành Thiên Uyên","cn":"","capDo":"thanh","parentId":null,"blurb":"Tòa thành được Hàn Lập dự kiến chọn làm nơi tổ chức đại lễ Đại Thừa.","detail":"Sau khi tin tức tiến cấp Đại Thừa được công bố chính thức, Hàn Lập dự kiến tổ chức lễ mừng sau một năm tại thành Thiên Uyên.","theLucLienQuan":["Nhân tộc","Yêu tộc"],"nguon":["@c2197"]},{"id":"khu-vuc-hoang-da","name":"Khu vực hoang dã","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực rộng lớn mà Băng Phượng đã một mình tiến vào hơn mười năm trước.","detail":"Băng Phượng chưa trở lại sau hơn mười năm ở khu vực hoang dã, nhưng Nguyên Mệnh Đăng vẫn bình yên; Hàn Lập cho rằng việc lưu lại nơi này vài trăm năm cũng không có gì lạ.","theLucLienQuan":[],"nguon":["@c2197"]},{"id":"dia-ban-hai-toc-nhan-yeu","name":"Địa bàn hai tộc Nhân–Yêu","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Lãnh thổ của hai tộc Nhân–Yêu từng bị quân Ma tộc chiếm giữ trong ma kiếp.","detail":"Sau khi quân Ma tộc rút lui, hai tộc thu hồi lãnh thổ, khắc phục tổn thất chiến tranh và chuẩn bị đại lễ mừng Hàn Lập tiến cấp Đại Thừa.","theLucLienQuan":["Nhân tộc","Yêu tộc","Ma tộc"],"nguon":["@c2198"]},{"id":"quang-truong-trung-tam-thanh-thien-uyen","name":"Quảng trường trung tâm thành Thiên Uyên","cn":"","capDo":"khac","parentId":"thanh-thien-uyen","blurb":"Địa điểm trung tâm diễn ra lễ mừng Hàn Lập tiến vào Đại Thừa kỳ.","detail":"Quảng trường cực lớn có đài trắng, Chấn Thiên Chung, hàng vạn vệ sĩ, các quang trận và hơn mười truyền tống trận tạm thời. Nơi đây được giáp sĩ phong tỏa khi đại lễ chính thức bắt đầu.","theLucLienQuan":["Thành Thiên Uyên","Hai tộc Nhân và Yêu"],"nguon":["@c2199"]},{"id":"toa-thap-da-cua-han-lap","name":"Tòa tháp đá của Hàn Lập","cn":"","capDo":"khac","parentId":"thanh-thien-uyen","blurb":"Nơi Hàn Lập nghỉ ngơi và hoàn tất bước tế luyện tạm thời Đại Thừa Tiên Thai trước đại lễ.","detail":"Từ tòa tháp đá này, Hàn Lập rời đi sau khi tế luyện xong bảo vật rồi xuất hiện trên không trung phía trên quảng trường trung tâm.","theLucLienQuan":["Hàn Lập","Thành Thiên Uyên"],"nguon":["@c2199"]},{"id":"ngon-nui-dai-thua-tien-thai","name":"Đại Thừa Tiên Thai","cn":"","capDo":"khac","parentId":"thanh-thien-uyen","blurb":"Ngọn núi ba màu cao tới vạn trượng được Hàn Lập biến ảo giữa Thành Thiên Uyên để tổ chức lễ mừng tiến giai Đại Thừa.","detail":"Đại Thừa Tiên Thai có phần đáy rộng gần che kín khu vực trung tâm thành, lầu các phủ nửa trên và mây trắng bao quanh đỉnh. Trên núi có hơn mười điện tiếp nhận truyền tống, sơn đạo với nhiều cảnh trí, hệ thống cấm chế và quảng trường bạch ngọc dùng làm nơi cử hành đại lễ.","theLucLienQuan":["Thành Thiên Uyên","Nhân tộc","Yêu tộc"],"nguon":["@c2200"]},{"id":"quang-truong-dinh-dai-thua-tien-thai","name":"Quảng trường đỉnh Đại Thừa Tiên Thai","cn":"","capDo":"khac","parentId":"ngon-nui-dai-thua-tien-thai","blurb":"Quảng trường bạch ngọc trên đỉnh Đại Thừa Tiên Thai, nơi hàng vạn tu sĩ tập hợp để bái chúc Hàn Lập.","detail":"Quảng trường có sức chứa khoảng ba đến bốn vạn người, được đặt vô số bồ đoàn và một tòa tháp trong suốt bảy tầng ở trung tâm. Hàn Lập ngồi trên thanh liên ở đỉnh tháp, còn khách dự lễ ngồi kín toàn bộ quảng trường.","theLucLienQuan":["Nhân tộc","Yêu tộc","Các Dị tộc cử sứ giả dự lễ"],"nguon":["@c2200"]},{"id":"quang-truong-dai-dien","name":"Quảng trường đại điển","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi tổ chức đại điển chúc mừng Hàn Lập tiến giai Đại Thừa.","detail":"Hàng vạn tu sĩ thuộc hai tộc Nhân–Yêu tập trung tại đây, uống linh trà và lần lượt dâng lễ vật cho Hàn Lập.","theLucLienQuan":["Nhân tộc"],"nguon":["@c2201"]},{"id":"thap-cao-va-dai-sen-mau-xanh","name":"Tháp cao và đài sen màu xanh","cn":"","capDo":"khac","parentId":"quang-truong-dai-dien","blurb":"Vị trí trung tâm nơi Hàn Lập ngồi chủ trì đại điển.","detail":"Hàn Lập ngồi trên đài sen màu xanh tại tháp cao để tiếp nhận chúc mừng, sau đó đứng dậy đáp lễ sứ giả Linh tộc.","theLucLienQuan":["Nhân tộc"],"nguon":["@c2201"]},{"id":"ranh-gioi-hai-toc-nhan-yeu","name":"Ranh giới hai tộc Nhân–Yêu","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực giáp ranh giữa địa bàn của Nhân tộc và Yêu tộc.","detail":"Vệ Vân Thành là một thành trì hạng trung nằm tại khu vực này và đủ tư cách cử người tham dự đại điển.","theLucLienQuan":["Nhân tộc"],"nguon":["@c2201"]},{"id":"ngon-nui-ba-mau","name":"Ngọn núi ba màu","cn":"","capDo":"khac","parentId":"thanh-thien-uyen","blurb":"Ngọn núi đặt quảng trường tổ chức lễ mừng Đại Thừa của Hàn Lập tại thành Thiên Uyên. Nơi này được nhiều tầng cấm chế bảo vệ.","detail":"Cấm chế trên núi có thể phóng hào quang năm màu và gọi xuống lôi điện vàng bạc. Hắc Kiêu Vương xuyên qua nhiều tầng phòng hộ trước khi đáp xuống quảng trường.","theLucLienQuan":["Thành Thiên Uyên","Nhân tộc"],"nguon":["@c2202"]},{"id":"thanh-dao","name":"Thánh Đảo","cn":"","capDo":"khac","parentId":null,"blurb":"Địa điểm Hàn Lập dự định tới sau lễ mừng Đại Thừa. Các tu sĩ tại đây muốn thương nghị với hắn một chuyện cực kỳ quan trọng.","detail":"Lý Dung thay mặt Thánh Đảo chuyển lời mời, nhưng nội dung cụ thể của cuộc thương nghị chưa được tiết lộ.","theLucLienQuan":["Thánh Đảo"],"nguon":["@c2202"]},{"id":"hua-gia","name":"Hứa gia","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Địa bàn của gia tộc Hứa thị, nơi Huyết Hồn trở về trong tình trạng trọng thương rồi hôn mê.","detail":"Các trưởng bối Hứa gia đã dùng nhiều phương pháp nhưng không thể chữa trị cho Huyết Hồn. Hàn Lập nhận lời cùng Hứa Thiên Vũ tới đây sau vài ngày để xem xét tình trạng của nàng.","theLucLienQuan":["Hứa gia"],"nguon":["@c2205"]},{"id":"dien-chinh-hua-gia","name":"Điện chính Hứa gia","cn":"","capDo":"khac","parentId":"hua-gia","blurb":"Nơi Hàn Lập tiếp kiến gia chủ Hứa Giao và nghe thuật lại biến cố của Huyết Hồn.","detail":"Ngân Nguyệt, Bạch Quả Nhi và Lý Dung ở lại đây trong lúc Hàn Lập cùng Giải Đạo Nhân tiến vào cấm địa. Sau khi tỉnh lại, Huyết Hồn cũng tới điện chính gặp Hàn Lập.","theLucLienQuan":["Hứa gia"],"nguon":["@c2206"]},{"id":"dai-luc-huyet-thien","name":"Đại lục Huyết Thiên","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Một trong ba đại lục thần bí nhất Linh giới.","detail":"Hàn Lập xác định đây là nơi Huyết Cổ Trùng tồn tại, trong khi loại cổ trùng này không có ở đại lục Phong Nguyên.","theLucLienQuan":[],"nguon":["@c2206"]},{"id":"dai-luc-loi-minh","name":"Đại lục Lôi Minh","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Đại lục Hàn Lập từng du lịch nhiều năm trước.","detail":"Trong thời gian ở đại lục Lôi Minh, Hàn Lập thu được một bản điển tịch có ghi chép giúp hắn nhận dạng Huyết Cổ Trùng.","theLucLienQuan":[],"nguon":["@c2206"]},{"id":"vach-vuc-dat-hon-don-van-linh-bang","name":"Vách vực đặt Hỗn Độn Vạn Linh Bảng","cn":"","capDo":"khac","parentId":"thanh-dao","blurb":"Khu vực dưới một vách vực sâu trên Thánh Đảo, nơi Hỗn Độn Vạn Linh Bảng hiện thành vách tường tinh thể cao trăm trượng.","detail":"Địa điểm được hai lão giả có tu vi Luyện Hư Hậu Kỳ chuyên trách bảo vệ.","theLucLienQuan":["Thánh Đảo"],"nguon":["@c2208"]},{"id":"thien-thu-cac","name":"Thiên Thư Các","cn":"","capDo":"khac","parentId":"thanh-dao","blurb":"Tòa nhà cao bảy, tám chục trượng trên Thánh Đảo, lưu giữ hơn vạn bí thuật.","detail":"Tầng trên của tòa nhà được bảo vệ bằng cấm chế vô hình tại cửa cầu thang. Người canh giữ dùng lệnh bài vàng để mở lối cho người đủ điều kiện trao đổi bí thuật.","theLucLienQuan":["Thiên Thư Các","Thánh Đảo"],"nguon":["@c2208"]},{"id":"khong-gian-tiet-diem-thong-ma-gioi","name":"Không gian tiết điểm thông Ma giới","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Tàn tích của đường hầm không gian mà đại quân Ma tộc từng dùng khi rút khỏi Linh giới.","detail":"Vách ngăn giữa hai giới tại đây đã suy yếu và thỉnh thoảng phát ra dao động không gian. Hàn Lập xác định vị trí tiết điểm rồi dùng pháp trận phá giới cùng Nghịch Tinh Bàn mở lại một đường hầm dẫn sang Ma giới.","theLucLienQuan":["Ma tộc","Yêu tộc"],"nguon":["@c2209"]},{"id":"cu-diem-ma-quan-hoang-phe","name":"Cứ điểm Ma quân hoang phế","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Cứ điểm cũ của Ma quân nằm trên một thảo nguyên xanh thuộc lãnh địa Yêu tộc.","detail":"Nơi này từng là cứ điểm quan trọng của Ma quân và có đường hầm không gian dùng khi rút lui. Đoàn Hàn Lập tới đây sau hơn nửa tháng, xác định tiết điểm còn sót lại và mở đường sang Ma giới.","theLucLienQuan":["Ma tộc","Yêu tộc"],"nguon":["@c2209"]},{"id":"dam-lay-den","name":"Đầm lầy đen","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Điểm xuất hiện của nhóm Hàn Lập sau khi tiến vào Ma giới.","detail":"Phía trên đầm lầy có một cửa động tối. Ven đầm là khu nhà đá từng được trận pháp bảo vệ nhưng cấm chế đã bị phá và cư dân Ma tộc đã biến mất.","theLucLienQuan":["Ma tộc"],"nguon":["@c2210"]},{"id":"khu-nha-da-ven-dam","name":"Khu nhà đá ven đầm","cn":"","capDo":"khac","parentId":"dam-lay-den","blurb":"Khu cư trú Ma tộc bỏ hoang nằm ven đầm lầy đen.","detail":"Khu vực gồm khoảng vài trăm gian nhà đá lớn nhỏ. Trận pháp và cấm chế bảo vệ đã bị xé toang, còn bên trong không có bất kỳ bóng dáng Ma tộc nào.","theLucLienQuan":["Ma tộc"],"nguon":["@c2210"]},{"id":"thanh-hac-ho","name":"Thành Hắc Hồ","cn":"","capDo":"thanh","parentId":"ma-gioi","blurb":"Một thành trì Ma tộc nằm về phía bắc Loạn Vân Sơn, rộng khoảng ba bốn trăm dặm.","detail":"Khi ba người Hàn Lập tới nơi, thành Hắc Hồ đang bị một biển Minh Trùng vây kín. Quân thủ thành dựa vào cấm chế phòng hộ, ma khí, ma công, mưa tên và hàng trăm tháp đen phóng điện để chống trả, nhưng quầng sáng bảo vệ đã ảm đạm và hệ thống tháp bắt đầu ngừng hoạt động.","theLucLienQuan":["Ma tộc"],"nguon":["@c2211"]},{"id":"loan-van-son","name":"Loạn Vân Sơn","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Khu vực tại Ma giới nơi nhóm Thải Tinh Khách hoạt động.","detail":"Theo lời thiếu nữ Ma tộc, thành Hắc Hồ nằm về phía bắc và là thành trì gần Loạn Vân Sơn nhất.","theLucLienQuan":["Thải Tinh Khách"],"nguon":["@c2211"]},{"id":"thuy-an","name":"Thủy ấn","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Khu vực bố trí phong ấn Minh Trùng Mẫu và là nơi lực lượng gồm các Thủy Tổ, Thánh Tổ cùng viện quân nhiều giới từng tập trung trấn áp tai họa.","detail":"Khu vực này đã mất hoàn toàn liên lạc với bên ngoài từ hai mươi năm trước. Vô số đàn Minh Trùng chiếm các thành lân cận và tạo thành biển trùng phong tỏa lối vào, trong đó có cá thể mạnh ngang tu sĩ Hợp Thể.","theLucLienQuan":["Lực lượng trấn áp Minh Trùng Mẫu"],"nguon":["@c2213"]},{"id":"day-nui-van-hoa","name":"Dãy núi Vạn Hoa","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Dãy núi tại Ma giới nơi Tà Liên cư ngụ, cách thành Hắc Hồ khoảng một tháng di chuyển bằng phi xa.","detail":"Khu vực có cảnh quan xanh tốt và khá giống những dãy núi tại Nhân giới. Tà Liên từng quét sạch Minh Trùng quanh dãy núi này ba năm trước; Triêu Thiên Phong nằm ở vùng trung tâm.","theLucLienQuan":["Ma tộc"],"nguon":["@c2213"]},{"id":"trieu-thien-phong","name":"Triêu Thiên Phong","cn":"","capDo":"khac","parentId":"day-nui-van-hoa","blurb":"Đỉnh núi nằm giữa dãy Vạn Hoa và là nơi ở của Tà Liên.","detail":"Chướng Nhãn Pháp khiến nơi này trông như một ngọn núi băng tuyết phủ sương đen tà dị. Sau khi lớp ngụy trang bị phá, diện mạo thật hiện ra là ngọn núi cao vài nghìn trượng, phủ kỳ hoa dị thảo, được hào quang năm màu bao bọc và có cung điện xanh biếc trên đỉnh.","theLucLienQuan":["Ma tộc"],"nguon":["@c2213"]},{"id":"bach-quang-gioi","name":"Bạch Quang giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Giới diện quê hương của Kim Soa và Thạch Định.","detail":"Bạch Quang giới đã cử ít nhất hai cường giả Đại Thừa tới Ma giới để tham gia xử lý nguy cơ Minh Trùng Mẫu.","theLucLienQuan":["Nhóm cường giả Bạch Quang giới"],"nguon":["@c2214"]},{"id":"van-hoa-son","name":"Vạn Hoa Sơn","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Khu vực tại Ma giới nơi Tà Liên tạm thời ẩn cư.","detail":"Động phủ của Tà Liên nằm trong một cung điện trên đỉnh núi, được vòng sáng năm màu bao phủ bảo vệ.","theLucLienQuan":["Các Thánh tổ Ma giới chưa vào Thủy Ấn"],"nguon":["@c2214"]},{"id":"bien-con-trung-quanh-thuy-an","name":"Biển côn trùng quanh thủy ấn","cn":"","capDo":"khac","parentId":"thuy-an","blurb":"Vùng biển trùng dày đặc bao quanh thủy ấn, ngăn cản lực lượng bên ngoài tiến vào.","detail":"Sau lần Bảo Hoa thâm nhập điều tra, số lượng côn trùng tại đây tăng hơn gấp mười lần. Trong biển trùng còn có chưa quá một ngàn Minh Trùng đỏ với khả năng thuấn di và tự bạo đủ sức làm các Thánh Tổ bị thương nặng.","theLucLienQuan":["Lực lượng trấn áp Minh Trùng Mẫu"],"nguon":["@c2215"]},{"id":"ma-gioi","name":"Ma giới","cn":"","aliases":["Thánh giới"],"capDo":"gioi-dien","parentId":null,"blurb":"Giới diện của Ma tộc, trong chương còn được gọi là Thánh Giới.","detail":"Khí tức do Minh Trùng Mẫu vô ý phát ra trong lúc ngủ say đã dẫn tới sự xuất hiện của Minh Trùng tại nhiều nơi trong giới diện này.","theLucLienQuan":["Các Thánh tổ Ma giới chưa vào Thủy Ấn"],"nguon":["@c2215"]},{"id":"toa-thanh-co-trong-sa-mac","name":"Tòa thành cổ trong sa mạc","cn":"","capDo":"thanh","parentId":null,"blurb":"Tòa thành cổ màu vàng đất trồi lên giữa một sa mạc mênh mông, trở thành điểm tụ họp của cường giả từ nhiều giới diện.","detail":"Tòa thành rộng vài dặm, có tường cao mấy chục trượng và hơn một vạn giáp sĩ rối canh giữ. Trung tâm thành là cung điện vàng kim phủ ma văn, nơi các đoàn cường giả dị giới lần lượt tiến vào trước chuyến đi tới Thủy Ấn.","theLucLienQuan":["Thiên Nha giới","Bạch Quang giới","Thánh giới"],"nguon":["@c2216"]},{"id":"thanh-dat-mau-vang-cua-hoang-sa-lao-quai","name":"Thành đất màu vàng của Hoàng Sa lão quái","cn":"","capDo":"thanh","parentId":"ma-gioi","blurb":"Tòa thành bằng đất màu vàng nằm trong sa mạc, là địa điểm tổ chức cuộc tụ họp giữa các Thánh tổ Ma giới và đông đảo tu sĩ Đại Thừa ngoại giới.","detail":"Thành thuộc sở hữu của Hoàng Sa lão quái và được hơn vạn Thổ Kiền thần vệ bảo vệ. Bên trong có cung điện vàng chứa phòng khách dùng làm nơi hội họp.","theLucLienQuan":["Ma tộc"],"nguon":["@c2217"]},{"id":"phong-khach-trong-cung-dien-vang","name":"Phòng khách trong cung điện vàng","cn":"","capDo":"khac","parentId":"thanh-dat-mau-vang-cua-hoang-sa-lao-quai","blurb":"Không gian hội họp rộng lớn nằm trong cung điện vàng của Hoàng Sa lão quái. Nơi này có hơn trăm người thuộc hơn ba mươi nhóm hiện diện.","detail":"Phòng khách được nối với cửa cung điện bằng cấm chế truyền tống. Đây là nơi Hoàng Sa lão quái đón các cường giả và giao quyền chủ trì cuộc tụ họp cho Bảo Hoa.","theLucLienQuan":["Ma tộc"],"nguon":["@c2217"]},{"id":"thien-nha-gioi","name":"Thiên Nha giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Giới diện của Đồng Nha Lão Nhân và tám tu sĩ Đại Thừa mặc chiến giáp đi cùng lão.","detail":"Chín cường giả Đại Thừa từ Thiên Nha giới cùng xuất hiện tại phòng khách trong thành đất. Nhóm này lấy Đồng Nha Lão Nhân làm trung tâm và khiến những người dự hội khác chủ động tránh né.","theLucLienQuan":[],"nguon":["@c2217"]},{"id":"phong-khach-noi-cac-dai-thua-tu-hoi","name":"Phòng khách nơi các Đại Thừa tụ hội","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Phòng họp tại Ma giới nơi Bảo Hoa cùng các cường giả ngoại giới bàn kế hoạch tiến vào thủy ấn.","detail":"Bảo Hoa trưng bày Lạc Tinh Phiên và Tiểu Huyễn Thiên Kính tại đây, công khai tin tức Nguyên Yểm truyền ra và điều hòa cuộc tranh luận về mục tiêu cứu viện.","theLucLienQuan":["Ma giới","Thiên Nha giới"],"nguon":["@c2218"]},{"id":"cung-dien-mau-vang","name":"Cung điện màu vàng","cn":"","capDo":"khac","parentId":"thanh-dat-mau-vang-cua-hoang-sa-lao-quai","blurb":"Nơi các lão tổ Đại Thừa họp bàn kế hoạch tiến vào Thủy Ấn.","detail":"Các Đại Thừa thương nghị tại đây suốt một ngày một đêm, hoàn thiện phương án giúp phong ấn thượng cổ đoạt lại sức mạnh và ấn định ngày xuất phát.","theLucLienQuan":["Liên minh"],"nguon":["@c2219"]},{"id":"con-cat-trong-sa-mac","name":"Cồn cát trong sa mạc","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Cồn cát nơi Bảo Hoa bí mật thương lượng giao dịch với Hàn Lập.","detail":"Bảo Hoa dựng một tầng cấm chế vô hình bao phủ cồn cát, sau đó lấy linh quả và linh tửu khoản đãi Hàn Lập trong lúc bàn điều kiện giao dịch.","theLucLienQuan":["Ma tộc"],"nguon":["@c2220"]},{"id":"tho-thanh","name":"Thổ Thành","cn":"","capDo":"thanh","parentId":"ma-gioi","blurb":"Điểm xuất phát của lực lượng Ma tộc tiến về thủy ấn.","detail":"Mấy vạn Ma tộc tinh nhuệ từ cấp Luyện Hư trở lên cùng hàng trăm thuyền lớn tập kết tại đây trước khi đồng loạt lên đường.","theLucLienQuan":["Ma tộc"],"nguon":["@c2220"]},{"id":"dai-doi-thap-ngoai-ria-sa-mac","name":"Dải đồi thấp ngoài rìa sa mạc","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Nơi Hàn Lập cùng hai người đồng hành dừng chân sau cuộc gặp Bảo Hoa.","detail":"Hàn Lập, Ngân Nguyệt và Giải Đạo Nhân đáp xuống dải đồi thấp này sau khi rời cồn cát.","theLucLienQuan":[],"nguon":["@c2220"]},{"id":"thung-lung-hoang-vu-trong-ma-gioi","name":"Thung lũng hoang vu trong Ma giới","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Điểm tập kết đại quân Ma tộc sau ba tháng hành quân.","detail":"Mấy trăm vạn tu sĩ Ma tộc tập trung trong thung lũng trước khi Bảo Hoa công bố kế hoạch nghi binh biển Minh Trùng và đột nhập thủy ấn.","theLucLienQuan":["Ma tộc"],"nguon":["@c2220"]},{"id":"hoang-coc","name":"Hoang cốc","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Nơi lực lượng Ma tộc tập kết trước khi mở chiến dịch tiến về Thủy ấn.","detail":"Các đạo quân Ma tộc từ hoang cốc chia thành nhiều hướng để thu hút Minh Trùng. Lực lượng tinh nhuệ và các tu sĩ Đại Thừa lên chiến thuyền xuất phát sau.","theLucLienQuan":["Ma tộc"],"nguon":["@c2221"]},{"id":"cao-nguyen-doi-troc","name":"Cao nguyên đồi trọc","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Chiến trường nơi một cánh quân hơn mười vạn Ma tộc bị biển Minh Trùng chặn đứng.","detail":"Cánh quân Ma tộc bố trí trận thế hình tròn lấy hàng trăm chiến thuyền làm trung tâm tại khu vực này. Trước các đợt tấn công liên tục của Minh Trùng, họ không thể tiếp tục tiến lên.","theLucLienQuan":["Ma tộc","Minh Trùng"],"nguon":["@c2221"]},{"id":"bien-minh-trung","name":"Biển Minh Trùng","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Khu vực dày đặc Minh Trùng bao quanh tuyến đường tiến tới Thủy ấn.","detail":"Số lượng Minh Trùng tại đây gần như vô tận, khiến nhiều cánh quân Ma tộc bị vây khốn và phải tính đường phá vây. Đội chủ lực vẫn dựa vào sức chiến đấu của các lão tổ Đại Thừa để tiếp tục tiến sâu.","theLucLienQuan":["Ma tộc","Minh Trùng"],"nguon":["@c2221"]},{"id":"vung-doi-ven-thuy-an","name":"Vùng đồi ven thủy ấn","cn":"","capDo":"khac","parentId":"thuy-an","blurb":"Vùng đồi núi hoang vắng nằm sát thủy ấn, nơi đàn Minh Trùng truy đuổi dừng lại và không dám tiến vào.","detail":"Trong vùng đồi có một số lầu các và cung điện nhưng hoàn toàn không có bóng người. Năng lượng phong ấn thượng cổ tại đây khắc chế Minh Trùng, còn các cấm chế ven ngoài đã hư hao và cần được tu bổ.","theLucLienQuan":["Đội ngũ tinh nhuệ Ma tộc","Minh Trùng"],"nguon":["@c2222"]},{"id":"cung-dien-ngam-duoi-phong-an","name":"Cung điện ngầm dưới phong ấn","cn":"","capDo":"khac","parentId":"thuy-an","blurb":"Quần thể cung điện khổng lồ do Thánh tộc thời thượng cổ xây dựng sâu dưới lòng đất để hỗ trợ phong ấn Minh Trùng Mẫu.","detail":"Quần thể trải rộng dưới khu vực phong ấn, có nhiều tầng cấm chế và các mắt trận phân bố tại nhiều nơi. Minh Trùng Mẫu đang nằm ở khu vực trung tâm, trong khi một phần quyền điều khiển phong ấn đã bị nó chiếm giữ.","theLucLienQuan":["Thánh tộc","Minh Trùng"],"nguon":["@c2223"]},{"id":"khe-sau-phun-suong-tim","name":"Khe sâu phun sương tím","cn":"","capDo":"khac","parentId":"thuy-an","blurb":"Khe nứt sâu dẫn xuống cung điện ngầm, liên tục phun tà khí màu tím có mùi tanh.","detail":"Sương tím khiến người hít phải choáng váng và mê muội. Thần niệm tại đây chỉ có thể thăm dò khoảng trăm trượng trước khi mất kiểm soát và tan đi.","theLucLienQuan":["Minh Trùng"],"nguon":["@c2223"]},{"id":"quang-truong-ngoc-trang","name":"Quảng trường ngọc trắng","cn":"","capDo":"khac","parentId":"cung-dien-ngam-duoi-phong-an","blurb":"Quảng trường rộng hơn trăm mẫu nằm sâu khoảng nghìn trượng dưới lòng đất.","detail":"Nền quảng trường được lát ngọc trắng và khảm cách quãng những viên ngọc trong suốt phát sáng, khiến nơi đây sáng rõ như ban ngày. Bảy tám con đường quanh co nối quảng trường với các khu vực khác của cung điện ngầm.","theLucLienQuan":["Thánh tộc"],"nguon":["@c2223"]},{"id":"rung-mo-thuong-co","name":"Rừng mộ thượng cổ","cn":"","capDo":"khac","parentId":"cung-dien-ngam-duoi-phong-an","blurb":"Khu mộ rộng lớn nằm trong quần thể cung điện ngầm, gồm vô số ngôi mộ bốn cạnh cao lớn.","detail":"Các ngôi mộ mang văn tự thượng cổ và trải dài đến mức nhóm Hàn Lập bay suốt một tuần trà vẫn chưa ra khỏi khu vực. Tại đây, Hàn Lập phát hiện một dấu hiệu mà thần niệm của Tà Liên và Lục Thạch không thể nhận ra.","theLucLienQuan":["Thánh tộc"],"nguon":["@c2223"]},{"id":"khu-thach-thap-do-nat","name":"Khu thạch tháp đổ nát","cn":"","capDo":"khac","parentId":"cung-dien-ngam-duoi-phong-an","blurb":"Khu phế tích cách con đường lát gạch hơn hai trăm trượng, nơi nhóm Hàn Lập phát hiện thi thể Minh Trùng mặt người.","detail":"Giữa khu vực có một hố sâu chứa hơn nửa thi thể cháy đen của Minh Trùng mặt người. Những dấu vết đao kiếm xung quanh cho thấy nơi này từng xảy ra một trận chiến kịch liệt.","theLucLienQuan":["Minh Trùng"],"nguon":["@c2224"]},{"id":"vuon-hoa-bac","name":"Vườn hoa bạc","cn":"","capDo":"khac","parentId":"cung-dien-ngam-duoi-phong-an","blurb":"Vườn hoa rộng lớn trồng đầy thực vật màu bạc phổ biến tại Ma giới.","detail":"Khi đi qua khu vườn, Hàn Lập liên tục cảm thấy bị một thứ vô hình nhìn chằm chằm dù thần thức không phát hiện được đối phương. Cảm giác quỷ dị biến mất sau khi hắn rời khỏi vườn.","theLucLienQuan":[],"nguon":["@c2224"]},{"id":"cung-dien-xam-trang-tai-mat-tran","name":"Cung điện xám trắng tại mắt trận","cn":"","capDo":"khac","parentId":"cung-dien-ngam-duoi-phong-an","blurb":"Công trình nằm phía trước vườn hoa bạc, được Tà Liên xác định là nơi đặt mắt trận cấm chế cần sửa chữa.","detail":"Đây là mục tiêu của nhóm Hàn Lập trong hành trình xuyên qua cung điện ngầm. Việc sửa chữa mắt trận tại đây thuộc kế hoạch lớn do Bảo Hoa chủ trì.","theLucLienQuan":[],"nguon":["@c2224"]},{"id":"hang-dong-sau-duoi-cung-dien-ngam","name":"Hang động sâu dưới cung điện ngầm","cn":"","capDo":"khac","parentId":"cung-dien-ngam-duoi-phong-an","blurb":"Hang động tăm tối nằm sâu dưới cung điện ngầm, nơi một bóng người bí ẩn đang ẩn náu.","detail":"Từ nơi này, bóng người nhận ra Hàn Lập đã tu luyện Luyện Thần Thuật đến tầng thứ hai. Phát hiện ấy khiến người này tin rằng cơ hội thoát khỏi nhiều năm đau khổ chống đỡ đã xuất hiện.","theLucLienQuan":[],"nguon":["@c2224"]},{"id":"quang-truong-truoc-cung-dien-ngam","name":"Quảng trường trước cung điện ngầm","cn":"","capDo":"khac","parentId":"cung-dien-ngam-duoi-phong-an","blurb":"Khoảng đất rộng giống một quảng trường nhỏ nằm sau khu vườn, đối diện một cung điện sừng sững.","detail":"Nhóm Hàn Lập tiến vào quảng trường sau khi rời khu vườn. Đây là nơi năm Nhân Diện Trùng xuất hiện và giao chiến với bốn người.","theLucLienQuan":[],"nguon":["@c2225"]},{"id":"cung-dien-minh-ha-sa","name":"Cung điện Minh Hà Sa","cn":"","capDo":"khac","parentId":"cung-dien-ngam-duoi-phong-an","blurb":"Cung điện vắng vẻ được xây bằng Minh Hà Sa, có khả năng ngăn cách thần niệm cực kỳ hữu hiệu.","detail":"Ngay cả thần niệm của Lục Thạch cũng không thể dò xét bên trong cung điện. Năm Nhân Diện Trùng trú tại đây và lao ra sau khi Hàn Lập dùng Ích Tà Thần Lôi oanh kích.","theLucLienQuan":["Minh Trùng"],"nguon":["@c2225"]},{"id":"san-ben-ngoai-cung-dien","name":"Sân bên ngoài cung điện","cn":"","capDo":"khac","parentId":"dai-cung","blurb":"Khoảng sân nơi nhóm Hàn Lập giao chiến với những sâu mặt người.","detail":"Hàn Lập, Tà Liên, Giải Đạo Nhân và Lục Thạch lão tổ lần lượt tiêu diệt các hung trùng tại đây. Đòn lôi điện của Giải Đạo Nhân để lại một hố lớn trên mặt sân.","theLucLienQuan":[],"nguon":["@c2226"]},{"id":"dai-cung","name":"Đại cung","cn":"","capDo":"khac","parentId":null,"blurb":"Công trình có liên hệ trực tiếp với phong ấn Minh Trùng Mẫu và từng được một lực lượng vệ sĩ canh giữ.","detail":"Sau khi tiêu diệt năm hung trùng, nhóm Hàn Lập tiến vào đại cung và phát hiện phía sau cửa điện chất đầy xương trắng, chiến giáp cùng binh khí hư hỏng. Tà Liên cho rằng các vệ sĩ đã bị Minh Trùng Mẫu ăn thịt sau khi nó thoát khỏi phong ấn.","theLucLienQuan":["Vệ sĩ canh giữ đại cung"],"nguon":["@c2226"]},{"id":"khu-rung-da-trong-long-dat","name":"Khu rừng đá trong lòng đất","cn":"","capDo":"khac","parentId":"cung-dien-ngam-duoi-phong-an","blurb":"Khu vực bí mật dưới lòng đất, nơi vô số cột đá mọc lên sau khi cấm chế kích phát. Nhìn từ trên cao, toàn bộ rừng đá tạo thành một trận pháp bao quanh tám cột đồng và tế đàn đỏ máu.","detail":"Trung tâm khu rừng đá có tám cột đồng đỏ như máu mang hình dạng đèn cổ, nhưng chỉ một cột còn ngọn lửa vàng yếu ớt. Giữa tám cột là tế đàn đỏ máu thờ một chiếc bát phủ khí đen.","theLucLienQuan":[],"nguon":["@c2227"]},{"id":"gian-phong-trung-tam-toa-dien","name":"Gian phòng trung tâm tòa điện","cn":"","capDo":"khac","parentId":"cung-dien-ngam-duoi-phong-an","blurb":"Gian phòng lớn đặt cấm chế trung tâm đã bị thay đổi và suy giảm một phần uy lực. Hàn Lập cùng Tà Liên nghiên cứu rồi tu bổ pháp trận tại đây.","detail":"Nhóm bốn người tiến vào gian phòng sau khi kiểm tra những mảnh giáp và binh khí vỡ. Hàn Lập và Tà Liên mất nửa ngày nghiên cứu cùng một ngày một đêm tu bổ pháp trận, trong khi Giải Đạo Nhân và Lục Thạch canh gác bên ngoài.","theLucLienQuan":[],"nguon":["@c2227"]},{"id":"te-dan-do-mau","name":"Tế đàn đỏ máu","cn":"","capDo":"khac","parentId":"khu-rung-da-trong-long-dat","blurb":"Tế đàn cao hàng chục trượng nằm giữa tám cột đồng trong trận pháp rừng đá. Phía trên thờ một chiếc bát phủ khí đen và phát ra tiếng cười âm u.","detail":"Tế đàn được phát hiện tại trung tâm khu vực bí mật sau khi cấm chế bất ngờ kích phát. Chiếc bát trên đỉnh tế đàn có dấu hiệu chứa hoặc liên hệ với một tồn tại có ý thức, nhưng danh tính chưa được xác nhận.","theLucLienQuan":[],"nguon":["@c2227"]},{"id":"duong-ham-trong-cung-dien-ngam","name":"Đường hầm trong cung điện ngầm","cn":"","capDo":"khac","parentId":"cung-dien-ngam-duoi-phong-an","blurb":"Tuyến đường hẹp dẫn Hàn Lập và Giải Đạo Nhân về phía nguồn chấn động.","detail":"Vách đường hầm xuất hiện chi chít vết rách nhỏ trong khi chấn động liên tục tăng mạnh, cho thấy kết cấu của cung điện ngầm đang nhanh chóng mất ổn định.","theLucLienQuan":[],"nguon":["@c2228"]},{"id":"dong-phu-duoi-long-dat","name":"Động phủ dưới lòng đất","cn":"","capDo":"khac","parentId":"cung-dien-ngam-duoi-phong-an","blurb":"Không gian rộng lớn ở cuối đường hầm, nơi Hàn Lập hội hợp với nhóm Bảo Hoa.","detail":"Động phủ có nền cát bạc và măng đá trên đỉnh. Nhóm Bảo Hoa đứng tại đây trước biển sương mù xám trắng để trao đổi với linh hồn phong ấn thượng cổ.","theLucLienQuan":[],"nguon":["@c2228"]},{"id":"bien-suong-mu-xam-trang","name":"Biển sương mù xám trắng","cn":"","capDo":"khac","parentId":"dong-phu-duoi-long-dat","blurb":"Biển sương tỏa mùi đàn hương nằm trong động phủ dưới lòng đất.","detail":"Linh hồn phong ấn thượng cổ hiện thành một khuôn mặt mờ ảo trong biển sương để truyền âm và trao đổi với Bảo Hoa về tình trạng phong ấn.","theLucLienQuan":[],"nguon":["@c2228"]},{"id":"noi-minh-trung-mau-ngu-say","name":"Nơi Minh Trùng Mẫu ngủ say","cn":"","capDo":"khac","parentId":"cung-dien-ngam-duoi-phong-an","blurb":"Khu vực Minh Trùng Mẫu đang ngủ trong phong ấn.","detail":"Linh hồn phong ấn đồng ý đưa nhóm Bảo Hoa thẳng tới đây để họ tập kích Minh Trùng Mẫu trước khi nó hoàn toàn thức tỉnh.","theLucLienQuan":["Minh Trùng"],"nguon":["@c2228"]},{"id":"noi-giam-cam-nguyen-yem","name":"Nơi giam cầm Nguyên Yểm","cn":"","capDo":"khac","parentId":"cung-dien-ngam-duoi-phong-an","blurb":"Khu vực phong ấn Nguyên Yểm cùng hơn một trăm tu sĩ Đại Thừa.","detail":"Nhóm Đồng Nha đang ở gần khu vực này và được trông đợi sẽ giải cứu những người bị nhốt trong lúc nhóm Bảo Hoa cầm chân Minh Trùng Mẫu.","theLucLienQuan":[],"nguon":["@c2228"]},{"id":"khu-vuc-phong-an-trong-cung-dien-ngam","name":"Khu vực phong ấn trong cung điện ngầm","cn":"","capDo":"khac","parentId":"cung-dien-ngam-duoi-phong-an","blurb":"Khu vực phủ sương xám, có đường hầm và truyền tống trận dẫn sâu vào nơi phong ấn Minh Trùng Mẫu.","detail":"Bảo Hoa mở một đường hầm xuyên qua sương xám và dẫn cả nhóm tới truyền tống trận xám trắng nằm giữa khoảng đất trống trải, nơi vang lên những âm thanh khó hiểu.","theLucLienQuan":[],"nguon":["@c2229"]},{"id":"khe-ho-khong-gian-cua-minh-trung-mau","name":"Khe hở không gian của Minh Trùng Mẫu","cn":"","capDo":"gioi-nho","parentId":"noi-minh-trung-mau-ngu-say","blurb":"Khe hở không gian do Minh Trùng Mẫu mở ra, mang hình thái một vùng biển xanh vô tận.","detail":"Nơi này vẫn chịu sự áp chế của phong ấn. Trên bầu trời có pháp trận đen khổng lồ giữ Minh Trùng Mẫu đang ngủ, còn sự ngăn cách không gian khiến hai viện thủ Hắc Dạ giới khó tiến vào.","theLucLienQuan":["Minh Trùng"],"nguon":["@c2229"]},{"id":"toa-phong-an-minh-trung-mau","name":"Tòa phong ấn Minh Trùng Mẫu","cn":"","capDo":"khac","parentId":"khu-vuc-phong-an-trong-cung-dien-ngam","blurb":"Tòa phong ấn có linh hồn riêng và có thể điều động lực lượng để áp chế Minh Trùng Mẫu.","detail":"Bảo Hoa liên hệ với linh hồn của tòa phong ấn, yêu cầu tập trung lực áp chế vào khu vực Minh Trùng Mẫu. Lực lượng phong ấn còn tạo ra các ký hiệu màu xám che giấu khí tức của nhóm tập kích.","theLucLienQuan":["Lực lượng trấn áp Minh Trùng Mẫu"],"nguon":["@c2230"]},{"id":"phap-tran-den-giam-minh-trung-mau","name":"Pháp trận đen giam Minh Trùng Mẫu","cn":"","capDo":"khac","parentId":"toa-phong-an-minh-trung-mau","blurb":"Pháp trận có màn cấm chế màu đen bao quanh và giam giữ Minh Trùng Mẫu.","detail":"Minh Trùng Mẫu nằm bên trong màn cấm chế đen của pháp trận. Khi cuộc tập kích bắt đầu, Thổ Hoàng Đinh xuyên trực tiếp qua lớp cấm chế này và ghim vào thân thể mục tiêu.","theLucLienQuan":["Lực lượng trấn áp Minh Trùng Mẫu"],"nguon":["@c2230"]},{"id":"vung-nuoc-duoi-chien-truong-phong-an","name":"Vùng nước dưới chiến trường phong ấn","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng nước nơi Minh Trùng Mẫu che giấu bản thể và bất ngờ phóng hóa thân bé gái lên tập kích Bảo Hoa.","detail":"Minh Trùng Mẫu ẩn dưới mặt nước trong khi lớp xác sâu keo làm vật thay thế ở phía trên. Bảo Hoa dự định để Dư đạo hữu xuống khu vực này tiêu diệt bản thể, còn nàng và Hàn Lập kiềm chế hóa thân nguyên thần.","theLucLienQuan":["Minh Trùng"],"nguon":["@c2231"]},{"id":"mat-nuoc-chien-truong","name":"Mặt nước chiến trường","cn":"","capDo":"khac","parentId":"vung-nuoc-duoi-chien-truong-phong-an","blurb":"Khu vực mặt nước nơi con sâu trong suốt nhiều mắt hiện thân và giao chiến với Giải Đạo Nhân.","detail":"Tại đây, Giải Đạo Nhân biến thành cua vàng khổng lồ và dùng điện cầu mang ký hiệu bạc đối đầu những mũi tên Sát Lôi xám trắng của con sâu.","theLucLienQuan":["Minh Trùng"],"nguon":["@c2234"]},{"id":"vuc-tham-duoi-day-bien","name":"Vực thẳm dưới đáy biển","cn":"","capDo":"khac","parentId":"vung-nuoc-duoi-chien-truong-phong-an","blurb":"Vực sâu không nhìn thấy đáy nằm dưới chiến trường phong ấn.","detail":"Lão già áo đen và bà lão áo đen phát hiện tại đây một thi thể sâu trắng như ngọc dài tới vạn trượng. Sau khi các đòn công kích bị chặn lại, thi thể được xác định là xác sâu chúa và bắt đầu đứng dậy.","theLucLienQuan":["Minh Trùng"],"nguon":["@c2234"]},{"id":"khong-trung-bien-nuoc","name":"Không trung biển nước","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực phía trên mặt biển, nơi Hàn Lập giao chiến với một con côn trùng khổng lồ.","detail":"Hàn Lập trong hình dạng yêu ma giật đầu con côn trùng dài hơn trăm trượng tại đây. Xác côn trùng không chảy máu và hai chân trước dị dạng co về kích thước bình thường, khiến hắn sinh nghi.","theLucLienQuan":[],"nguon":["@c2235"]},{"id":"bau-troi-phia-tren-mat-nuoc","name":"Bầu trời phía trên mặt nước","cn":"","capDo":"khac","parentId":"mat-nuoc-chien-truong","blurb":"Khoảng không phía trên mặt nước nơi dị tượng ngũ sắc xuất hiện sau khi nhóm Hàn Lập tiến xuống vực sâu.","detail":"Các vòng sáng ngũ sắc ngưng tụ tại đây thành hình dáng giống một cặp mắt khổng lồ, nhưng bản chất của dị tượng chưa được xác nhận.","theLucLienQuan":[],"nguon":["@c2236"]},{"id":"vuc-sau-noi-minh-trung-mau-dieu-duong","name":"Vực sâu nơi Minh Trùng Mẫu điều dưỡng","cn":"","capDo":"khac","parentId":null,"blurb":"Vực sâu chứa biển lửa và xác sâu khổng lồ, nơi Minh Trùng Mẫu tái tạo chân thân rồi giao chiến với nhóm Hàn Lập.","detail":"Minh Trùng Mẫu nhập vào xác sâu giữa biển lửa để phục hồi thân thể ba đầu. Hàn Lập, Bảo Hoa và Giải Đạo Nhân sau đó đến đây vây đánh nó; khi Huyền Thiên Linh Vực bắt đầu triển khai, ánh sáng trong toàn vực trở nên âm u.","theLucLienQuan":["Minh Trùng"],"nguon":["@c2237"]},{"id":"vuc-bien","name":"Vực biển","cn":"","capDo":"vuc","parentId":null,"blurb":"Chiến trường nơi Hàn Lập và Minh Trùng Mẫu hóa thành hai quái vật khổng lồ để đối đầu.","detail":"Khí tức của Hàn Lập và Minh Trùng Mẫu đối chọi dữ dội, tạo cảm giác toàn bộ vực biển bị chia thành hai nửa.","theLucLienQuan":["Minh Trùng"],"nguon":["@c2241"]},{"id":"vung-bien-sau","name":"Vùng biển sâu","cn":"","capDo":"khac","parentId":"vuc-bien","blurb":"Khu vực biển sâu bị chấn động dữ dội bởi cuộc cận chiến giữa Hàn Lập và Minh Trùng Mẫu.","detail":"Sức mạnh thân thể của hai bên khiến đáy biển rung chuyển, sóng nước dâng lên tận trời và hư không liên tục xuất hiện những vết rách màu bạc.","theLucLienQuan":["Minh Trùng"],"nguon":["@c2241"]},{"id":"ha-gioi","name":"Hạ giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Nơi Bách Tạo Sơn được cho là đã đi xuống sau khi phản bội.","detail":"Hạ giới được Minh Trùng Mẫu nhắc tới khi nói về nguồn gốc phương pháp tu luyện Bách Mạch Luyện Bảo Quyết mà Hàn Lập có được.","theLucLienQuan":[],"nguon":["@c2241"]},{"id":"hu-khong-duoi-vuc-sau","name":"Hư không dưới vực sâu","cn":"","capDo":"gioi-nho","parentId":"vuc-tham-duoi-day-bien","blurb":"Không gian chiến trường nằm dưới vực sâu và do lực lượng của Minh Trùng Mẫu tạo ra.","detail":"Sau khi Minh Trùng Mẫu bị tiêu diệt, hư không này bắt đầu sụp đổ. Tiếng động trầm đục truyền lên từ đáy vực trong khi nước biển bốn phía chấn động dữ dội.","theLucLienQuan":["Minh Trùng"],"nguon":["@c2242"]},{"id":"thach-lam-than-bi-trong-dia-cung","name":"Thạch lâm thần bí trong Địa Cung","cn":"","capDo":"khac","parentId":null,"blurb":"Thạch lâm bí ẩn có đồng trụ, cổ đăng và những sợi xích.","detail":"Nam tử điều khiển Thiên Phạt Chi Lôi hiện diện tại đây. Sau khi hắn ra tay giết Minh Trùng Mẫu, cổ đăng duy nhất còn sáng trở nên cực kỳ ảm đạm.","theLucLienQuan":[],"nguon":["@c2242"]},{"id":"te-dan-phong-an","name":"Tế đàn phong ấn","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Nơi Hàn Lập đối thoại với nguyên thần Chân Tiên đang bị giam trong Hắc Đàn Bát.","detail":"Tại đây, Hàn Lập được nghe chân tướng về Luyện Thần Thuật, cuộc chiến với Minh Trùng Mẫu, sự phản bội giữa hai Chân Tiên và điều kiện kích hoạt bùa truyền tin tới Tiên giới.","theLucLienQuan":["Ma tộc","Tiên giới"],"nguon":["@c2244"]},{"id":"dai-te-va-rung-da","name":"Đài tế và rừng đá","cn":"","capDo":"khac","parentId":null,"blurb":"Không gian nơi Hàn Lập trao đổi với người đàn ông trong chiếc bát. Khu vực có rừng đá, trụ đồng xanh và một đài tế.","detail":"Sau khi Hàn Lập được truyền tống rời đi và người đàn ông tiếp tục ngủ, rừng đá cùng các trụ đồng cấu thành trận pháp đồng loạt tan biến, khiến không gian trở lại trống trải.","theLucLienQuan":["Sứ giả tuần tra và giám sát Tiên giới"],"nguon":["@c2245"]},{"id":"dinh-nui-van-truong","name":"Đỉnh núi vạn trượng","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Đỉnh núi nằm rất xa khu vực thủy ấn tại Ma giới. Đây là nơi Hàn Lập gặp Nguyên Yểm theo kế hoạch của Bảo Hoa.","detail":"Hàn Lập chủ động chờ Nguyên Yểm trên đỉnh núi để giữ chân vị thủy tổ này trong lúc Bảo Hoa hành động tại cốc Phỉ Vân. Sau khi Nguyên Yểm quyết định không can thiệp, hai người ngồi lại trao đổi kinh nghiệm tu luyện.","theLucLienQuan":["Ma tộc"],"nguon":["@c2245"]},{"id":"coc-phi-van","name":"Cốc Phỉ Vân","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Một sơn cốc tại Ma giới, cách nơi Hàn Lập gặp Nguyên Yểm khoảng trăm vạn dặm. Lục Cực đang dưỡng thương tại đây.","detail":"Bảo Hoa đến cốc Phỉ Vân để tiến hành mũi hành động chính trong kế hoạch đoạt lại vị trí thủy tổ, trực tiếp nhắm vào Lục Cực đang dưỡng thương.","theLucLienQuan":["Ma tộc"],"nguon":["@c2245"]},{"id":"hon-dao-nho-giua-ho","name":"Hòn đảo nhỏ giữa hồ","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Một hòn đảo nằm giữa hồ tại Ma giới. Lão già Đồng Nha và thanh niên mặc chiến giáp vàng bạc đối đầu tại đây.","detail":"Lão già Đồng Nha lơ lửng trên không với vẻ mặt nghiêm nghị, còn thanh niên tuấn tú đối diện nhìn lão bằng ánh mắt không thân thiện. Chương chưa xác nhận danh tính của thanh niên.","theLucLienQuan":["Ma tộc"],"nguon":["@c2245"]},{"id":"thung-lung-truc-phu-suong-trang","name":"Thung lũng trúc phủ sương trắng","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Một thung lũng trồng đầy trúc và bị sương trắng bao phủ. Nơi đây xuất hiện tiếng nổ cùng những ảo ảnh cánh hoa.","detail":"Sương mù trong thung lũng cuồn cuộn như mặt biển trắng xóa, kèm theo tiếng nổ và các cánh hoa ảo ảnh bay giữa không trung. Chương chưa xác nhận nơi này là cốc Phỉ Vân hay chỉ rõ những người đang tham chiến.","theLucLienQuan":[],"nguon":["@c2245"]},{"id":"thung-lung-chien-truong-cua-bao-hoa-va-luc-cuc","name":"Thung lũng chiến trường của Bảo Hoa và Lục Cực","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Thung lũng nơi Bảo Hoa tiến hành trận báo thù cuối cùng với Lục Cực.","detail":"Bảo Hoa vây bản thể Lục Cực trong Huyền Thiên Linh Vực tại đây rồi phát động đòn công kích cuối. Sau khi khối cầu sáng rộng cả dặm và dao động dữ dội tan đi, chỉ còn Bảo Hoa hiện diện trong thung lũng.","theLucLienQuan":["Ma tộc"],"nguon":["@c2246"]},{"id":"ho-lam-boc","name":"Hồ Lam Bộc","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Một hồ nổi tiếng tại Ma giới, được bao phủ bởi nhiều tầng cấm chế.","detail":"Hàn Lập tới hồ Lam Bộc sau ba tháng và dùng thuyền ngọc trắng tiến về cơ sở Quảng Nguyên Trai nằm trong khu vực này.","theLucLienQuan":["Ma tộc","Quảng Nguyên Trai"],"nguon":["@c2246"]},{"id":"quang-nguyen-trai-tai-ho-lam-boc","name":"Quảng Nguyên Trai tại hồ Lam Bộc","cn":"","capDo":"khac","parentId":"ho-lam-boc","blurb":"Cơ sở của Quảng Nguyên Trai nằm trong khu rừng cạnh thành tại hồ Lam Bộc.","detail":"Cụm kiến trúc được nhiều tầng cấm chế bảo vệ và có tòa lầu nơi thiếu nữ áo gai cùng Dì Chu hiện diện. Hàn Lập dùng thần niệm phá cấm rồi điều khiển thuyền tiến thẳng vào bên trong.","theLucLienQuan":["Quảng Nguyên Trai"],"nguon":["@c2246"]},{"id":"dai-sanh-tang-ba-cua-quang-nguyen-trai","name":"Đại sảnh tầng ba của Quảng Nguyên Trai","cn":"","capDo":"khac","parentId":"quang-nguyen-trai-tai-ho-lam-boc","blurb":"Đại sảnh nơi Hàn Lập gặp Lam Dĩnh và sau đó trò chuyện riêng với Tử Linh.","detail":"Tại đây, Hàn Lập nhờ Lam Dĩnh liên hệ Tử Linh và tra cứu bí tàng Khấp Linh. Năm ngày sau, Lam Dĩnh đưa Tử Linh tới để hai người gặp riêng.","theLucLienQuan":["Quảng Nguyên Trai"],"nguon":["@c2247"]},{"id":"thanh-lam-boc","name":"Thành Lam Bộc","cn":"","capDo":"thanh","parentId":"ma-gioi","blurb":"Tòa thành có cơ sở của Quảng Nguyên Trai, nơi Hàn Lập lưu lại một tháng.","detail":"Hàn Lập ở tại cơ sở Quảng Nguyên Trai trong thành để truyền kinh nghiệm tu luyện Ma công cho Tử Linh. Sau khi du ngoạn quanh hồ Lam Bộc và chia tay nàng, hắn rời khỏi thành.","theLucLienQuan":["Quảng Nguyên Trai","Ma tộc"],"nguon":["@c2248"]},{"id":"son-coc-gan-lam-boc","name":"Sơn cốc gần Lam Bộc","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Sơn cốc gần Lam Bộc, nơi Hàn Lập hội hợp với Ngân Nguyệt.","detail":"Nửa tháng sau khi chia tay Tử Linh, Hàn Lập tới sơn cốc này gặp Ngân Nguyệt và bàn việc tạm hoãn trở về Linh giới để tìm bảo vật.","theLucLienQuan":[],"nguon":["@c2248"]},{"id":"vung-dat-hoang-cua-ma-toc","name":"Vùng đất hoang của Ma tộc","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Vùng hoang dã trong Ma giới mà Hàn Lập và Ngân Nguyệt tiến vào bằng phi thuyền.","detail":"Sau vài tháng phi hành, Hàn Lập và Ngân Nguyệt tiến vào vùng đất hoang này. Trong lúc con rối hình vượn điều khiển phi thuyền, hai người lần lượt tu luyện và nghiên cứu vật phẩm.","theLucLienQuan":["Ma tộc"],"nguon":["@c2248"]},{"id":"canh-dong-bang-ma-gioi","name":"Cánh đồng băng Ma giới","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Vùng băng tuyết rộng lớn tại Ma giới, nơi Hàn Lập tìm đường tới bảo tàng Khấp Linh và gặp lại Nguyên Sát.","detail":"Khu vực có gió lạnh, bão tuyết, sông băng và những núi băng cao lớn. Hàn Lập cùng Ngân Nguyệt đi sâu vào vùng này bằng thuyền bay màu trắng.","theLucLienQuan":["Ma tộc"],"nguon":["@c2249"]},{"id":"nui-bang-noi-nguyen-sat-giao-chien","name":"Núi băng nơi Nguyên Sát giao chiến","cn":"","capDo":"khac","parentId":"canh-dong-bang-ma-gioi","blurb":"Ngọn núi băng nơi Hàn Lập và Ngân Nguyệt gặp lại Nguyên Sát.","detail":"Ngọn núi cao mấy nghìn trượng, sườn núi bị cuộc giao chiến bào mòn và phủ đầy băng vỡ. Nguyên Sát tiêu diệt giao long trắng tại khu vực này.","theLucLienQuan":["Ma tộc"],"nguon":["@c2249"]},{"id":"bao-tang-khap-linh","name":"Bảo tàng Khấp Linh","cn":"","capDo":"khac","parentId":"canh-dong-bang-ma-gioi","blurb":"Bảo tàng bí mật do Khấp Linh để lại tại Ma giới.","detail":"Địa điểm được đánh dấu trên bản đồ gắn với thông tin Lam Dĩnh cung cấp. Khi Hàn Lập và Ngân Nguyệt trao đổi về mục tiêu, nơi này còn cách họ khoảng nửa ngày đường và có thể cất giữ Ma Linh Thánh Chu.","theLucLienQuan":["Ma tộc"],"nguon":["@c2249"]},{"id":"binh-nguyen-bang","name":"Bình nguyên băng","cn":"","capDo":"vuc","parentId":"ma-gioi","blurb":"Vùng băng tuyết rộng lớn che giấu lối vào bảo tàng Khấp Linh.","detail":"Giữa bình nguyên băng có một hồ nước nóng màu lam rộng lớn, quanh bờ mọc những bụi cây xanh đen. Hàn Lập và Ngân Nguyệt tới đây để tìm cửa vào bảo tàng.","theLucLienQuan":["Ma tộc"],"nguon":["@c2250"]},{"id":"ho-nuoc-nong-mau-lam","name":"Hồ nước nóng màu lam","cn":"","capDo":"khac","parentId":"binh-nguyen-bang","blurb":"Hồ nước nóng rộng vài nghìn mẫu nằm giữa bình nguyên băng, bên dưới ẩn giấu cửa vào bảo tàng Khấp Linh.","detail":"Hàn Lập dùng bốn miếng gạch tạo pháp trận năm màu trên mặt hồ. Cột sáng xám từ pháp trận khiến vòng xoáy đen dẫn xuống bảo tàng hiện ra, rồi lối vào khép lại sau khi hai người tiến xuống.","theLucLienQuan":["Ma tộc"],"nguon":["@c2250"]},{"id":"me-cung-vo-danh-duoi-long-ho","name":"Mê cung vô danh dưới lòng hồ","cn":"","capDo":"khac","parentId":"bao-tang-khap-linh","blurb":"Mê cung cột trụ nằm trong bảo tàng Khấp Linh, chứa tiếng gào khóc mê thần và những đợt sói đen do khí đen huyễn hóa.","detail":"Khu vực này dày đặc những cột trụ cao hàng chục trượng, phủ khí đen và sương mù. Tiếng gào khóc có thể mê loạn tu sĩ thông thường, còn cấm chế liên tục tạo sói đen tập kích người xâm nhập và vẫn che giấu một tác dụng khác.","theLucLienQuan":["Khấp Linh"],"nguon":["@c2250"]},{"id":"me-cung-trong-bao-tang-khap-linh","name":"Mê cung trong bảo tàng Khấp Linh","cn":"","capDo":"khac","parentId":"bao-tang-khap-linh","blurb":"Mê cung có vô số cột trụ, âm khí dơ bẩn và ảo ảnh yêu thú nằm trong bảo tàng Khấp Linh.","detail":"Hàn Lập và Ngân Nguyệt đi qua mê cung, chống lại âm khí dơ bẩn và tiêu diệt các ảo ảnh yêu thú. Cuối đường là một cánh cổng đỏ khổng lồ dẫn vào khu vực biển lửa.","theLucLienQuan":["Ma tộc"],"nguon":["@c2251"]},{"id":"canh-cong-hoa-nguyen-tinh","name":"Cánh cổng Hỏa Nguyên Tinh","cn":"","capDo":"khac","parentId":"me-cung-trong-bao-tang-khap-linh","blurb":"Cánh cổng đỏ cao hơn mười trượng nằm ở cuối mê cung trong bảo tàng Khấp Linh.","detail":"Cổng được luyện từ Hỏa Nguyên Tinh và khảm Ma văn màu đen. Khi Hàn Lập kích hoạt, cổng mở ra, phun luồng nhiệt dữ dội và để lộ biển lửa phía sau.","theLucLienQuan":["Ma tộc"],"nguon":["@c2251"]},{"id":"bien-lua-sau-canh-cong","name":"Biển lửa sau cánh cổng","cn":"","capDo":"khac","parentId":"canh-cong-hoa-nguyen-tinh","blurb":"Khu vực biển lửa nằm sau cánh cổng Hỏa Nguyên Tinh, có nhiều dao động cấm chế và tinh thạch đỏ.","detail":"Mặt đất trong khu vực rải đầy tinh thạch đỏ có thể phun lửa và phát nổ. Con rối Ma tinh khổng lồ ẩn dưới vùng tinh thạch này rồi trồi lên tập kích Hàn Lập cùng Ngân Nguyệt.","theLucLienQuan":["Ma tộc"],"nguon":["@c2251"]},{"id":"dai-cao-tinh-thach-do-tham","name":"Đài cao tinh thạch đỏ thẫm","cn":"","capDo":"khac","parentId":"bien-lua-sau-canh-cong","blurb":"Đài cao rộng khoảng ngàn mẫu, có bề mặt phủ tinh thạch đỏ thẫm.","detail":"Sau khi con rối cuối cùng bị thu lấy, toàn bộ đài cao chìm xuống hơn trăm trượng và để lộ cửa đá dẫn vào bảo tàng của Khấp Linh thánh tổ.","theLucLienQuan":[],"nguon":["@c2252"]},{"id":"khu-ham-chua-dai-quan-con-roi","name":"Khu hầm chứa đại quân con rối","cn":"","capDo":"khac","parentId":"bien-lua-sau-canh-cong","blurb":"Vùng lõm rộng lớn quanh đài cao, chứa vô số hầm sâu dành cho đại quân con rối ma tinh.","detail":"Các hầm kéo dài đến tận chân trời và chứa gần mười vạn con rối thuộc nhiều hình thái chiến đấu. Thực lực của chúng trải từ Kết Đan, Nguyên Anh đến Hóa Thần, Luyện Hư và Hợp Thể.","theLucLienQuan":[],"nguon":["@c2252"]},{"id":"bao-tang-cua-khap-linh-thanh-to","name":"Bảo tàng của Khấp Linh thánh tổ","cn":"","capDo":"khac","parentId":"dai-cao-tinh-thach-do-tham","blurb":"Kho báu bí mật nằm sau cửa đá được lộ ra khi đài cao chìm xuống.","detail":"Không gian bên trong có quy mô như cung điện, chứa nhiều bệ đá đặt hộp ngọc và bảo vật cấp cao. Ba bục cao nhất lần lượt đặt cán thương xanh rỉ sét, hồ lô vàng nhạt và phi chu đen nhánh.","theLucLienQuan":[],"nguon":["@c2252"]},{"id":"dai-nui-vo-danh-o-linh-gioi","name":"Dải núi vô danh ở Linh giới","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Một dải núi tại Linh giới, nơi Ma Linh Thánh Chu xuất hiện sau khi xuyên qua vòng xoáy không gian.","detail":"Đây là điểm Hàn Lập và Ngân Nguyệt trở lại Linh giới. Vị trí này tuy lệch khỏi dự định ban đầu nhưng gần địa bàn Nhân tộc hơn.","theLucLienQuan":["Nhân tộc"],"nguon":["@c2253"]},{"id":"phong-an-thuong-co-tai-ma-gioi","name":"Phong ấn thượng cổ tại Ma giới","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Một phong ấn cổ tại Ma giới, nơi Ngao Khiếu và Mạc Giản Ly từng suýt táng thân.","detail":"Phong ấn này đang che giấu một Chân Tiên. Khi kể lại hành trình, Hàn Lập không tiết lộ sự tồn tại đó và quy một phần công lao diệt Minh Trùng Mẫu cho sức mạnh của phong ấn.","theLucLienQuan":[],"nguon":["@c2253"]},{"id":"lanh-dia-linh-toc","name":"Linh tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Lãnh địa của Linh tộc, do Linh Vương bảo hộ và duy trì qua một thời gian rất dài.","detail":"Thạch Tâm lão tổ từng lưu lại tại đây, tận mắt nhìn thấy Tam Thanh Lôi Tiêu Phù và đạt thỏa thuận giao dịch với chủ nhân của bí phù. Linh tộc khó mở rộng vì thành viên mới sinh ra cực kỳ khó khăn.","theLucLienQuan":["Linh tộc"],"nguon":["@c2254"]},{"id":"linh-toc-dia-ban","name":"Linh tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Địa bàn của Linh tộc và là nơi Linh Vương cư ngụ.","detail":"Hàn Lập và Mạc Giản Ly dự định tới đây sau một năm, khi Mạc Giản Ly đã bế quan hồi phục nguyên khí, nhằm gặp Linh Vương và tìm cách lấy Tam Thanh Lôi Tiêu Phù.","theLucLienQuan":["Linh tộc"],"nguon":["@c2255"]},{"id":"the-gioi-hoang-da","name":"Thế giới hoang dã","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực rộng lớn có nhiều cơ duyên nhưng cực kỳ nguy hiểm, được Hàn Lập chọn làm nơi rèn luyện cho hai đệ tử.","detail":"Thế giới hoang dã chứa nhiều cơ duyên có thể giúp tu sĩ vượt qua bình cảnh, nhưng mức độ nguy hiểm đủ khiến cả tu sĩ Hợp Thể Kỳ bỏ mạng. Khí Linh Tử và Bạch Quả Nhi được lệnh tới đây rèn luyện thực tế.","theLucLienQuan":[],"nguon":["@c2256"]},{"id":"dai-luc-thien-nguyen","name":"Đại lục Thiên Nguyên","cn":"","capDo":"chau","parentId":null,"blurb":"Đại lục nơi thanh niên áo trắng sáu cánh ve và thiếu nữ áo bạc xuất hiện.","detail":"Tại một vùng mặt nước thuộc đại lục Thiên Nguyên, thanh niên áo trắng giao chiến với đàn sư tử lửa cấp Hóa Thần trong khi thiếu nữ áo bạc đứng quan sát phía sau.","theLucLienQuan":[],"nguon":["@c2256"]},{"id":"lanh-dia-yeu-toc","name":"Lãnh địa Yêu tộc","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực mà đoàn Hàn Lập tiến vào bằng Mặc Linh Thánh Thuyền sau khi rời Thánh Đảo.","detail":"Đoàn Hàn Lập đi qua lãnh địa Yêu tộc để tìm một đài tế thượng cổ. Những Yêu tu gặp chiến thuyền và lực lượng con rối ma tinh trên đường đều chủ động tránh xa.","theLucLienQuan":["Yêu tộc"],"nguon":["@c2259"]},{"id":"vung-bien-cua-hoa-thach","name":"Vùng biển của Hoa Thạch","cn":"","capDo":"vuc","parentId":"lanh-dia-yeu-toc","blurb":"Vùng biển giàu tài nguyên do Hoa Thạch chiếm cứ khoảng vạn năm.","detail":"Động phủ của Hoa Thạch nằm dưới đáy vùng biển này. Mặc Linh Thánh Thuyền đi qua đã kích hoạt cảnh báo trong động phủ, dẫn đến cuộc chạm trán giữa Hoa Thạch và đoàn Hàn Lập.","theLucLienQuan":["Yêu tộc","Thủy tộc"],"nguon":["@c2259"]},{"id":"ti-nam-tu-phuong-dan","name":"Ti Nam Tứ Phương Đàn","cn":"","capDo":"khac","parentId":null,"blurb":"Một đài tế không trọn vẹn lưu lại từ thượng cổ, không có vị trí cố định.","detail":"Ti Nam Tứ Phương Đàn luôn di động và lơ lửng nên việc tìm thấy phụ thuộc nhiều vào vận may. Hoa Thạch chỉ có thể dẫn đoàn Hàn Lập đến một số nơi đài tế thường xuất hiện.","theLucLienQuan":[],"nguon":["@c2259"]},{"id":"mat-van-hung-lam","name":"Mật Vân Hung Lâm","cn":"","capDo":"khac","parentId":"lanh-dia-yeu-toc","blurb":"Khu rừng hung hiểm thuộc vùng hoạt động của Yêu tộc, nơi Hàn Lập tìm thấy Ti Nam Cổ Đàn.","detail":"Bên dưới khu rừng là đầm lầy phủ khí độc xanh nhạt, có cạm bẫy tự nhiên, yêu thú chưa khai trí và nhiều độc trùng. Tu sĩ từ Hóa Thần trở xuống khó tồn tại lâu tại đây nếu không có bảo vật hộ thân đặc biệt.","theLucLienQuan":["Yêu tộc"],"nguon":["@c2260"]},{"id":"dam-nuoc-trung-tam-mat-van-hung-lam","name":"Đầm nước trung tâm Mật Vân Hung Lâm","cn":"","capDo":"khac","parentId":"mat-van-hung-lam","blurb":"Đầm nước hoang vắng ở trung tâm Mật Vân Hung Lâm, nơi Ti Nam Cổ Đàn lơ lửng trên không.","detail":"Đây là điểm kết thúc hành trình tìm kiếm đài tế của đoàn Hàn Lập và là nơi họ bắt đầu tiến hành phép đo định vị Tiểu Linh Thiên.","theLucLienQuan":["Yêu tộc"],"nguon":["@c2260"]},{"id":"dai-luc-phong-nguyen","name":"Đại lục Phong Nguyên","cn":"","capDo":"chau","parentId":"linh-gioi","blurb":"Đại lục nơi Ti Nam Tế Đàn hiện tại tiến hành suy tính lối vào Tiểu Linh Thiên.","detail":"Kết quả suy tính xác nhận lối vào Tiểu Linh Thiên không nằm tại đại lục Phong Nguyên, đồng thời cho thấy phạm vi tính toán của đài tế đang dùng bị giới hạn trong đại lục này.","theLucLienQuan":["Nhân tộc","Yêu tộc"],"nguon":["@c2261"]},{"id":"khe-nui-sau","name":"Khe núi sâu","cn":"","capDo":"khac","parentId":"the-gioi-hoang-da","blurb":"Khe núi trong thế giới hoang dã nơi Mặc Linh Thánh Thuyền gặp biển bão lốc.","detail":"Khu vực bị bao phủ bởi những cột lốc cao hàng vạn trượng, khiến khôi lỗi trên thuyền không thể hóa giải hoàn toàn và buộc Hàn Lập cùng Mạc Giản Ly trực tiếp ra tay.","theLucLienQuan":[],"nguon":["@c2261"]},{"id":"bao-phong-hai","name":"Bạo Phong Hải","cn":"","capDo":"vuc","parentId":null,"blurb":"Vùng biển nguy hiểm có thiên uy dữ dội và những lốc xoáy khổng lồ.","detail":"Hàn Lập và Mạc Giản Ly liên thủ phá tan cuồng phong tại đây, mở đường cho Mặc Linh Thánh Thuyền rời khỏi hạp cốc.","theLucLienQuan":[],"nguon":["@c2262"]},{"id":"cu-diem-linh-thien","name":"Cứ điểm Linh Thiên","cn":"","capDo":"thanh","parentId":"linh-vuc","blurb":"Một trong bảy cứ điểm bảo vệ các tuyến đường trọng yếu của Linh tộc.","detail":"Cứ điểm được xây quanh một ngọn núi cao hơn vạn trượng, với nhiều kiến trúc hình tháp dày đặc. Nơi đây dựa vào địa thế hiểm trở để ngăn Dị tộc xâm nhập.","theLucLienQuan":["Linh tộc"],"nguon":["@c2262"]},{"id":"khu-vuc-hoa-ly-so-ba","name":"Khu vực Hỏa Ly số ba","cn":"","capDo":"khac","parentId":"cu-diem-linh-thien","blurb":"Khu vực gần cứ điểm Linh Thiên nơi Bối La Đồ ghi nhận dao động linh áp bất thường.","detail":"Mặc Linh Thánh Thuyền từng dừng tại khu vực này. Hơn trăm vệ sĩ Linh tộc được phái tới dò xét nhưng không tìm thấy dấu vết hữu ích.","theLucLienQuan":["Linh tộc"],"nguon":["@c2262"]},{"id":"linh-vuc","name":"Linh vực","cn":"","capDo":"vuc","parentId":"dai-luc-phong-nguyen","blurb":"Tộc vực của Linh tộc, được bảo vệ bởi địa thế hiểm trở và bảy cứ điểm phòng thủ.","detail":"Đoàn Hàn Lập tránh cứ điểm Linh Thiên, vượt qua một thủy vực độc không được trực tiếp trấn giữ và bí mật tiến vào nơi này.","theLucLienQuan":["Linh tộc"],"nguon":["@c2262"]},{"id":"thuy-vuc-den","name":"Thủy vực đen","cn":"","capDo":"khac","parentId":"linh-vuc","blurb":"Hiểm địa có nước kỳ độc, sương vàng và nhiều Huyền Thừ thú.","detail":"Khu vực có cấm chế hạn chế tốc độ của pháp bảo phi hành, kèm âm thanh quỷ dị và những đợt tập kích liên tục của Huyền Thừ thú có thân thể đặc biệt bền chắc.","theLucLienQuan":["Linh tộc"],"nguon":["@c2262"]},{"id":"trung-tam-linh-toc","name":"Trung tâm Linh tộc","cn":"","capDo":"khac","parentId":"linh-vuc","blurb":"Khu vực trung tâm của Linh tộc và là điểm đến của đoàn Hàn Lập.","detail":"Hàn Lập cùng những người đồng hành muốn tới đây tìm Linh Vương. Hai tu sĩ Đại Thừa Dị tộc cũng bí mật bàn bạc về Linh Vương và Lôi Tiêu Phù trong một lầu các tại khu vực này.","theLucLienQuan":["Linh tộc"],"nguon":["@c2262"]},{"id":"cam-dia-than-bi-cua-linh-toc","name":"Cấm địa thần bí của Linh tộc","cn":"","capDo":"khac","parentId":"linh-vuc","blurb":"Một cấm địa có ngọc tháp trắng nằm trong tộc vực Linh tộc.","detail":"Trên tầng cao nhất của ngọc tháp có năm ngọc bài dài hơn thước đang lơ lửng, bên ngoài được điện vàng quấn quanh.","theLucLienQuan":["Linh tộc"],"nguon":["@c2262"]},{"id":"thanh-thuy-yen","name":"Thành Thúy Yên","cn":"","capDo":"thanh","parentId":"trung-tam-linh-toc","blurb":"Thành trì lớn nhất tại trung tâm lãnh địa Linh tộc, cách núi Phục Linh hơn mười vạn dặm.","detail":"Sau hai tháng di chuyển theo đường vắng, đoàn Hàn Lập tới khu vực thành Thúy Yên. Mặc Linh Thánh Thuyền được dừng ở vùng phụ cận bên ngoài thành trước khi Hàn Lập và Mạc Giản Ly tiến về núi Phục Linh.","theLucLienQuan":["Linh tộc"],"nguon":["@c2263"]},{"id":"nui-phuc-linh","name":"Núi Phục Linh","cn":"","aliases":["Núi Thánh của Linh tộc","Thánh sơn Linh tộc"],"capDo":"khac","parentId":"trung-tam-linh-toc","blurb":"Thánh Địa của Linh tộc và nơi cư trú của Linh Vương cùng các thánh vệ.","detail":"Núi Phục Linh cao hơn vạn trượng, được cầu vồng năm màu và ánh sáng bao phủ. Ngọn núi tỏa ra linh áp khủng bố, mang tính chất như một dị bảo có uy năng lớn và đang bị Linh Vương phong tỏa nghiêm ngặt.","theLucLienQuan":["Linh tộc"],"nguon":["@c2263"]},{"id":"khu-vuc-cam-quanh-nui-phuc-linh","name":"Khu vực Cấm quanh núi Phục Linh","cn":"","capDo":"vuc","parentId":"nui-phuc-linh","blurb":"Khu vực hạn chế rộng ba vạn dặm bao quanh núi Phục Linh.","detail":"Người có tu vi dưới Hợp Thể bị cấm tới gần khu vực này. Tu sĩ từ Hợp Thể trở lên nếu không được Linh Vương đồng ý cũng chỉ có thể đi tới sườn núi.","theLucLienQuan":["Linh tộc"],"nguon":["@c2263"]},{"id":"cong-chao-do-tia","name":"Cổng chào đỏ tía","cn":"","capDo":"khac","parentId":"nui-phuc-linh","blurb":"Cổng lớn tại sườn núi Phục Linh do hai tu sĩ Hợp Thể của Linh tộc trấn giữ.","detail":"Hàn Lập trong trạng thái hóa hư vượt qua cổng mà không bị phát hiện. Mạc Giản Ly đang độn dưới lòng đất lại bị lệnh bài bảy màu ép hiện thân và bị phù lục đỏ thẫm hóa thành hỏa liệm trói lại tại đây.","theLucLienQuan":["Linh tộc"],"nguon":["@c2263"]},{"id":"tu-khi-duong","name":"Tử Khí Đường","cn":"","aliases":["Điện Tử Khí"],"capDo":"khac","parentId":"nui-phuc-linh","blurb":"Điện trên Núi Phục Linh, nơi Linh Vương được nói là đang chờ hai vị khách Đại Thừa đến từ đảo Địa Giao.","detail":"Lão già tóc trắng tiết lộ Linh Vương đã chờ Huyết Nhiên và Hắc Lân tại đây từ lâu.","theLucLienQuan":["Linh tộc"],"nguon":["@c2264"]},{"id":"dao-dia-giao","name":"Đảo Địa Giao","cn":"","aliases":[],"capDo":"khac","parentId":null,"blurb":"Nơi gắn với Huyết Nhiên và Hắc Lân, hai Đại Thừa ngoại tộc được Linh Vương đích thân mời.","detail":"Hai người có thanh danh tại vùng biển trung bộ đại lục và được nhóm thủ vệ Núi Thánh chờ đón theo lệnh Linh Vương.","theLucLienQuan":[],"nguon":["@c2264"]},{"id":"dao-cua-huyet-nhien-va-hac-lan","name":"Đảo của Huyết Nhiên và Hắc Lân","cn":"","capDo":"khac","parentId":null,"blurb":"Hòn đảo đặt bảo khố của hai huynh đệ Huyết Nhiên và Hắc Lân.","detail":"Huyết Nhiên cho biết hai huynh đệ đã mang sạch tài vật trong bảo khố trên đảo theo mình để chuẩn bị đổi lấy Tam Thanh Lôi Tiêu Phù.","theLucLienQuan":[],"nguon":["@c2266"]},{"id":"dai-duong-va-bien-sau","name":"Đại dương và biển sâu","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực tu luyện và tìm kiếm tài nguyên của Huyết Nhiên cùng Hắc Lân.","detail":"Vùng đại dương và biển sâu có nhiều tài nguyên quý hiếm. Huyết Nhiên và Hắc Lân từng phát hiện bảy tám động phủ thượng cổ tại đây và thu được nhiều bảo vật.","theLucLienQuan":[],"nguon":["@c2266"]},{"id":"tieu-tu-la-gioi","name":"Tiểu Tu La Giới","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Một giới diện nhỏ từng xuất hiện trên đại lục Phong Nguyên khoảng hai mươi vạn năm trước. Nơi này có hoàn cảnh tương tự thế giới Tu La thời thượng cổ, vừa hung hiểm vừa giàu tài liệu quý hiếm.","detail":"Các đại tộc từng tranh đoạt Tiểu Tu La Giới và gây ra sai lầm khiến cửa vào bị phá hủy. Dù vậy, Tu La Tâm phối hợp với một pháp trận thượng cổ vẫn có thể truyền tống người vào trong, còn năng lượng của Tu La Tâm giúp chống lực bài xích của giới diện.","theLucLienQuan":[],"nguon":["@c2267","@c2296"]},{"id":"quang-am-ha","name":"Quang Âm Hà","cn":"","capDo":"khac","parentId":null,"blurb":"Dòng sông được hình thành từ những dòng chảy pháp tắc thời gian và được cho là nơi sinh ra Quang Âm Ti.","detail":"Quang Âm Hà khó có khả năng xuất hiện tại một hạ giới như Linh giới. Theo truyền thuyết, những dòng pháp tắc khổng lồ tại Tiên giới có thể hội tụ thành dòng sông này.","theLucLienQuan":[],"nguon":["@c2267"]},{"id":"tu-la-gioi","name":"Tu La giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Giới diện được nhắc tới như nguồn gốc của loài Tu La Thù.","detail":"Tu La Thù tại giới diện này đã có thực lực Nguyên Anh từ thời kỳ ấu trùng và khi trưởng thành có thể đạt tới mức gần Đại Thừa.","theLucLienQuan":[],"nguon":["@c2268"]},{"id":"long-nui-phuc-linh","name":"Lòng núi Phục Linh","cn":"","capDo":"khac","parentId":"nui-phuc-linh","blurb":"Bí địa sâu và tối nằm bên trong núi Phục Linh.","detail":"Nơi này chứa một pháp trận truyền tống bí mật và núi băng khổng lồ đang phong ấn thanh niên áo vàng.","theLucLienQuan":["Linh tộc"],"nguon":["@c2268"]},{"id":"nui-bang-ngan-truong","name":"Núi băng ngàn trượng","cn":"","capDo":"khac","parentId":"long-nui-phuc-linh","blurb":"Khối băng khổng lồ tỏa ánh sáng lam nằm sâu trong lòng núi Phục Linh.","detail":"Núi băng cao hơn ngàn trượng, bị đại phù màu vàng bao phủ hơn nửa. Dưới đáy băng là một thanh niên áo vàng đang hôn mê và bị bùa chú trói chặt.","theLucLienQuan":["Linh tộc"],"nguon":["@c2268"]},{"id":"kim-han-tien-cung-dia-diem","name":"Kim Hàn Tiên Cung","cn":"","capDo":"khac","parentId":"chan-tien-gioi","blurb":"Quần thể cung điện khổng lồ nằm trên các ngọn núi nổi giữa biển sương mù tại Chân Tiên giới.","detail":"Cung điện trung tâm đồ sộ như một tòa thành, có tường vàng, vô số ký hiệu lưu chuyển và cửa chính cao ngàn trượng do vệ sĩ giáp vàng canh giữ. Hơn mười ngọn núi nổi bao quanh khu vực trung tâm.","theLucLienQuan":["Kim Hàn Tiên Cung"],"nguon":["@c2269"]},{"id":"linh-dien-chan-tien-gioi","name":"Linh điền Chân Tiên giới","cn":"","capDo":"khac","parentId":"chan-tien-gioi","blurb":"Những thửa linh điền vuông vức trải rộng trên đại lục Chân Tiên giới.","detail":"Linh điền trồng loại thóc khổng lồ giàu linh khí, được vô số con rối hình nông phu chăm sóc và các đạo đồng điều khiển linh vân tưới nước.","theLucLienQuan":["Kim Hàn Tiên Cung"],"nguon":["@c2269"]},{"id":"bien-suong-mu-tren-dai-luc","name":"Biển sương mù trên đại lục","cn":"","capDo":"khac","parentId":"chan-tien-gioi","blurb":"Tầng sương mù cuồn cuộn ở độ cao vạn trượng phía trên đại lục Chân Tiên giới.","detail":"Biển sương mù dường như bao phủ toàn bộ đại lục. Phía trên có nhiều núi nổi, trong khi linh cầm và linh thú thường xuyên chở người ra vào.","theLucLienQuan":["Kim Hàn Tiên Cung"],"nguon":["@c2269"]},{"id":"dai-nui-noi-kim-han-tien-cung","name":"Dải núi nổi Kim Hàn Tiên Cung","cn":"","capDo":"khac","parentId":"chan-tien-gioi","blurb":"Quần thể gồm hàng trăm ngọn núi lớn nhỏ trôi nổi trên biển sương mù.","detail":"Các ngọn núi phủ kỳ hoa dị thảo, đình đài lầu gác và được nối với nhau bằng những dải cầu vồng. Khu vực trung tâm là nơi tọa lạc của Kim Hàn Tiên Cung.","theLucLienQuan":["Kim Hàn Tiên Cung"],"nguon":["@c2269"]},{"id":"khong-gian-nui-bang","name":"Không gian núi băng","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian bên trong núi băng nơi Linh Vương liên hệ với hình người tí hon đồng thể.","detail":"Phía dưới không gian này đang giam giữ chân hồn của một Kim Tiên để người tí hon luyện hóa. Nơi đây có truyền tống trận giúp Linh Vương rời đi.","theLucLienQuan":[],"nguon":["@c2269"]},{"id":"tieu-nam-chau-gioi","name":"Tiểu Nam Châu Giới","cn":"","capDo":"vuc","parentId":"chan-tien-gioi","blurb":"Một khu vực từng liên hệ với hàng trăm tiểu Linh giới. Sau một biến cố khủng khiếp, tọa độ các giới trực thuộc bị dịch chuyển khiến Chân Tiên giới mất liên lạc.","detail":"Việc tọa độ bị lệch khiến Hàng Tiên Đài không thể truyền người xuống khu vực này. Tu sĩ trong các giới diện thất lạc cũng khó phi thăng lên Chân Tiên giới, còn phản đồ Cửu Nguyên Quan được suy đoán đang ở một trong số đó.","theLucLienQuan":["Cửu Nguyên Quan","Kim Hàn Tiên Cung"],"nguon":["@c2270"]},{"id":"cac-tieu-linh-gioi-thuoc-tieu-nam-chau-gioi","name":"Các tiểu Linh giới thuộc Tiểu Nam Châu Giới","cn":"","capDo":"gioi-dien","parentId":"tieu-nam-chau-gioi","blurb":"Hàng trăm tiểu Linh giới từng thuộc phạm vi quản lý của Tiểu Nam Châu Giới. Tọa độ của chúng đã bị dịch chuyển sau một biến cố lớn.","detail":"Cách Minh chỉ xác định phản đồ đang ở một trong các tiểu Linh giới này mà chưa tìm được giới cụ thể hay tọa độ chuẩn xác. Vì vậy Hàng Tiên Đài không thể đưa người từ Tiên giới xuống truy bắt.","theLucLienQuan":["Cửu Nguyên Quan","Kim Hàn Tiên Cung"],"nguon":["@c2270"]},{"id":"cuu-nguyen-quan-dia-diem","name":"Cửu Nguyên Quan","cn":"","capDo":"khac","parentId":null,"blurb":"Địa điểm của thế lực Cửu Nguyên Quan, nơi một đệ tử đứng đầu cùng thế hệ từng mang nhiều bảo vật bỏ trốn.","detail":"Cửu Nguyên Quan đang truy tìm tên phản đồ cùng vật trọng yếu mà hắn mang đi. Mã Lương, Cách Minh, Chúc sư điệt và Ngô sư điệt đều có quan hệ với nơi này.","theLucLienQuan":["Cửu Nguyên Quan"],"nguon":["@c2271"]},{"id":"khu-rung-cay-than-trang","name":"Khu rừng cây thân trắng","cn":"","capDo":"khac","parentId":"tieu-tu-la-gioi","blurb":"Khu rừng trong Tiểu Tu La giới nơi Hàn Lập tỉnh lại sau cuộc truyền tống vượt giới.","detail":"Rừng có những thân cây màu trắng, cây bụi và cỏ dại đều héo úa. Hàn Lập không tìm thấy Mạc Giản Ly, Huyết Nhiên hay Hắc Lân tại đây và phát hiện dị trạng khi nhìn lên trời.","theLucLienQuan":[],"nguon":["@c2271"]},{"id":"rung-go-trang","name":"Rừng gỗ trắng","cn":"","capDo":"khac","parentId":"tieu-tu-la-gioi","blurb":"Khu rừng tại tiểu Tu La giới nơi Hàn Lập chạm trán một dị thú kịch độc.","detail":"Dị thú bị Hàn Lập chém nát tại đây có hình thái pha trộn giữa yêu trùng và yêu thú. Chất độc tỏa ra từ thi thể khiến cây cỏ cùng nhiều quái trùng hình bọ ngựa quanh đó nhanh chóng mất hết sinh khí.","theLucLienQuan":[],"nguon":["@c2272"]},{"id":"hang-dong-giua-lop-bun-dat","name":"Hang động giữa lớp bùn đất","cn":"","capDo":"khac","parentId":"tieu-tu-la-gioi","blurb":"Hang động mà Huyết Nhiên và Hắc Lân tìm đến nhờ cảm ứng huyết mạch.","detail":"Bên trong hang có bốn con nhện gai xanh chứ không phải Tu La chu. Sau khi giết chúng, Huyết Nhiên lấy được hai viên đá vàng nhạt từ bùn đất.","theLucLienQuan":[],"nguon":["@c2272"]},{"id":"ngon-nui-nho-co-bien-doi","name":"Ngọn núi nhỏ có biển dơi","cn":"","capDo":"khac","parentId":"tieu-tu-la-gioi","blurb":"Khu vực Hàn Lập bị một biển dơi đỏ như máu chặn đường.","detail":"Đàn dơi do một cá thể lớn mang hoa văn vàng và con mắt thứ ba dẫn đầu. Cả bầy hợp nhất dao động vô thanh thành một luồng sóng trong suốt khổng lồ để tấn công Hàn Lập.","theLucLienQuan":[],"nguon":["@c2272"]},{"id":"thung-lung-da-den","name":"Thung lũng đá đen","cn":"","capDo":"khac","parentId":"tieu-tu-la-gioi","blurb":"Một thung lũng đá đen nằm trong khu vực Hàn Lập tìm kiếm Tu La Thù.","detail":"Tại đây, Hàn Lập phát hiện hang thú chứa những thi thể khô héo cùng sợi tơ mang lực lượng thời gian, từ đó xác định dấu vết hoạt động của Tu La Thù.","theLucLienQuan":[],"nguon":["@c2273"]},{"id":"hang-thu-duoi-thung-lung","name":"Hang thú dưới thung lũng","cn":"","capDo":"khac","parentId":"thung-lung-da-den","blurb":"Một hang thú kín đáo nằm trong thung lũng đá đen.","detail":"Hang chứa nhiều xác quái thú nửa người nửa gấu đã khô héo như chết già nhưng không có thương tích bên ngoài. Bên dưới các thi thể có những sợi tơ trong suốt mang lực lượng thời gian.","theLucLienQuan":[],"nguon":["@c2273"]},{"id":"ho-che-giau-duong-ham","name":"Hồ phía dưới đường hầm","cn":"","capDo":"khac","parentId":"thung-lung-da-den","blurb":"Một hồ nước nằm không xa thung lũng đá đen và chứa nhiều quái ngư.","detail":"Lớp đá xanh nhạt dưới đáy hồ cản trở thần niệm và che giấu lối vào đường hầm sâu. Hàn Lập dùng lôi điện tiêu diệt quái ngư trước khi tiến vào.","theLucLienQuan":[],"nguon":["@c2273"]},{"id":"duong-ham-sau-duoi-dat","name":"Đường hầm sâu dưới đất","cn":"","capDo":"khac","parentId":"ho-che-giau-duong-ham","blurb":"Một đường hầm thô sơ chỉ vừa một người đi qua, ẩn sâu dưới lớp đá xanh nhạt ở đáy hồ.","detail":"Đường hầm dốc xuống gần vạn trượng, có sợi tơ trong suốt bám bên trong và dẫn tới khu vực có sóng nhiệt cực mạnh cùng hồ dung nham.","theLucLienQuan":[],"nguon":["@c2273"]},{"id":"can-hoa-chi-dia","name":"Càn Hỏa Chi Địa","cn":"","capDo":"vuc","parentId":"tieu-tu-la-gioi","blurb":"Khu vực cực nóng có hồ dung nham, nơi một chi Không Ngư sinh sống.","detail":"Không Ngư Nhất Tộc tại đây bị phe cô gái khống chế và khai thác làm nguồn tế phẩm.","theLucLienQuan":["Không Ngư Nhất Tộc"],"nguon":["@c2274"]},{"id":"ho-dung-nham-khong-ngu","name":"Hồ dung nham của Không Ngư","cn":"","capDo":"khac","parentId":"can-hoa-chi-dia","blurb":"Hồ dung nham cực nóng nơi một chi Không Ngư ẩn cư.","detail":"Ráng lửa từ hồ có thể được Không Ngư hấp thu để thi triển Dục Hỏa thuật. Hàn Lập phái Phệ Kim Trùng Vương xuống đây giám sát tộc đàn.","theLucLienQuan":["Không Ngư Nhất Tộc"],"nguon":["@c2274"]},{"id":"hap-coc-bi-an-qua-vang","name":"Hạp cốc bí ẩn","cn":"","capDo":"khac","parentId":"tieu-tu-la-gioi","blurb":"Một hạp cốc nằm trên đường cô gái trở về sơn mạch.","detail":"Cô gái ghé qua nơi này và hái hơn mười quả màu vàng chưa rõ tên cùng công dụng.","theLucLienQuan":[],"nguon":["@c2274"]},{"id":"son-mach-o-nhen-tu-la-nghi-van","name":"Sơn mạch nơi cô gái trở về","cn":"","capDo":"vuc","parentId":"tieu-tu-la-gioi","blurb":"Một sơn mạch rộng lớn dường như kéo dài vô tận, nơi cô gái trở về sau khi lấy tế phẩm.","detail":"Bảy tám quái cầm lớn bay ra nghênh đón cô gái tại rìa sơn mạch. Một luồng thần niệm khủng bố từ sâu bên trong quét xét toàn bộ khu vực giáp ranh và lướt sát vị trí Hàn Lập đang ẩn nấp.","theLucLienQuan":["Tu La nhện"],"nguon":["@c2274"]},{"id":"thien-chu-thanh","name":"Thiên Chu thành","cn":"","capDo":"thanh","parentId":"tieu-tu-la-gioi","blurb":"Thạch thành màu xanh nằm sâu trong dãy núi của Tiểu Tu La Giới, không có cổng và được Đại Hóa Bạch Liên Cấm chế bảo vệ. Bên trong thành có nhiều tồn tại sở hữu thần niệm cấp Đại Thừa.","detail":"Thiên Chu thành nằm sau một bình nguyên, có phạm vi hơn mười dặm và tường thành cao gần mấy trăm trượng. Thành gần như không có bóng người bên ngoài, nhưng được bảo vệ bằng cấm chế có nguồn gốc từ một đại tộc nổi tiếng tại Linh giới và ẩn giấu nhiều cường giả cấp Đại Thừa.","theLucLienQuan":["Tu La nhện tại tiểu Tu La giới"],"nguon":["@c2275"]},{"id":"day-nui-quanh-thien-chu-thanh","name":"Dãy núi quanh Thiên Chu thành","cn":"","capDo":"vuc","parentId":"tieu-tu-la-gioi","blurb":"Dãy núi rộng lớn bao quanh lối tới Thiên Chu thành. Nơi đây có nhiều dị thú mạnh bị Tu La nhện thu phục và tổ chức thành các đội tuần tra.","detail":"Hàn Lập tiến sâu ít nhất trăm vạn dặm qua dãy núi này trước khi nhìn thấy Thiên Chu thành. Trên đường có dị thú cấp Hóa Thần, Luyện Hư và hai quái cầm cấp Hợp Thể đảm nhiệm việc tuần tra, canh gác.","theLucLienQuan":["Tu La nhện tại tiểu Tu La giới"],"nguon":["@c2275"]},{"id":"sao-huyet-tu-la-nhen-trong-day-nui","name":"Sào huyệt Tu La nhện trong dãy núi","cn":"","capDo":"khac","parentId":"tieu-tu-la-gioi","blurb":"Nơi Tộc Mẫu họ La và lão giả họ Dịch trú đóng cùng lực lượng Tu La nhện.","detail":"Hàn Lập đã thăm dò thực lực đại khái tại đây, bí mật để lại hậu thủ giám sát rồi rút ra ngoài khoảng mười vạn dặm.","theLucLienQuan":["Tu La nhện"],"nguon":["@c2277"]},{"id":"can-hoa-tri","name":"Càn Hỏa trì","cn":"","capDo":"khac","parentId":"tieu-tu-la-gioi","blurb":"Khu vực có Càn Hỏa, gắn trực tiếp với điều kiện sinh tồn của Không Ngư Nhất Tộc.","detail":"Sau khi từ bỏ phương án cưỡng ép Không Ngư Nhất Tộc di dời, Tộc Mẫu họ La và lão giả họ Dịch quyết định phái người tới giám sát nơi này.","theLucLienQuan":["Không Ngư Nhất Tộc","Tu La nhện"],"nguon":["@c2277"]},{"id":"ho-nuoc-co-rong-vang","name":"Hồ nước có rong vàng","cn":"","capDo":"khac","parentId":"tieu-tu-la-gioi","blurb":"Hồ nước có cây rong màu hoàng kim mang ba dị quả đỏ, thu hút nhiều ngư thú tranh đoạt.","detail":"Hàn Lập chứng kiến cự quy giao chiến với rắn đen hai đầu tại đây, nhận ra huyết mạch Huyền Vũ trong cự quy rồi bắt sống nó.","theLucLienQuan":[],"nguon":["@c2277"]},{"id":"dinh-nui-khong-ten","name":"Đỉnh núi không tên","cn":"","capDo":"khac","parentId":"tieu-tu-la-gioi","blurb":"Một địa điểm kín đáo được bốn tu sĩ Đại Thừa chọn làm nơi hội họp.","detail":"Hàn Lập, Mạc Giản Ly, Huyết Nhiên và Hắc Lân tập trung tại đỉnh núi này để trao đổi tình báo, phân chia đối thủ và thống nhất cách xử lý tinh hạch Tu La Thù trước cuộc tiến công.","theLucLienQuan":[],"nguon":["@c2279"]},{"id":"dinh-nui-noi-nhom-han-lap-nghi-chan","name":"Đỉnh núi nơi nhóm Hàn Lập nghỉ chân","cn":"","capDo":"khac","parentId":"tieu-tu-la-gioi","blurb":"Đỉnh núi nơi nhóm Hàn Lập tạm dừng và bị phân thân của thanh niên áo vàng rình trộm.","detail":"Khu vực quanh nơi nghỉ chân được bố trí cấm chế ngăn nghe lén. Hắc Lân phát hiện phân thân áo vàng tại đây, nhưng đối phương tự bạo trước khi bị khống chế hoàn toàn.","theLucLienQuan":[],"nguon":["@c2280"]},{"id":"khu-rung-cach-dinh-nui-muoi-van-dam","name":"Khu rừng cách đỉnh núi mười vạn dặm","cn":"","capDo":"khac","parentId":"tieu-tu-la-gioi","blurb":"Khu rừng nơi bản thể thanh niên áo vàng ẩn náu sau khi phái phân thân đi do thám.","detail":"Bản thể thanh niên áo vàng ẩn trong một đại thụ tại đây, cách nơi nhóm Hàn Lập nghỉ chân khoảng mười vạn dặm. Hắn theo dõi hướng phi thuyền rời đi rồi dùng mộc bài truyền tin về Thạch Thành.","theLucLienQuan":["Tu La Thù nhất tộc"],"nguon":["@c2280"]},{"id":"thach-thanh","name":"Thạch Thành","cn":"","aliases":["Hang ổ Tu La Thù","Sào huyệt Tu La Thù","Thạch Thành của Tu La Thù"],"capDo":"thanh","parentId":"tieu-tu-la-gioi","blurb":"Sào huyệt của Tu La Thù nhất tộc và mục tiêu mà nhóm Hàn Lập đang áp sát.","detail":"Trong một mật thất của Thạch Thành, Tộc Mẫu họ La và lão già họ Dịch nhận tin về nhóm Đại Thừa ngoại lai. Hai người tổ chức triệu hồi thuộc hạ, Âm Thi và linh sủng, đồng thời cân nhắc mời thêm viện thủ.","theLucLienQuan":["Tu La Thù nhất tộc"],"nguon":["@c2280"]},{"id":"dia-am-dam-lay","name":"Địa Âm Đầm Lầy","cn":"","capDo":"khac","parentId":"tieu-tu-la-gioi","blurb":"Đầm lầy nơi chín Âm Thi của Tu La Thù nhất tộc bị đặt dưới cấm chế.","detail":"Tộc Mẫu họ La đã phái người tới giải trừ cấm chế cho chín Âm Thi. Theo dự tính, chúng cần tối đa hai ngày để trở về Thạch Thành.","theLucLienQuan":["Tu La Thù nhất tộc"],"nguon":["@c2280"]},{"id":"huyet-tri","name":"Huyết Trì","cn":"","capDo":"khac","parentId":"tieu-tu-la-gioi","blurb":"Địa điểm đang có một nhân vật thần bí được lão già họ Dịch xem là hậu thủ.","detail":"Lão già họ Dịch yêu cầu báo tin cho người đang ở trong Huyết Trì. Thần thông của nhân vật này có thể được nhờ tới nếu cuộc đối đầu phát sinh biến cố ngoài dự liệu.","theLucLienQuan":["Tu La Thù nhất tộc"],"nguon":["@c2280"]},{"id":"son-mach-cua-thach-thanh-cu","name":"Sơn mạch của Thạch Thành cũ","cn":"","capDo":"vuc","parentId":"tieu-tu-la-gioi","blurb":"Sơn mạch từng là nơi Thạch Thành của Tu La Thù ẩn dưới lòng đất.","detail":"Sau khi Phi Hành Cấm Chế đưa thành trì rời đi, vị trí cũ chỉ còn lại một hố lớn đen xì. Phi thuyền của đoàn Hàn Lập bay qua khu vực này trong quá trình truy đuổi.","theLucLienQuan":["Tu La Thù nhất tộc"],"nguon":["@c2281"]},{"id":"cao-nguyen-dat-vang","name":"Cao nguyên đất vàng","cn":"","capDo":"vuc","parentId":"tieu-tu-la-gioi","blurb":"Một cao nguyên đất vàng rộng lớn, nhiều gió cát và không thấy giới hạn.","detail":"Tu La Thù nhất tộc chuyển Thạch Thành tới đây rồi dùng cấm chế giấu toàn bộ thành trì trong một khối đất cát. Hắc Lân dùng thần niệm phát hiện mục tiêu cách đoàn người hơn vạn dặm.","theLucLienQuan":["Tu La Thù nhất tộc"],"nguon":["@c2281"]},{"id":"mat-that-duoi-thach-thanh","name":"Mật thất dưới Thạch Thành","cn":"","capDo":"khac","parentId":"thach-thanh","blurb":"Mật thất bí mật nằm dưới Thạch Thành, được nhiều tầng cấm chế bảo vệ nghiêm mật.","detail":"Một kẻ chưa rõ danh tính cầm vật phẩm kim loại màu đen hình côn bổng trong mật thất. Bên ngoài gian phòng đặt hơn mười huyết sắc viên cầu phong chứa những quái vật có khí tức khủng bố.","theLucLienQuan":["Tu La Thù nhất tộc"],"nguon":["@c2287"]},{"id":"ben-ngoai-man-sang-thach-thanh","name":"Bên ngoài màn sáng Thạch Thành","cn":"","capDo":"khac","parentId":"thach-thanh","blurb":"Khu vực ngay ngoài màn sáng phòng hộ của Thạch Thành.","detail":"Anh Nhi một mình ra khu vực này để trực tiếp đối diện Hàn Lập, Huyết Nhiên và Hắc Lân, dù cả ba người đều là tu sĩ Đại Thừa.","theLucLienQuan":["Tu La Thù tộc"],"nguon":["@c2291"]},{"id":"dam-lanh-vo-cung","name":"Đầm lạnh vô cùng","cn":"","capDo":"khac","parentId":null,"blurb":"Đầm lạnh nơi thánh vật Không Ngư Tộc đang chìm sâu.","detail":"Điều kiện bên trong khắc nghiệt đến mức ngay cả tồn tại Đại Thừa cũng không thể tự mình tiến sâu. Nhóm Hàn Lập được đề nghị hỗ trợ lấy thánh vật tại đây.","theLucLienQuan":["Tu La Thù tộc","Không Ngư Tộc"],"nguon":["@c2292"]},{"id":"quan-dao-chien-truong-thuong-co","name":"Quần đảo chiến trường thượng cổ","cn":"","capDo":"khac","parentId":null,"blurb":"Một quần đảo giữa biển từng là chiến trường thời thượng cổ, nơi Hàn Đàm được cất giấu.","detail":"Cảnh quan và Thiên Địa Nguyên Khí trên các đảo phân bố khác thường. Nhiều trận pháp và cấm chế không trọn vẹn còn lưu lại, nhưng phần lớn chỉ còn chưa tới một hai phần trăm hiệu lực ban đầu.","theLucLienQuan":["Tu La Thù tộc"],"nguon":["@c2293"]},{"id":"dao-bang","name":"Đảo băng","cn":"","capDo":"khac","parentId":"quan-dao-chien-truong-thuong-co","blurb":"Hòn đảo rộng khoảng vạn dặm, phủ đầy băng tuyết và có một ngọn núi khổng lồ.","detail":"Hàn Đàm nằm trong một sơn cốc trên đảo. Đoàn Hàn Lập được phía Tu La Thù dẫn tới đây sau khi vượt qua các cấm chế còn sót lại trong quần đảo.","theLucLienQuan":["Tu La Thù tộc"],"nguon":["@c2293"]},{"id":"han-dam","name":"Hàn Đàm","cn":"","capDo":"khac","parentId":"son-coc-tuyet","blurb":"Đầm lạnh bị ảo trận che giấu và được phong kín dưới đài Huyền Băng trong sơn cốc tuyết.","detail":"Hàn khí từ Hàn Đàm được pháp trận sử dụng nhiều bảo vật thuần dương trấn áp. Phía Tu La Thù cảnh báo rằng nếu mở phong ấn mà không kiềm chế, vùng biển quanh quần đảo có thể bị đóng băng.","theLucLienQuan":["Tu La Thù tộc"],"nguon":["@c2293","@c2296"]},{"id":"son-coc-tuyet","name":"Sơn cốc tuyết","cn":"","capDo":"khac","parentId":"dao-bang","blurb":"Sơn cốc phủ tuyết trên đảo băng, nơi đặt phong ấn Hàn Đàm.","detail":"Bên trong sơn cốc có pháp trận lớn, nhiều tinh thạch đủ màu và đài Huyền Băng hình trụ. Toàn bộ khu vực ban đầu bị một ảo trận che giấu.","theLucLienQuan":["Tu La Thù tộc"],"nguon":["@c2293"]},{"id":"sao-huyet-xa-khap-tu","name":"Sào huyệt Xa Khấp Tử","cn":"","capDo":"khac","parentId":"tieu-tu-la-gioi","blurb":"Sào huyệt của Thượng Cổ hung thú Xa Khấp Tử nằm trong Tiểu Tu La giới.","detail":"Vị trí chính xác của sào huyệt được ghi trong ngọc giản do Tộc mẫu Tu La Thù giao cho Huyết Nhiên để đổi lấy thù lao.","theLucLienQuan":[],"nguon":["@c2296"]},{"id":"cu-dao","name":"Cự đảo chứa Hàn Đàm","cn":"","capDo":"khac","parentId":"tieu-tu-la-gioi","blurb":"Cự đảo là nơi có sơn cốc tuyết và Hàn Đàm.","detail":"Sau khi Huyết Nhiên, Hắc Lân và Mạc Giản Ly lần lượt rời đi, Hàn Lập một mình quay lại Cự đảo để tiếp cận Hàn Đàm.","theLucLienQuan":[],"nguon":["@c2296"]},{"id":"can-hoa-dia","name":"Càn Hỏa Địa","cn":"","capDo":"khac","parentId":"tu-la-gioi","blurb":"Khu vực cư trú của Không Ngư Tộc và là nơi Hàn Lập tới sau khi lấy được Sơn Hải Châu.","detail":"Hàn Lập bay về Càn Hỏa Địa sau khi rời Hàn Đàm. Cuối chương, hắn xuất hiện trong tầng đất bên dưới hồ dung nham tại khu vực này.","theLucLienQuan":["Không Ngư Tộc"],"nguon":["@c2297"]},{"id":"ho-dung-nham","name":"Hồ dung nham","cn":"","capDo":"khac","parentId":"can-hoa-dia","blurb":"Hồ dung nham tại Càn Hỏa Địa, bên dưới có các tầng đất mà Hàn Lập có thể hiện thân.","detail":"Hàn Lập xuất hiện trong tầng đất trên cùng bên dưới hồ dung nham và nhíu mày sau khi quan sát xung quanh.","theLucLienQuan":["Không Ngư Tộc"],"nguon":["@c2297"]},{"id":"khong-gian-cu-tru-cua-khong-ngu-toc","name":"Không gian cư trú của Không Ngư Tộc","cn":"","capDo":"gioi-nho","parentId":"ho-dung-nham","blurb":"Nơi cư trú bí mật của Không Ngư Tộc nằm phía sau màn sáng màu lam dưới hồ dung nham tại Càn Hỏa Địa.","detail":"Không gian này rộng khoảng hơn mười dặm vuông, có chưa tới một trăm kiến trúc hình tam giác khắc văn tự cổ sơ. Toàn bộ dân cư chỉ khoảng năm sáu trăm người, phần lớn là người già, phụ nữ và trẻ em.","theLucLienQuan":["Không Ngư Tộc"],"nguon":["@c2298"]},{"id":"huyet-thien-dai-luc","name":"Huyết Thiên Đại Lục","cn":"","capDo":"chau","parentId":"linh-gioi","blurb":"Một đại lục thuộc Linh Giới, nơi thân ảnh trong suốt từ Tiên Giới giáng xuống.","detail":"Tại một khu vực dưới lòng đất của Huyết Thiên Đại Lục có thượng cổ tế đàn được quang trận ngũ sắc kích hoạt, trở thành điểm giáng lâm của một người chưa rõ danh tính từ Tiên Giới.","theLucLienQuan":[],"nguon":["@c2299","@c2325","@c2353","@c2384"],"aliases":["Đại lục Huyết Thiên"]},{"id":"thuong-co-te-dan-duoi-dat","name":"Thượng cổ tế đàn dưới đất","cn":"","capDo":"khac","parentId":"huyet-thien-dai-luc","blurb":"Một tế đàn cổ bị chôn dưới lòng đất tại Huyết Thiên Đại Lục.","detail":"Ba động không gian tại đây phá tung bùn đất và đá vụn, sau đó quang trận ngũ sắc xuất hiện và đưa một thân ảnh trong suốt từ Tiên Giới xuống Linh Giới.","theLucLienQuan":[],"nguon":["@c2299"]},{"id":"vung-dat-den-hoang-vang","name":"Vùng đất đen hoang vắng","cn":"","capDo":"khac","parentId":"tieu-tu-la-gioi","blurb":"Vùng đất chết nơi thanh niên áo đen xuất hiện sau khi rời quang trận dưới lòng đất.","detail":"Mặt đất đen chỉ có cỏ dại thấp bé, không có cây lớn hay tiếng côn trùng. Thanh niên áo đen thử thi pháp tại đây rồi dò tìm phương hướng có nhiều sinh linh nhất.","theLucLienQuan":["Quan Trung Hội"],"nguon":["@c2300"]},{"id":"mat-that-cua-toc-truong-khong-ngu","name":"Mật thất của tộc trưởng Không Ngư","cn":"","capDo":"khac","parentId":"khong-gian-cu-tru-cua-khong-ngu-toc","blurb":"Mật thất nơi Hàn Lập nghiên cứu bí thuật và luyện hóa Sơn Hải Châu.","detail":"Mật thất nằm trong một kiến trúc hình tam giác có cổng đá xanh, bên trong chứa vật dụng, thẻ tre, hộp ngọc, bình và lò luyện đan. Hàn Lập đặt cấm chế rồi luyện hóa Sơn Hải Châu tại đây trong hai ngày hai đêm.","theLucLienQuan":["Không Ngư Tộc"],"nguon":["@c2300"]},{"id":"quang-truong-khong-ngu-toc","name":"Quảng trường Không Ngư Tộc","cn":"","capDo":"khac","parentId":"khong-gian-cu-tru-cua-khong-ngu-toc","blurb":"Nơi toàn bộ Không Ngư Tộc tập hợp để lập huyết thệ phụng dưỡng Hàn Lập.","detail":"Tộc trưởng cùng năm trăm lẻ một tộc nhân tập trung tại quảng trường, đồng loạt lấy máu lập lời thề. Huyết khí của họ hợp thành một phù văn đỏ lớn trên bầu trời.","theLucLienQuan":["Không Ngư Tộc"],"nguon":["@c2300"]},{"id":"noi-dong-thien-son-hai-chau","name":"Nội động thiên Sơn Hải Châu","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian nội bộ rộng lớn của Sơn Hải Châu, có mặt nước xanh biếc và một quần đảo ở trung tâm.","detail":"Hơn một nửa nội động thiên là mặt nước. Quần đảo trung tâm gồm ba đảo lớn và bốn đảo nhỏ, được Hàn Lập chọn làm nơi tạm cư cho Không Ngư Tộc.","theLucLienQuan":["Không Ngư Tộc"],"nguon":["@c2301","@c2303"],"aliases":["Động Thiên Sơn Hải Châu"]},{"id":"ngon-nui-da-hoang-vu","name":"Ngọn núi đá hoang vu","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Điểm Hàn Lập xuất hiện sau khi rời Tiểu Tu La Giới và truyền tống trở về Linh Giới.","detail":"Ngọn núi nằm không quá xa tọa độ được thiết lập trước chuyến đi. Hàn Lập chờ tại đây khoảng ba canh giờ cho tới khi Mạc Giản Ly tìm đến.","theLucLienQuan":[],"nguon":["@c2301"]},{"id":"phuc-linh-son","name":"Phục Linh Sơn","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Đích đến được Mạc Giản Ly gọi tên khi cùng Hàn Lập lên đường gặp Linh Vương.","detail":"Hàn Lập và Mạc Giản Ly quyết định lập tức tới Phục Linh Sơn vì lo Huyết Nhiên và Hắc Lân sẽ đổi hết số Lôi Tiêu phù trước họ.","theLucLienQuan":["Linh tộc"],"nguon":["@c2301"]},{"id":"dao-cu-tru-cua-khong-ngu-toc","name":"Đảo cư trú của Không Ngư Tộc","cn":"","aliases":[],"capDo":"khac","parentId":"noi-dong-thien-son-hai-chau","blurb":"Một đảo nhỏ trong Sơn Hải Châu được Không Ngư Tộc chọn làm nơi định cư.","detail":"Hòn đảo vốn hoang vắng nhưng đã xuất hiện nhiều kiến trúc mới có hình tam giác, trở thành nơi tập trung của toàn bộ tộc nhân.","theLucLienQuan":["Không Ngư Tộc"],"nguon":["@c2303"]},{"id":"lanh-dia-nhan-toc","name":"Lãnh địa Nhân Tộc","cn":"","aliases":[],"capDo":"vuc","parentId":null,"blurb":"Khu vực của Nhân Tộc mà đoàn Hàn Lập trở lại sau hành trình kéo dài vài tháng.","detail":"Mặc Linh Thánh Thuyền bình an đưa đoàn Hàn Lập trở về nơi đây. Ngay sau khi đến, mọi người nhận được một tin tức gây kinh hãi nhưng nội dung chưa được tiết lộ.","theLucLienQuan":["Nhân Tộc"],"nguon":["@c2303"]},{"id":"dai-dien-truyen-tong-tran-thien-uyen-thanh","name":"Đại điện truyền tống trận Thiên Uyên Thành","cn":"","capDo":"khac","parentId":"thien-uyen-thanh","blurb":"Đại điện đặt truyền tống trận tại Thiên Uyên Thành, nơi đoàn Hàn Lập nhận tin Ngao Khiếu sắp độ thiên kiếp.","detail":"Sau khi nghe nguyên nhân Ngao Khiếu phải độ kiếp sớm, đoàn Hàn Lập lập tức sử dụng một tòa truyền tống trận tại đây để tiếp tục lên đường.","theLucLienQuan":["Thiên Uyên Thành"],"nguon":["@c2304"]},{"id":"hong-van-coc","name":"Hồng Vân cốc","cn":"","capDo":"khac","parentId":null,"blurb":"Sơn cốc cách Thánh Đảo mười vạn dặm, nơi Ngao Khiếu tiến hành thiên kiếp cuối cùng.","detail":"Các trưởng lão Thánh Đảo tới đây hộ pháp, nhưng Ngao Khiếu vẫn không vượt qua được thiên kiếp và chỉ để lại linh hạch cùng hai bảo vật hộ thân không trọn vẹn.","theLucLienQuan":["Thánh Đảo"],"nguon":["@c2304"]},{"id":"hon-dao-nho-o-sau-trong-bien","name":"Hòn đảo nhỏ ở sâu trong biển","cn":"","capDo":"khac","parentId":"lanh-dia-nhan-toc","blurb":"Hòn đảo hẻo lánh ngoài biển, có linh khí tinh thuần và lưỡng nghi lực tự nhiên bao phủ phân nửa hải vực.","detail":"Hải Đại Thiếu tìm được nơi này sau khi thăm dò hơn nửa lãnh địa hai tộc. Hàn Lập chọn đảo làm động phủ mới cho bản thân và môn hạ.","theLucLienQuan":["Nhân tộc","Yêu tộc"],"nguon":["@c2304"]},{"id":"vo-nhai-hai","name":"Vô Nhai Hải","cn":"","capDo":"vuc","parentId":null,"blurb":"Vùng biển rộng nằm giữa địa vực Nhân tộc và Yêu tộc.","detail":"Vô Nhai Hải chứa một quần đảo gồm hàng trăm đảo lớn nhỏ. Các Từ Mạch trong vùng dường như tập trung tại quần đảo này, tạo điều kiện để Hàn Lập thiết lập mạng lưới Lưỡng Nghi Vạn Dẫn Đại Trận.","theLucLienQuan":["Nhân tộc","Yêu tộc","Môn hạ Hàn Lập tại Nguyên Hợp Đảo"],"nguon":["@c2305"]},{"id":"quan-dao-vo-nhai-hai","name":"Quần đảo Vô Nhai Hải","cn":"","capDo":"khac","parentId":"vo-nhai-hai","blurb":"Quần đảo gồm hàng trăm đảo lớn nhỏ trong Vô Nhai Hải.","detail":"Nguyên Hợp Đảo là đảo trung tâm của quần đảo. Nhiều đảo khác cũng có Từ Mạch, cho phép bố trí các phiên bản đơn giản của Lưỡng Nghi Vạn Dẫn Đại Trận để hô ứng với đại trận chính.","theLucLienQuan":["Môn hạ Hàn Lập tại Nguyên Hợp Đảo"],"nguon":["@c2305"]},{"id":"nguyen-hop-dao","name":"Nguyên Hợp Đảo","cn":"","capDo":"khac","parentId":"quan-dao-vo-nhai-hai","blurb":"Hòn đảo khổng lồ chu vi hàng vạn dặm, giữ vị trí trung tâm quần đảo Vô Nhai Hải và trở thành căn cơ mới của Hàn Lập.","detail":"Dưới đảo có các địa mạch Từ Quang lớn dùng làm căn cơ cho Lưỡng Nghi Vạn Dẫn Đại Trận. Sau ba năm xây dựng, trên đảo đã có động phủ, điện vũ, cấm chế, linh cầm dị thú và khôi lỗi tuần tra.","theLucLienQuan":["Nhân tộc","Yêu tộc","Môn hạ Hàn Lập tại Nguyên Hợp Đảo"],"nguon":["@c2305","@c2405"]},{"id":"bich-lam-tieu-truc","name":"Bích Lâm Tiểu Trúc","cn":"","aliases":["Bích Nguyên Tiểu Trúc"],"capDo":"khac","parentId":null,"blurb":"Nơi ở được bảo vệ bằng cấm chế của Tam Toàn đạo nhân. Hoàng Nguyên Tử dùng Cửu Huyễn Như Ý Môn để xâm nhập và bàn kế hoạch đối phó Thanh Nguyên Tử.","detail":"Tam Toàn phát hiện Hoàng Nguyên Tử đã xuất hiện trong Bích Lâm Tiểu Trúc dù nơi này có cấm chế bảo vệ. Hoàng Nguyên Tử thừa nhận nếu phá giải theo cách thông thường thì không thể hoàn thành trong thời gian ngắn.","theLucLienQuan":[],"nguon":["@c2306"]},{"id":"thuy-ma-chi-dia","name":"Thủy Ma Chi Địa","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Địa điểm trong Ma Giới nơi Viên Phi cùng một số người từng bị vây.","detail":"Viên Phi từng bị vây tại đây trong biến cố liên quan Minh Trùng Chi Mẫu và được Hàn Lập cứu thoát.","theLucLienQuan":[],"nguon":["@c2307"]},{"id":"dong-phu-viet-long","name":"Động phủ Việt Long","cn":"","capDo":"khac","parentId":"khu-vuc-phi-linh-toc","blurb":"Nơi ở của Việt Long trong lãnh địa Phi Linh Tộc.","detail":"Động phủ nằm cách nơi Việt Long gặp Hàn Lập hơn một canh giờ phi hành bằng độn tốc Đại Thừa. Việt Long dẫn Hàn Lập tới đây sau khi nhận ra thân phận của ông.","theLucLienQuan":["Phi Linh Tộc"],"nguon":["@c2307"]},{"id":"bon-dia-thach-thap","name":"Bồn địa thạch tháp","cn":"","capDo":"khac","parentId":"dong-phu-viet-long","blurb":"Bồn địa được núi xanh bao quanh, có một thạch tháp khổng lồ nằm ở trung tâm.","detail":"Thạch tháp cao hơn nghìn trượng và có hơn trăm tầng. Các kiến trúc khác đều nằm cách tháp ngoài mười dặm, tạo thành một khu vực biệt lập khác thường.","theLucLienQuan":["Phi Linh Tộc"],"nguon":["@c2307"]},{"id":"mot-trong-bay-dai-dong-phu-cua-viet-long","name":"Một trong bảy đại động phủ của Việt Long","cn":"","capDo":"khac","parentId":null,"blurb":"Một trong bảy đại động phủ của Việt Long, nằm giữa thung lũng có đông đảo Phi Linh tộc nhân sinh sống và hoạt động.","detail":"Động phủ gồm quần thể kiến trúc dày đặc trong thung lũng và một ngọn cự tháp làm nơi Việt Long tiếp đãi Hàn Lập.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c2308"]},{"id":"cu-thap-trong-dong-phu-viet-long","name":"Cự tháp trong động phủ Việt Long","cn":"","capDo":"khac","parentId":"mot-trong-bay-dai-dong-phu-cua-viet-long","blurb":"Ngọn tháp lớn trong động phủ Việt Long, có lối vào trên đỉnh và đại sảnh hoa lệ bên trong.","detail":"Việt Long đưa Hàn Lập vào đại sảnh trong cự tháp, mời Hổ Nguyên Tửu, trưng bày ba khối Cực Nguyên Tinh và bàn bạc giao dịch hợp luyện.","theLucLienQuan":["Phi Linh tộc"],"nguon":["@c2308"]},{"id":"linh-dia-luyen-cuc-nguyen-tinh","name":"Linh Địa luyện Cực Nguyên Tinh","cn":"","capDo":"khac","parentId":"phong-nguyen-dai-luc","blurb":"Linh Địa ở gần nơi Việt Long cư trú, được chọn để dẫn lực lượng thiên địa thuộc tính Kim và Mộc.","detail":"Việt Long cần chuẩn bị trước khi cùng Hàn Lập tới đây vào ngày hôm sau. Địa điểm này có điều kiện phù hợp để dẫn hai loại lực lượng thiên địa hiếm gặp phục vụ việc luyện Cực Nguyên Tinh.","theLucLienQuan":["Phi Linh Tộc"],"nguon":["@c2309"]},{"id":"dai-sanh-trong-cu-thap","name":"Đại sảnh trong cự tháp","cn":"","capDo":"khac","parentId":"cu-thap-trong-dong-phu-viet-long","blurb":"Đại sảnh nơi Kim Duyệt cầu viện Việt Long và gặp lại Hàn Lập.","detail":"Kim Duyệt quỳ xuống cầu xin Việt Long bảo vệ Thiên Bằng Tộc tại đây. Sau khi Hàn Lập tuyên bố chấm dứt duyên nợ với tộc nàng, hắn dùng hư không truyền tống đưa nàng ra khỏi đại sảnh.","theLucLienQuan":["Thiên Bằng Tộc","Xích Dung Tộc"],"nguon":["@c2310"]},{"id":"dat-trung-giua-hai-toa-nui-nho","name":"Đất trũng giữa hai tòa núi nhỏ","cn":"","capDo":"khac","parentId":"dong-phu-viet-long","blurb":"Linh địa hoang vu từng chịu hai lần Thiên Kiếp, được dùng để dẫn phát lực Thiên Địa.","detail":"Vùng đất trũng nằm giữa hai ngọn núi nhỏ đã trở nên hoang vu sau hai lần chịu Thiên Kiếp. Vì rất khó tìm nơi thích hợp hơn, Việt Long vẫn chọn địa điểm này để dựng pháp trận và tiến hành nghi thức.","theLucLienQuan":[],"nguon":["@c2310"]},{"id":"bau-troi-ngan-dam-quanh-bai-luyen-che","name":"Bầu trời ngàn dặm quanh bãi luyện chế","cn":"","capDo":"khac","parentId":null,"blurb":"Phạm vi thiên không nơi lực lượng thiên địa bị phù trận màu vàng thu hút.","detail":"Vô số quang cầu trắng xuất hiện trong phạm vi ngàn dặm rồi bị phù trận thu hút và thôn phệ, sau đó chuyển hóa thành những đợt kim quang đánh xuống cự đỉnh.","theLucLienQuan":[],"nguon":["@c2311"]},{"id":"son-coc-do-kiep-trong-dia-uyen","name":"Sơn cốc độ kiếp trong Địa Uyên","cn":"","capDo":"khac","parentId":"dia-uyen","blurb":"Không gian bí mật sâu dưới Địa Uyên được Thanh Nguyên Tử chọn làm nơi vượt Đại Thiên Kiếp.","detail":"Trong sơn cốc có đài cao, nhiều pháp khí, tượng hình người và thú, gạch trong suốt cùng hàng trăm loại cấm chế. Khu vực phòng hộ trải rộng bốn vạn dặm quanh nơi độ kiếp.","theLucLienQuan":[],"nguon":["@c2312"]},{"id":"dai-cao-bay-tang","name":"Đài cao bảy tầng","cn":"","capDo":"khac","parentId":"son-coc-do-kiep-trong-dia-uyen","blurb":"Đài cao xanh biếc bảy tầng được dựng làm trung tâm đạo trường độ kiếp của Thanh Nguyên Tử.","detail":"Mỗi tầng của đài đều có nhiều pháp khí. Tầng cao nhất đặt bồ đoàn và nhiều phiên kỳ tạo thành một pháp trận huyền diệu.","theLucLienQuan":[],"nguon":["@c2312"]},{"id":"vung-loan-thach-ngoai-son-coc","name":"Vùng loạn thạch ngoài sơn cốc","cn":"","capDo":"khac","parentId":"dia-uyen","blurb":"Khu vực loạn thạch nằm rất xa sơn cốc độ kiếp.","detail":"Cuối chương, cuồng phong nổi lên tại đây và hai bàn tay đen khổng lồ xuất hiện, dùng sức xé hư không sang hai phía.","theLucLienQuan":[],"nguon":["@c2312"]},{"id":"khong-gian-do-kiep-cua-thanh-nguyen-tu","name":"Không gian Độ Kiếp của Thanh Nguyên Tử","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian riêng nơi Thanh Nguyên Tử tiến hành Đại Thiên Kiếp và bị ba cường giả Đại Thừa xâm nhập.","detail":"Hoàng Nguyên Tử dùng Cửu Huyễn Như Ý Môn làm suy yếu phần lớn lực lượng không gian, tạo điều kiện để Bất Diệt Thiên Tôn xé mở khe nứt đưa Tam Toàn đạo nhân cùng tiến vào. Bên trong có sơn cốc Độ Kiếp và các cấm chế phòng hộ do Thanh Nguyên Tử bố trí.","theLucLienQuan":[],"nguon":["@c2313"]},{"id":"bien-huyet-vu","name":"Biển Huyết Vụ","cn":"","capDo":"khac","parentId":"dia-uyen","blurb":"Khu vực Huyết Vụ rộng mênh mông do trận pháp tạo thành gần nơi Thanh Nguyên Tử độ kiếp.","detail":"Bên trong Biển Huyết Vụ có vô số bóng đen phát ra huyết khí, chống lại Cửu Huyễn Như Ý Môn và hào quang ba màu của Tam Toàn đạo nhân.","theLucLienQuan":[],"nguon":["@c2315"]},{"id":"tinh-cau-mau-xanh","name":"Tinh cầu màu xanh","cn":"","capDo":"tinh-cau","parentId":null,"blurb":"Tinh cầu màu xanh đầy những vết rách được Hàn Lập dò xét trước khi tiến về sơn cốc.","detail":"Hàn Lập quan sát tinh cầu và nhận định kẻ địch vừa phát hiện mình mạnh hơn Đại Thừa bình thường nhưng vẫn kém xa Tộc mẫu Tu La Thù. Sau đó chàng kích hoạt Truyền Tấn Phù để liên lạc với Nghiên Lệ.","theLucLienQuan":[],"nguon":["@c2316"]},{"id":"chien-truong-ngoai-muoi-dam","name":"Chiến trường ngoài mười dặm","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực cách chiến trường chính hơn mười dặm, nơi Phệ Kim Trùng Vương giao chiến với Bất Diệt Thiên Tôn.","detail":"Trận chiến để lại thi thể khổng lồ của Bất Diệt Thiên Tôn hóa thành một núi xương thịt, với máu chảy thành sông quanh một ngọn núi nhỏ. Phệ Kim Trùng Vương chém lấy thủ cấp và tiêu diệt Nguyên Anh đối phương tại khu vực này.","theLucLienQuan":[],"nguon":["@c2319"]},{"id":"son-coc-do-kiep-cua-thanh-nguyen-tu","name":"Sơn cốc độ kiếp của Thanh Nguyên Tử","cn":"","capDo":"khac","parentId":"minh-ha-chi-dia","blurb":"Sơn cốc được nhiều tầng trận pháp và cấm chế bao phủ, nơi Thanh Nguyên Tử chống Đại Thiên Kiếp.","detail":"Thanh Nguyên Tử chống đỡ những vòng thiên kiếp cuối cùng trong sơn cốc với sự tương trợ trực tiếp của Nguyên Dao. Hàn Lập không yêu cầu mở cấm chế mà chờ và hộ pháp bên ngoài cho đến khi Thanh Nguyên Tử vượt kiếp rồi phục hồi nguyên khí.","theLucLienQuan":[],"nguon":["@c2320"]},{"id":"xich-dung-son-mach","name":"Xích Dung sơn mạch","cn":"","capDo":"vuc","parentId":"phong-nguyen-dai-luc","blurb":"Dãy núi dài hàng triệu dặm trên Phong Nguyên đại lục, có gần một nửa số núi là núi lửa hoạt động.","detail":"Khu vực khô nóng nhưng giàu linh thạch, khoáng tài hỏa thuộc tính và linh dược chí dương. Cự thuyền màu đen chở Hàn Lập xuất hiện trên bầu trời nơi đây sau khi rời Minh Hà chi địa.","theLucLienQuan":[],"nguon":["@c2321"]},{"id":"hac-tieu-phong","name":"Hắc Tiêu Phong","cn":"","capDo":"khac","parentId":"xich-dung-son-mach","blurb":"Ngọn núi phía bên phải trong cụm ba núi đen hình tam giác tại trung tâm Xích Dung Sơn Mạch. Đây là nơi Hách Liên Thương Minh tổ chức đấu giá hội.","detail":"Hắc Tiêu Phong từ lâu đã nằm trong khu vực cấm nguy hiểm. Đoàn của Hàn Lập phải xuất trình tín vật khách khanh với đội vệ sĩ Dị Hùng Tộc mới được tiến vào.","theLucLienQuan":["Hách Liên Thương Minh","Dị Hùng Tộc"],"nguon":["@c2322"]},{"id":"khu-vuc-cam-cua-hach-lien-thuong-minh","name":"Khu vực cấm của Hách Liên Thương Minh","cn":"","capDo":"khac","parentId":"xich-dung-son-mach","blurb":"Khu vực hạn chế bao quanh ba ngọn núi đen ở trung tâm Xích Dung Sơn Mạch. Người ngoài phải xuất trình tín vật mới được tiến vào.","detail":"Phạm vi cấm được đội vệ sĩ Dị Hùng Tộc cưỡi cự ưng tuần tra trong vùng phụ cận. Hắc Tiêu Phong và địa điểm tổ chức đấu giá hội của Hách Liên Thương Minh nằm bên trong khu vực này.","theLucLienQuan":["Hách Liên Thương Minh","Dị Hùng Tộc"],"nguon":["@c2322"]},{"id":"huyen-thien-mon","name":"Huyền Thiên môn","cn":"","capDo":"khac","parentId":null,"blurb":"Một cửa vào nối với khu vực tổ chức đấu giá dưới lòng đất.","detail":"Đoàn Hàn Lập sử dụng cửa này để truyền tống tới một bệ đá trong thế giới dưới lòng đất.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2323"]},{"id":"the-gioi-duoi-long-dat","name":"Thế giới dưới lòng đất","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian ngầm rộng lớn phục vụ khu vực tổ chức đấu giá của Hách Liên Thương Minh.","detail":"Nơi đây sáng như ban ngày, có rừng cự mộc, nhiều bệ truyền tống và thạch bích cao gắn dày đặc nguồn sáng nhân tạo. Một cấm chế vô hình hạn chế thần niệm của Hàn Lập khi hắn dò xét ra khoảng mười dặm.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2323"]},{"id":"leu-tiep-khach-cua-thuong-minh","name":"Lều tiếp khách của Thương Minh","cn":"","capDo":"khac","parentId":"the-gioi-duoi-long-dat","blurb":"Trạm chờ và tiếp dẫn khách tham dự đấu giá của Hách Liên Thương Minh.","detail":"Lều nằm tại một ngã tư trong thế giới dưới lòng đất. Khách mang tín vật vẫn phải chờ người của Thương Minh tới tiếp đón và dẫn vào khu vực bên trong.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2323"]},{"id":"thien-tu-hieu-quy-tan-cac","name":"Thiên Tự Hiệu Quý Tân Các","cn":"","capDo":"khac","parentId":"the-gioi-duoi-long-dat","blurb":"Khu tiếp đãi dành cho khách quý cấp cao của Hách Liên Thương Minh.","detail":"Phi Vân được lệnh đưa Hàn Lập tới nơi này theo tiêu chuẩn tiếp đón cao nhất dành cho thân phận Đại Thừa của hắn.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2323"]},{"id":"thi-tran-giao-dich-cua-bon-minh","name":"Thị trấn giao dịch của bổn minh","cn":"","capDo":"thanh","parentId":null,"blurb":"Khu giao dịch rộng hơn trăm dặm do bổn minh quản lý.","detail":"Thị trấn có nhiều đường phố đan xen cùng hàng loạt cửa hàng. Phần lớn người mua bán là thành viên của bổn minh, còn ngay cả tiểu nhị tại các cửa hàng cũng có tu vi ngoài Kim Đan kỳ.","theLucLienQuan":["Bổn minh của cô gái áo tím"],"nguon":["@c2324"]},{"id":"toa-thap-dau-gia","name":"Tòa tháp đấu giá","cn":"","capDo":"khac","parentId":"thi-tran-giao-dich-cua-bon-minh","blurb":"Tòa tháp nằm trong khu giao dịch và đóng vai trò cửa vào sàn đấu giá.","detail":"Bản thân tòa tháp không phải nơi tổ chức đấu giá thực sự mà trực tiếp liên thông với một Động Thiên ở bên trong.","theLucLienQuan":["Bổn minh của cô gái áo tím"],"nguon":["@c2324"]},{"id":"dong-thien-san-dau-gia","name":"Động Thiên sàn đấu giá","cn":"","capDo":"gioi-nho","parentId":"toa-thap-dau-gia","blurb":"Không gian Động Thiên được dùng làm sàn đấu giá thực sự.","detail":"Động Thiên có khả năng dung nạp đông đảo khách tham dự và giúp bổn minh hạn chế nguy cơ có người gây loạn trong đấu giá hội.","theLucLienQuan":["Bổn minh của cô gái áo tím"],"nguon":["@c2324"]},{"id":"khu-khach-quy-phong-chu-thien","name":"Khu khách quý phòng chữ Thiên","cn":"","capDo":"khac","parentId":null,"blurb":"Khu nghỉ dành cho khách quý của bổn minh, nằm giữa rừng xanh có linh khí tinh thuần.","detail":"Các lầu các trong khu nghỉ cách nhau vài dặm và được những cây cổ thụ khổng lồ ngăn cách, tạo không gian riêng biệt cho từng nhóm khách.","theLucLienQuan":["Bổn minh của cô gái áo tím"],"nguon":["@c2324"]},{"id":"quang-truong-dau-gia","name":"Quảng trường đấu giá","cn":"","capDo":"khac","parentId":"dong-thien-san-dau-gia","blurb":"Quảng trường khổng lồ nằm trong Động Thiên tổ chức Đấu Giá Đại Hội.","detail":"Khu vực này có hàng vạn chỗ ngồi và tập trung mấy vạn Dị Tộc Nhân từ cảnh giới Luyện Hư trở lên. Bệ đá trung tâm được dùng để Minh Tôn khai mạc và Hồ Ngọc Song chủ trì đấu giá; toàn quảng trường được nhiều tầng cấm chế bảo vệ.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2326"]},{"id":"phong-xam-bac","name":"Phòng xám bạc","cn":"","capDo":"khac","parentId":"dong-thien-san-dau-gia","blurb":"Những gian phòng dành cho khách có địa vị cao tại hội đấu giá.","detail":"Nhiều nhân vật Đại Thừa ngồi trong các phòng xám bạc và tham gia tranh mua cốt tủy Hoàng Kim Lôi Sư. Các phòng được phân biệt theo vị trí, trong đó người ở phòng thứ ba đã báo giá 4.800 vạn cực phẩm linh thạch.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2327"]},{"id":"thach-dai-dau-gia","name":"Thạch đài đấu giá","cn":"","capDo":"khac","parentId":"quang-truong-dau-gia","blurb":"Thạch đài trung tâm nơi Hồ Ngọc Song công bố và biểu diễn Phiên Thiên Âm Kỳ. Bốn trưởng lão Hách Liên Thương Minh chia nhau trấn giữ bốn góc.","detail":"Đây là khu vực chính của cuộc đấu giá ba bảo vật áp trục. Phiên Thiên Âm Kỳ được đưa ra, giải thích lai lịch, kích phát biểu diễn và mở giá tại đây.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2329"]},{"id":"phi-oc","name":"Phi ốc","cn":"","capDo":"khac","parentId":"quang-truong-dau-gia","blurb":"Các gian phòng dành cho những Đại Thừa tham dự cuộc đấu giá. Hàn Lập, Huyết Phách và Chu Quả Nhi theo dõi cuộc tranh đoạt Phiên Thiên Âm Kỳ từ một Phi ốc.","detail":"Phi ốc bố trí quanh khu vực đấu giá, tách các Đại Thừa khỏi đám đông trên quảng trường. Nhiều tiếng chất vấn và báo giá trong cuộc đấu giá Phiên Thiên Âm Kỳ phát ra từ những gian phòng này.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2329"]},{"id":"thach-oc-hoi-dau-gia","name":"Các Thạch Ốc phía trên quảng trường","cn":"","capDo":"khac","parentId":"quang-truong-dau-gia","blurb":"Khu vực bố trí phía trên quảng trường đấu giá dành cho các lão tổ Đại Thừa. Từ đây, những tồn tại cấp cao dùng thần niệm, linh mục và bí thuật để dò xét vật phẩm áp trục.","detail":"Các Thạch Ốc nằm phía trên quảng trường và là nơi những khách Đại Thừa theo dõi hội đấu giá. Khi Ngũ Trảo Kim Long xuất hiện, các lão tổ tại đây đồng loạt triển khai phương pháp dò xét để xác định nó là linh vật biến hình.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2331"]},{"id":"be-da-dau-gia","name":"Bệ đá đấu giá","cn":"","capDo":"khac","parentId":"quang-truong-dau-gia","blurb":"Bệ đá đặt bảo vật trong quảng trường đấu giá, nơi vụ cướp Tổ Long chân huyết và cuộc giao chiến giữa các Đại Thừa bùng phát.","detail":"Bình bát chứa linh huyết được đặt tại đây. Sau khi nam tử áo đen lấy bảo vật, cự chưởng của hai Đại Thừa va chạm ngay phía trên bệ đá và Hách Liên Thương Minh lập tức dùng màn sáng phong tỏa khu vực.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2332"]},{"id":"dai-dien-truyen-tong-duoi-long-dat","name":"Đại điện truyền tống dưới lòng đất","cn":"","capDo":"khac","parentId":"the-gioi-duoi-long-dat","blurb":"Một đại điện bí mật và được bảo vệ nghiêm mật, chứa pháp trận liên đại lục năm màu.","detail":"Tại đây, các vệ sĩ mặc giáp đen lắp linh thạch cực phẩm vào pháp trận để đưa đoàn hơn năm mươi người từ Phong Nguyên Đại Lục tới Huyết Thiên Đại Lục.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2336"]},{"id":"khong-gian-ben-trong-bat-quy-phe-phat-do","name":"Không gian bên trong Bát Quỷ Phệ Phật Đồ","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian bí mật nằm bên trong Bát Quỷ Phệ Phật Đồ, được Bích Ảnh dùng làm nơi gặp và khảo nghiệm Hàn Lập.","detail":"Không gian bị huyết vụ dày đặc bao phủ quanh Hàn Lập. Huyết khí chứa khí tức Âm Sát khiến thần niệm tiếp xúc cảm thấy lạnh buốt và chìm xuống; tại đây, hình tượng tăng nhân áo xám cùng tám ác quỷ có thể hiện thân.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2337"]},{"id":"tieu-the-gioi-moi-hinh-thanh","name":"Tiểu thế giới mới hình thành","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Tiểu thế giới giàu tài nguyên được chi nhánh Hách Liên Thương Minh tại Huyết Thiên đại lục phát hiện hơn trăm năm trước.","detail":"Tiểu thế giới đã tồn tại nhiều năm nhưng chưa sinh ra sinh linh cao cấp và trước đó chưa từng bị ngoại giới phát hiện. Tuy diện tích không lớn, nơi đây có nhiều tài nguyên nên trở thành đối tượng tranh chấp giữa Hách Liên Thương Minh và thế lực quỷ vật; hai bên sẽ dùng năm trận đấu để quyết định việc phân chia.","theLucLienQuan":["Hách Liên Thương Minh","Thế lực quỷ vật tự xưng đến từ Minh giới"],"nguon":["@c2338"]},{"id":"gioi-dien-quy-vat-tu-xung-minh-gioi","name":"Giới diện quỷ vật tự xưng Minh giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Giới diện thích hợp cho quỷ vật cường đại sinh tồn, được cư dân của nó tự nhận là Minh giới.","detail":"Theo điều tra và nhận định của Hách Liên Thương Minh, nơi này không phải Minh giới chân chính trong truyền thuyết mà gần với một Hoàng Tuyền Quỷ Quốc. Quỷ vật từ giới diện này đã tiến vào tiểu thế giới đang bị tranh đoạt.","theLucLienQuan":["Thế lực quỷ vật tự xưng đến từ Minh giới","Âm Ty Thập Vương"],"nguon":["@c2338"]},{"id":"dang-thien-cac","name":"Đăng Thiên Các","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Hách Liên Thương Minh cất giữ các bí thuật truyền từ Tiên giới.","detail":"Bích Ảnh hứa cho Hàn Lập quyền vào Đăng Thiên Các tùy ý chọn một môn bí thuật Tiên giới nếu hắn đại diện Thương Minh tham gia ước đấu và thắng một trận.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2338"]},{"id":"thuy-an-chi-dia","name":"Thủy Ấn Chi Địa","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Địa điểm tại Ma giới nơi các Đại Thừa của Hách Liên Thương Minh từng bị Minh Trùng Mẫu vây trong cấm chế.","detail":"Một số Đại Thừa do Hách Liên Thương Minh phái tới xử lý Minh Trùng Mẫu từng bị nhốt tại đây. Nhờ Hàn Lập tương trợ, họ mới thoát khỏi cấm chế, khiến hắn trở thành ân nhân của nhiều trưởng lão Thương Minh.","theLucLienQuan":["Hách Liên Thương Minh","Minh Trùng"],"nguon":["@c2338"]},{"id":"thanh-huyet-hac","name":"Thành Huyết Hạc","cn":"","aliases":["Huyết Hạc Thành"],"capDo":"thanh","parentId":"huyet-thien-dai-luc","blurb":"Tòa thành nơi Huyết Phách từng phát hiện dấu vết do bản thể của nàng để lại.","detail":"Thành Huyết Hạc nằm cách vị trí của đoàn Hàn Lập khoảng nửa năm đường bay nếu không sử dụng Truyền tống trận. Huyết Phách từng tìm thấy dấu vết bản thể tại đây nhưng phải bỏ dở việc điều tra vì bị truy sát. Thành thuộc phạm vi thế lực của Huyết Đạo đại tông.","theLucLienQuan":["Huyết Đạo đại tông"],"nguon":["@c2339"]},{"id":"thuong-co-te-dan-tuyen-thanh-huyet-hac","name":"Thượng Cổ tế đàn tuyến thành Huyết Hạc","cn":"","aliases":[],"capDo":"khac","parentId":"huyet-thien-dai-luc","blurb":"Các Thượng Cổ tế đàn nằm gần vị trí của đoàn Hàn Lập và dọc tuyến đường tới thành Huyết Hạc.","detail":"Một tế đàn nằm gần nơi đoàn Hàn Lập xuất phát, còn nhiều tế đàn khác phân bố dọc hành trình tới thành Huyết Hạc. Hàn Lập quyết định khảo sát chúng trong lúc hộ tống Huyết Phách.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2339"]},{"id":"tieu-the-gioi-cuoc-chien-cuong-gia","name":"Tiểu thế giới cuộc chiến Cường giả","cn":"","aliases":[],"capDo":"gioi-nho","parentId":null,"blurb":"Tiểu thế giới được chọn làm địa điểm tổ chức cuộc chiến Cường giả sau ba năm.","detail":"Khi cuộc chiến bắt đầu, người tham dự mang tín vật tới một phân bộ của Hách Liên Thương Minh và sẽ được tổ chức này sắp xếp đưa tới lối vào tiểu thế giới.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2339"]},{"id":"day-nui-tranh-doat-linh-duoc","name":"Dãy núi có danh tiếng trên Huyết Thiên Đại Lục","cn":"","capDo":"vuc","parentId":"huyet-thien-dai-luc","blurb":"Dãy núi nơi hai nhóm dị tộc giao chiến để tranh đoạt vài cây Linh Dược hiếm.","detail":"Mặc Linh Thánh Thuyền bay ngang qua khu vực này, dùng khí thế đánh bật các tu sĩ và xé một rãnh lớn xuyên qua rừng. Quỹ đạo của thuyền cố ý tránh những cây Linh Dược, khiến chúng vẫn nguyên vẹn sau khi thuyền rời đi.","theLucLienQuan":[],"nguon":["@c2340"]},{"id":"cam-dia-ly-hoa-tong","name":"Cấm địa Ly Hỏa Tông","cn":"","capDo":"khac","parentId":"huyet-thien-dai-luc","blurb":"Cấm địa thuộc Ly Hỏa Tông, bên trong có một tế đàn thượng cổ đã bị bỏ hoang nhiều năm.","detail":"Hơn ngàn khôi lỗi của đoàn Hàn Lập phong tỏa khu vực này trong lúc Hàn Lập và Chu Quả Nhi phá cấm chế tiến vào kiểm tra tế đàn. Sau khi đoàn rời đi, Ly Hỏa Tông tăng gấp đôi nhân thủ canh giữ.","theLucLienQuan":["Ly Hỏa Tông"],"nguon":["@c2340"]},{"id":"te-dan-thuong-co-ly-hoa-tong","name":"Tế đàn thượng cổ của Ly Hỏa Tông","cn":"","capDo":"khac","parentId":"cam-dia-ly-hoa-tong","blurb":"Tế đàn thượng cổ nằm trong cấm địa Ly Hỏa Tông, đã bị bỏ hoang nhiều năm.","detail":"Hàn Lập và Chu Quả Nhi kiểm tra nơi này nhưng xác định đây không phải tế đàn họ cần tìm. Phí trưởng lão về sau phát hiện dấu vết thi pháp do đoàn Hàn Lập để lại tại đây.","theLucLienQuan":["Ly Hỏa Tông"],"nguon":["@c2340"]},{"id":"pham-vi-huyet-cot-mon","name":"Phạm vi thế lực Huyết Cốt Môn","cn":"","capDo":"vuc","parentId":"huyet-thien-dai-luc","blurb":"Địa bàn do Huyết Cốt Môn kiểm soát, có một trong những tế đàn mà đoàn Hàn Lập cần dò xét.","detail":"Theo địa đồ và báo cáo của Huyết Phách, đoàn Hàn Lập dự kiến tiến vào khu vực này sau khoảng nửa tháng. Vì Huyết Cốt Môn có nhiều Đại Thừa và từng có thù với Huyết Phách, đoàn phải chuẩn bị thu liễm hành tung.","theLucLienQuan":["Huyết Cốt Môn"],"nguon":["@c2340"]},{"id":"van-nguyet-son-mach","name":"Vạn Nguyệt sơn mạch","cn":"","capDo":"vuc","parentId":"huyet-thien-dai-luc","blurb":"Một sơn mạch nằm gần Huyết Hạc Thành, nơi bản thể Huyết Phách từng để lại dấu hiệu.","detail":"Huyết Phách không vào Huyết Hạc Thành mà trực tiếp tới Vạn Nguyệt sơn mạch để tìm kiếm manh mối còn sót lại về bản thể.","theLucLienQuan":[],"nguon":["@c2341","@c2370"]},{"id":"dau-truong-huyet-hac-thanh","name":"Đấu trường Huyết Hạc Thành","cn":"","capDo":"khac","parentId":"thanh-huyet-hac","blurb":"Địa điểm được chọn để giải quyết cuộc xung đột giữa các Đại Thừa.","detail":"Tiêu Minh yêu cầu Vạn Hoa phu nhân tới đây tiếp ba chiêu của mình, sau đó mới bỏ qua trách nhiệm về vụ công kích trong thành.","theLucLienQuan":["Huyết Cốt Môn"],"nguon":["@c2342"]},{"id":"dong-phu-tieu-minh","name":"Động phủ của Tiêu Minh","cn":"","capDo":"khac","parentId":"thanh-huyet-hac","blurb":"Nơi ở của thành chủ Tiêu Minh tại Huyết Hạc Thành.","detail":"Tiêu Minh mời Hàn Lập, Thanh Bình đạo nhân và Vạn Hoa phu nhân tới động phủ làm khách sau khi các cuộc luận bàn kết thúc.","theLucLienQuan":["Huyết Cốt Môn"],"nguon":["@c2342"]},{"id":"di-tich-thuong-co","name":"Di tích thượng cổ","cn":"","capDo":"khac","parentId":null,"blurb":"Một di tích thượng cổ nơi Vạn Hoa phu nhân từng tìm được phương pháp tế luyện trận đồ phi châm.","detail":"Vị trí và lai lịch cụ thể của di tích chưa được nêu. Phương pháp lấy được tại đây giúp Vạn Hoa phu nhân luyện thành Trận đồ Hắc Huyết Châm.","theLucLienQuan":[],"nguon":["@c2344"]},{"id":"thien-dinh-cung","name":"Thiên Đỉnh cung","cn":"","aliases":["Thiên Đỉnh Tiên Cung"],"capDo":"gioi-nho","parentId":"van-nguyet-son-mach","blurb":"Động phủ do Thiên Đỉnh chân nhân để lại, sắp mở trong sơn mạch Vạn Nguyệt.","detail":"Thiên Đỉnh cung được cho là chứa bảo vật, linh dược, công pháp và di vật liên quan tới phương pháp vượt thiên kiếp của Thiên Đỉnh chân nhân. Chìa khóa giả vẫn có thể cảm ứng thời gian và vị trí mở cung, vì vậy nơi này có khả năng thu hút nhiều tu sĩ Đại Thừa tới tranh đoạt.","theLucLienQuan":[],"nguon":["@c2345","@c2351"]},{"id":"te-van-son-mach","name":"Tề Vân sơn mạch","cn":"","capDo":"vuc","parentId":"huyet-thien-dai-luc","blurb":"Sơn mạch nơi toàn bộ cư dân của tám quốc gia và thành viên mười chín tông môn biến mất.","detail":"Khu vực không còn người sống hay dấu vết chống cự rõ ràng, chỉ lưu lại khí tức Huyết Đạo cực mạnh. Phía bắc sơn mạch có một hồ lớn che giấu hạp cốc chứa huyết hà dưới đáy.","theLucLienQuan":["Liên minh của Bích Ảnh","Mười chín tông môn Tề Vân sơn mạch","Đề Huyết môn","Phong Xà tộc"],"nguon":["@c2346"]},{"id":"vu-quang-quoc","name":"Vũ Quang quốc","cn":"","capDo":"quoc-gia","parentId":"te-van-son-mach","blurb":"Một quốc gia quanh Tề Vân sơn mạch bị hủy diệt và mất toàn bộ cư dân.","detail":"Vũ Quang quốc nằm trong nhóm tám quốc gia xảy ra thảm họa biến mất hàng loạt, không còn người sống hay dấu vết chống cự kịch liệt.","theLucLienQuan":["Liên minh của Bích Ảnh"],"nguon":["@c2346"]},{"id":"xuyen-van-quoc","name":"Xuyên Vân quốc","cn":"","capDo":"quoc-gia","parentId":"te-van-son-mach","blurb":"Quốc gia được nêu đích danh trong nhóm tám nước mất toàn bộ cư dân quanh Tề Vân sơn mạch.","detail":"Xuyên Vân quốc bị báo là đã hủy diệt cùng Vũ Quang quốc và các quốc gia khác, không còn người sống hay dấu vết chống cự rõ ràng.","theLucLienQuan":["Liên minh của Bích Ảnh"],"nguon":["@c2346"]},{"id":"hap-coc-day-ho-phia-bac-te-van-son-mach","name":"Hạp cốc đáy hồ phía bắc Tề Vân sơn mạch","cn":"","capDo":"khac","parentId":"te-van-son-mach","blurb":"Hạp cốc bí mật dưới đáy hồ, bị vô số tầng cấm chế phong kín và chứa một huyết hà khổng lồ.","detail":"Không gian tràn ngập huyết vụ; một bóng người ngồi trên sông máu và hút từng dòng máu đặc vào vật phát sáng trong tay.","theLucLienQuan":[],"nguon":["@c2346"]},{"id":"dong-phu-tam-thoi-trong-van-nguyet-son-mach","name":"Động phủ tạm thời trong Vạn Nguyệt sơn mạch","cn":"","capDo":"khac","parentId":"van-nguyet-son-mach","blurb":"Nơi Hàn Lập dừng chân và nghe Huyết Phách kể bí mật về Hư Thiên đỉnh.","detail":"Tại đây, Huyết Phách tiết lộ Hư Thiên đỉnh là chìa khóa phỏng chế, giải thích sơ hở đại trận Thiên Đỉnh cung và mục tiêu cứu bản thể.","theLucLienQuan":[],"nguon":["@c2346"]},{"id":"long-chao-co-dam-nuoc-nam-mau","name":"Lòng chảo có đầm nước năm màu","cn":"","capDo":"khac","parentId":"te-van-son-mach","blurb":"Một vùng lòng chảo khổng lồ được các ngọn núi nhỏ bao quanh, nơi đại môn Thiên Đỉnh cung hiện thế.","detail":"Trung tâm lòng chảo có đầm nước bị cỏ thấp che phủ và phun lên cột sáng năm màu. Các phe cường giả chiếm vị trí quanh thung lũng trước khi cột sáng biến thành màn sáng và đại môn Thiên Đỉnh cung ngưng tụ.","theLucLienQuan":["Huyết Cốt Môn","Tông môn của Phụng Tông Chủ"],"nguon":["@c2348"]},{"id":"canh-cua-cuc-lon-cua-thien-dinh-cung","name":"Cánh cửa cực lớn của Thiên Đỉnh cung","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Cánh cửa lớn ngăn lối vào khu vực phong ấn của Thiên Đỉnh cung.","detail":"Cửa được vòng sáng bảo vệ, có khả năng tự khép và tự phục hồi. Lối mở do một nhóm tạo ra không thể được nhóm khác tùy ý lợi dụng, khiến từng nhóm phải tự phá cửa.","theLucLienQuan":["Môn hạ của Phụng Tông Chủ"],"nguon":["@c2349"]},{"id":"thung-lung-ngoai-thien-dinh-cung","name":"Thung lũng ngoài Thiên Đỉnh cung","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Khu vực tập kết nằm bên ngoài cánh cửa Thiên Đỉnh cung.","detail":"Huyết ảnh ẩn mình tại đây trong lúc các nhóm lớn lần lượt tiến vào, sau đó hiện thân và sát hại những người đến muộn.","theLucLienQuan":[],"nguon":["@c2349"]},{"id":"khong-gian-toi-tam-sau-canh-cua","name":"Không gian tối tăm sau cánh cửa","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Không gian nằm giữa cánh cửa lớn và phong ấn dẫn sâu vào Thiên Đỉnh cung.","detail":"Phong ấn dài hơn mấy trăm dặm bao trùm lối vào tại đây, khiến các nhóm phải tách ra và chọn những đoạn cách xa nhau để tự phá giải.","theLucLienQuan":[],"nguon":["@c2349"]},{"id":"khu-vuc-trung-tam-thien-dinh-cung","name":"Khu vực trung tâm Thiên Đỉnh cung","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Những khu vực lớn và được bảo vệ nghiêm mật nhất trong nội cung Thiên Đỉnh cung.","detail":"Các cột sáng và cấm chế tại đây mạnh hơn khu vực bên ngoài, khiến thần niệm rất khó xuyên thấu. Hàn Lập suy đoán những bảo vật quan trọng nhất được cất giữ tại khu vực trung tâm.","theLucLienQuan":[],"nguon":["@c2350"]},{"id":"khu-vuc-ben-ngoai-thien-dinh-cung","name":"Khu vực bên ngoài Thiên Đỉnh cung","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Phần ngoại vi của quần thể nội cung, nơi Huyết Phách dự định tự mình tìm kiếm Băng Phách.","detail":"Các bảo vật thông thường tại đây có khả năng đã bị những người tiến vào trước lấy đi phần lớn. Huyết Phách chọn tìm kiếm khu vực này trong khi Hàn Lập tiến sâu vào trung tâm.","theLucLienQuan":[],"nguon":["@c2350"]},{"id":"rung-mat-quy","name":"Rừng mặt quỷ","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Không gian cấm chế có con đường xuyên qua những thân cây mang gương mặt quỷ dị.","detail":"Các gương mặt nam nữ già trẻ trên cây có thể phóng tia sáng đen và lửa xanh. Sau khi Hàn Lập tiêu diệt chúng, toàn bộ cây cối trong rừng khô héo.","theLucLienQuan":[],"nguon":["@c2351"]},{"id":"vuon-cu-hoa","name":"Vườn cự hoa","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Khu vườn tỏa hương mê thần với những đóa hoa khổng lồ có thể hóa thành ma đầu.","detail":"Các cự hoa hóa thành ma đầu mặt xanh nanh vàng để vây công người xâm nhập, nhưng bị Hàn Lập dùng Ích Tà Thần Lôi tiêu diệt sạch.","theLucLienQuan":[],"nguon":["@c2351"]},{"id":"khong-gian-cat-vang","name":"Không gian cát vàng","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Khu vực cấm chế nơi khôi lỗi đất vàng liên tục tái hiện và vây đánh người xâm nhập.","detail":"Vạn Hoa phu nhân, Tiêu Minh và Thanh Bình đạo nhân bị hơn mười vạn khôi lỗi đất vàng cản đường tại đây. Mắt trận của khu vực được che giấu trong hư không dưới dạng phù văn bạc.","theLucLienQuan":[],"nguon":["@c2351"]},{"id":"trung-tam-thien-dinh-cung","name":"Trung tâm Thiên Đỉnh Cung","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Khu vực trung tâm là mục tiêu tranh đoạt của những người đang thăm dò Thiên Đỉnh Cung.","detail":"Theo tuyến đường nhóm Thanh Bình đạo nhân lựa chọn, họ cần vượt qua ba tòa phân cung để tới đây. Vạn Hoa phu nhân lo Hàn Lập sẽ phá cấm chế nhanh hơn và giành quyền tiếp cận trước.","theLucLienQuan":[],"nguon":["@c2351"]},{"id":"khu-ngoai-vi-co-day-nha","name":"Khu ngoại vi có dãy nhà","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Khu ngoại vi bị cấm chế ký hiệu bạc che giấu bằng một cảnh tượng khôi lỗi giả.","detail":"Sau khi Tiêu Minh phá tan các ký hiệu bạc, cảnh tượng giả biến mất và để lộ những dãy nhà cùng con đường dẫn tới quầng sáng.","theLucLienQuan":[],"nguon":["@c2352"]},{"id":"ngu-sac-phong-an","name":"Ngũ sắc phong ấn","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Khu vực có phong ấn năm màu, nơi Huyết Hợp Ngũ Tử phục kích người mang chìa khóa.","detail":"Một huyệt động không gian xuất hiện bên ngoài phong ấn và đưa Huyết Ảnh Tử ra ngoài. Tại đây, Huyết Ảnh Tử giao chiến ngang sức với Huyết Hợp Ngũ Tử.","theLucLienQuan":["Huyết Hợp Ngũ Tử"],"nguon":["@c2352"]},{"id":"cua-lon-thien-dinh-cung","name":"Cửa lớn Thiên Đỉnh Cung","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Lối vào có ký hiệu kim ngân bảo vệ, từng khiến gần nghìn tu luyện giả phải dừng lại.","detail":"Hơn ba mươi tu luyện giả hợp lực công kích nhưng không thể làm cửa lớn tổn hại. Xích Lôi lão tổ sau đó dùng lôi pháp đỏ đậm cưỡng ép xuyên qua cửa.","theLucLienQuan":[],"nguon":["@c2352"]},{"id":"hanh-lang-kho-phap-khi","name":"Hành lang kho pháp khí","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Hành lang dẫn tới cánh cửa gỗ đỏ của một kho pháp khí trong khu ngoại vi.","detail":"Cuối hành lang có hai Kim Cương Khôi Lỗi vàng bạc cầm bốn thanh cự chùy canh giữ. Phía sau cửa là đại sảnh chứa hơn một nghìn pháp khí.","theLucLienQuan":[],"nguon":["@c2352"]},{"id":"ao-canh-mat-bien-de-nhi-cung","name":"Ảo cảnh mặt biển đệ nhị Cung","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Mặt biển xanh vô tận do cấm chế tạo ra trên tuyến đường hướng tới khu vực trung tâm.","detail":"Ảo cảnh vây nhóm Tiêu Minh khoảng hai ngày. Tiêu Minh phải dùng trận bàn tìm cách phá giải trong khi Vạn Hoa phu nhân và Thanh Bình đạo nhân chờ đợi.","theLucLienQuan":[],"nguon":["@c2352"]},{"id":"ngon-nui-ben-trong-thien-dinh-cung","name":"Ngọn núi bên trong Thiên Đỉnh cung","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Ngọn núi rộng hơn ngàn trượng nằm trong Thiên Đỉnh cung.","detail":"Quanh núi có bảy tám khu vực bị quầng sáng bao phủ và cách ly. Hàn Lập cùng ba lão giả khô gầy lần lượt được truyền tống tới đây rồi bắt đầu đối đầu.","theLucLienQuan":[],"nguon":["@c2354"]},{"id":"thung-lung-ngoai-dai-mon","name":"Thung lũng ngoài đại môn","cn":"","capDo":"khac","parentId":"van-nguyet-son-mach","blurb":"Thung lũng gần đại môn dẫn vào Thiên Đỉnh cung.","detail":"Huyết Cốt môn bố trí một pháp trận siêu cấp bao phủ toàn bộ thung lũng, biến nơi này thành điểm phục kích những người có khả năng truyền tống ra khỏi Thiên Đỉnh cung.","theLucLienQuan":["Huyết Cốt môn"],"nguon":["@c2354"]},{"id":"rung-ram-hac-yen","name":"Rừng rậm Hắc Yên","cn":null,"capDo":"khac","parentId":null,"blurb":"Khu rừng ở phía tây bắc, nơi Vu Linh Tam thánh ẩn cư.","detail":"Vu Linh Tam thánh là ba tồn tại Đại Thừa tu luyện Vu Đạo thần thông, từng ẩn cư tại khu rừng này trước khi tiến vào Thiên Đỉnh cung.","theLucLienQuan":["Vu Linh Tam thánh"],"nguon":["@c2355"]},{"id":"man-anh-sang-mau-lam-nhat","name":"Màn ánh sáng màu lam nhạt","cn":null,"capDo":"khac","parentId":"thien-dinh-cung","blurb":"Lối vào khu vực được Hàn Lập chọn khi thăm dò Thiên Đỉnh cung.","detail":"Bên trong màn sáng phát ra ánh chớp cùng tiếng sấm. Hướng đi này trùng với con đường dẫn tới khu trung tâm Thiên Đỉnh cung mà nhóm Tiêu Minh dự định tiến vào.","theLucLienQuan":["Nhất mạch truyền thừa Thiên Đỉnh tổ sư"],"nguon":["@c2355"]},{"id":"huyet-nguc","name":"Huyết Ngục","cn":"","capDo":"gioi-nho","parentId":"thien-dinh-cung","blurb":"Nơi Thiên Đỉnh chân nhân từng giam giữ các thượng cổ cường giả, trong đó có Thiên Vu.","detail":"Huyết Ngục chứa cung điện với các trụ máu, Thôn Cốt Điệp và Huyết Linh. Nơi đây có thể còn lưu lại bảo vật và truyền thừa của những cường giả từng bị giam giữ.","theLucLienQuan":["Vu Linh tam thánh"],"nguon":["@c2356"]},{"id":"khu-vuc-bang-tuyet-trong-thien-dinh-cung","name":"Khu vực băng tuyết trong Thiên Đỉnh cung","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Một vùng sông băng và tuyết lam có hàn khí cực mạnh trong Thiên Đỉnh cung.","detail":"Hàn khí tại đây có thể xuyên qua một phần quầng sáng hộ thể của Hàn Lập. Cấm chế trong khu vực tạo ra hàng nghìn băng tước và những cự nhân băng có khả năng tái tạo thân thể.","theLucLienQuan":[],"nguon":["@c2356"]},{"id":"cung-dien-tru-mau","name":"Cung điện trụ máu","cn":"","capDo":"khac","parentId":"huyet-nguc","blurb":"Cung điện nằm trong Huyết Ngục, có nhiều cột trụ khảm đầu lâu và chảy máu.","detail":"Vu Linh tam thánh đi qua khu vực này trước khi hơn vạn Thôn Cốt Điệp xuất hiện. Máu trên các cột trụ biến thành những Huyết Linh đầu lâu khổng lồ chặn đường phía trước.","theLucLienQuan":["Vu Linh tam thánh"],"nguon":["@c2356"]},{"id":"thach-thai-truyen-tong","name":"Thạch thai truyền tống","cn":"","capDo":"khac","parentId":"khu-vuc-bang-tuyet-trong-thien-dinh-cung","blurb":"Bệ đá khắc một truyền tống trận loại nhỏ, nằm trong thế giới băng tuyết.","detail":"Thạch thai được màn sáng màu vàng của Ngũ Hành Quang Tráo bao phủ. Hàn Lập tìm thấy nơi này sau khi vượt qua sinh linh băng hệ và bão tuyết.","theLucLienQuan":[],"nguon":["@c2357"]},{"id":"khu-dien-phu-va-lau-cac-ngoai-trung-khu","name":"Khu điện phủ và lầu các ngoài trung khu","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Khu vực có điện phủ màu vàng và lầu các màu bạc mà nhóm Tiêu Minh tới sau khi thoát khỏi cấm chế băng tuyết.","detail":"Nơi này không phải trung tâm Thiên Đỉnh Cung như điển tịch ghi lại. Tiêu Minh, Thanh Bình đạo nhân và Vạn Hoa phu nhân bỏ qua các kiến trúc tại đây để tiến thẳng về màn sáng dẫn tới trung khu.","theLucLienQuan":[],"nguon":["@c2358"]},{"id":"khong-gian-tam-bia-lon","name":"Không gian tấm bia lớn","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Không gian u tối tại trung khu Thiên Đỉnh Cung, nổi bật với tấm bia đỏ tươi cao như núi và phủ đầy vân bạc.","detail":"Hàn Lập được truyền tống tới đây từ đài đá. Tấm bia lớn mang các Ngân Khoa Văn che giấu một thông đạo dẫn vào bên trong.","theLucLienQuan":[],"nguon":["@c2358"]},{"id":"thong-dao-ben-trong-tam-bia","name":"Thông đạo bên trong tấm bia","cn":"","capDo":"khac","parentId":"khong-gian-tam-bia-lon","blurb":"Lối đi hình vòm lát đá xanh, khắc linh văn đỏ tươi và tỏa ra mùi máu tanh.","detail":"Thông đạo có cấm chế áp chế thần niệm và cầm không rất mạnh. Lối đi dốc lên hơn trăm trượng rồi dẫn tới một gian phòng cực lớn.","theLucLienQuan":[],"nguon":["@c2358"]},{"id":"gian-phong-cuc-lon-cuoi-thong-dao","name":"Gian phòng cực lớn","cn":"","capDo":"khac","parentId":"thong-dao-ben-trong-tam-bia","blurb":"Gian phòng nằm ở cuối thông đạo bên trong tấm bia lớn.","detail":"Hàn Lập tiến vào gian phòng sau khi vượt qua đoạn thông đạo dốc lên. Cảnh tượng cụ thể chưa được tiết lộ, nhưng khiến hắn tỏ ra kinh ngạc khi quan sát xung quanh.","theLucLienQuan":[],"nguon":["@c2358"]},{"id":"can-phong-chien-truong-co","name":"Căn phòng chiến trường cổ","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Căn phòng rộng hơn ngàn mẫu, lưu lại hài cốt, pháp khí và dấu vết của một trận chiến cổ.","detail":"Không gian cao ba, bốn mươi trượng, chứa bộ xương của một con thú từng đạt Hợp Thể hậu kỳ đại thành cùng hài cốt và pháp khí của nhiều tu sĩ. Mười khay bạc trên giá gỗ đen đều đã bị lấy sạch.","theLucLienQuan":[],"nguon":["@c2359"]},{"id":"khong-gian-mieu-tho-hinh-tam-giac","name":"Không gian miếu thờ hình tam giác","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Không gian rộng có mây trắng, nền cát mịn và một kiến trúc hình tam giác giống miếu thờ.","detail":"Hàn Lập tới đây sau khi đi qua một thông đạo màu xanh. Bình nhỏ óng ánh không xuất hiện phản ứng đặc biệt trước kiến trúc ở trung tâm.","theLucLienQuan":[],"nguon":["@c2359"]},{"id":"ho-mau-huyet-nguc","name":"Hồ máu Huyết Ngục","cn":"","capDo":"khac","parentId":"huyet-nguc","blurb":"Hồ hình thành từ máu loãng, chứa vô số sinh vật trắng giống giòi và hơn mười lồng sắt.","detail":"Những lồng sắt lớn nhỏ nằm rải rác trên mặt hồ, bên trong giam các bộ hài cốt cổ xưa mang khí tức khiến Vu Linh Tam thánh kinh hãi.","theLucLienQuan":["Vu Linh Tam thánh"],"nguon":["@c2359"]},{"id":"dien-phu-co-pho-tuong-thien-dinh","name":"Điện phủ có pho tượng Thiên Đỉnh","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Điện phủ cao lớn đặt pho tượng đạo sĩ áo trắng được Hàn Lập suy đoán là Thiên Đỉnh Chân Nhân.","detail":"Bên cạnh tượng đạo sĩ còn có tượng chim ưng xanh và bọ ngựa bạc. Trong điện phủ có bốn khôi lỗi huyết giáp nguyên vẹn, nhiều hài cốt và pháp bảo hư hỏng, cho thấy nơi đây từng xảy ra giao chiến ác liệt.","theLucLienQuan":["Nhất mạch truyền thừa Thiên Đỉnh tổ sư"],"nguon":["@c2360"]},{"id":"khu-vuc-sau-pho-tuong","name":"Khu vực sau pho tượng","cn":"","capDo":"khac","parentId":"dien-phu-co-pho-tuong-thien-dinh","blurb":"Khu vực phía sau pho tượng trong điện phủ, nơi đặt một pháp trận truyền tống nhỏ đã bị phá hủy.","detail":"Nơi này có bệ đá trắng ngà, hai bộ hài cốt mang bốn vòng tay trữ vật và một dấu tinh huyết Băng Phách còn lưu lại trên pháp trận.","theLucLienQuan":[],"nguon":["@c2360"]},{"id":"ho-mau","name":"Hồ máu","cn":"","capDo":"khac","parentId":"huyet-nguc","blurb":"Hồ máu nằm phía trên lồng sắt giam bộ hài cốt nửa người nửa ngựa.","detail":"Đòn công kích của quái vật do các pho tượng triệu hiện khiến mặt hồ lõm xuống, để lộ vô số hài cốt trắng dưới đáy và tạo thành mưa máu phủ kín toàn hồ.","theLucLienQuan":["Vu Linh tam thánh"],"nguon":["@c2360"]},{"id":"ben-trong-long-sat","name":"Bên trong lồng sắt","cn":"","capDo":"khac","parentId":"huyet-nguc","blurb":"Không gian bên trong lồng sắt, nơi giam giữ bộ hài cốt nửa người nửa ngựa.","detail":"Bộ hài cốt bị xích sắt màu máu cùng những mũi nhọn quỷ dị trói thành một khối. Sau khi phá thủng lồng, Vu Linh tam thánh tiến vào và hiện thân phía trên mục tiêu.","theLucLienQuan":["Vu Linh tam thánh"],"nguon":["@c2360"]},{"id":"khong-gian-toi-den-sau-truyen-tong","name":"Không gian tối đen sau truyền tống","cn":"","capDo":"gioi-nho","parentId":"thien-dinh-cung","blurb":"Điểm đến của truyền tống pháp trận do Hàn Lập sửa chữa, được một lớp cảnh tượng giả che phủ.","detail":"Không gian ban đầu hiện ra như một vùng đồi núi có nhiều cột chất lỏng. Sau khi Hàn Lập dùng phi kiếm chém rách lớp hư không giả, cảnh quan thật là một đình viện có tường đá bao quanh.","theLucLienQuan":[],"nguon":["@c2362"]},{"id":"dinh-vien-tuong-da","name":"Đình viện tường đá","cn":"","capDo":"khac","parentId":"khong-gian-toi-den-sau-truyen-tong","blurb":"Cảnh quan thật được che giấu phía sau lớp huyễn cảnh tại điểm đến của truyền tống pháp trận.","detail":"Đình viện có tường đá trắng cao hàng chục trượng bao quanh núi nhỏ và cây cối. Một người chưa rõ danh tính ẩn nấp sau đại thụ tại đây.","theLucLienQuan":[],"nguon":["@c2362"]},{"id":"dai-dien-mau-xam-trang","name":"Đại điện màu xám trắng","cn":"","capDo":"khac","parentId":"trung-tam-thien-dinh-cung","blurb":"Một đại điện cổ xưa trong trung khu Thiên Đỉnh Cung, được xây bằng những khối gạch trắng lớn.","detail":"Bên trong đại điện có pho tượng Thiên Đỉnh chân nhân. Tòa tháp nhỏ màu vàng chứa bảo tàng cuối cùng nằm trong tay pho tượng và được một màn sáng phản xạ công kích bảo vệ.","theLucLienQuan":["Nhất mạch truyền thừa Thiên Đỉnh tổ sư"],"nguon":["@c2363"]},{"id":"truyen-tong-tran-trong-thien-dinh-cung","name":"Truyền Tống Trận trong Thiên Đỉnh Cung","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Pháp trận dịch chuyển nằm trong Thiên Đỉnh Cung, từng được Hàn Lập sử dụng để đi vào khu vực đại điện.","detail":"Sau khi lấy bảo vật, Hàn Lập và Băng Phách trở lại pháp trận này. Hàn Lập kích hoạt trận, khiến cả hai nhanh chóng biến mất khỏi đại điện.","theLucLienQuan":[],"nguon":["@c2364"]},{"id":"khong-gian-ben-ngoai-bia-da-mau","name":"Không gian bên ngoài bia đá màu máu","cn":"","capDo":"gioi-nho","parentId":"thien-dinh-cung","blurb":"Không gian đặt tấm bia đá màu máu mang bốn Ngân Khoa văn và đầu mối cửa vào.","detail":"Tiêu Minh, Thanh Bình đạo nhân và Vạn Hoa Phu Nhân vượt qua hành trình gian khổ để tới đây. Nhóm thử kích hoạt cửa vào bằng pháp quyết nhưng không thành công.","theLucLienQuan":[],"nguon":["@c2364"]},{"id":"bia-da-ngan-van","name":"Bia đá ngân văn","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Bia đá có những ngân văn hội tụ thành vân trận màu bạc.","detail":"Vân trận tại trung tâm bia đá mở ra một thông đạo lớn, đưa Hàn Lập và Băng Phách xuất hiện trước nhóm Tiêu Minh.","theLucLienQuan":["Nhất mạch truyền thừa Thiên Đỉnh tổ sư"],"nguon":["@c2365"]},{"id":"chien-truong-hu-khong","name":"Chiến trường hư không","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực hư không nơi Hàn Lập giao chiến với Vô Cấu lão tổ và Hoa Tây tiên tử.","detail":"Không gian tại chiến trường nhiều lần bị tinh sa khóa chặt, bị sức mạnh của Hàn Lập phá vỡ và xuất hiện dao động cấm chế từ hỏa điểu bạc. Những biến động này làm độn thuật mất hiệu lực, bóp méo hư không và giam cầm Hoa Tây trong biển lửa.","theLucLienQuan":[],"nguon":["@c2368"]},{"id":"lau-cac-chua-bao-vat","name":"Lầu các chứa bảo vật","cn":"","capDo":"khac","parentId":"thien-dinh-cung","blurb":"Lầu các trong Thiên Đỉnh Cung đặt hơn chục bảo vật trên các giá gỗ màu vàng nhạt.","detail":"Huyết Phách đang thu lấy các bảo vật tại đây thì cảm ứng được nhóm Băng Phách xuất hiện. Nàng bỏ lại hai ba món, bay ra ngoài và gặp lại bản thể của mình.","theLucLienQuan":[],"nguon":["@c2369"]},{"id":"son-coc-bi-mat","name":"Sơn cốc bí mật","cn":"","capDo":"khac","parentId":"huyet-thien-dai-luc","blurb":"Một sơn cốc bí mật trên Huyết Thiên Đại Lục, nơi thanh niên áo đen đối đầu ba tu sĩ Đại Thừa.","detail":"Sau một năm rưỡi, thanh niên áo đen xuất hiện tại đây giữa Huyết Hà, đã giết Yên Vũ Chân Nhân và dùng Vạn Linh Huyết Tỷ trấn sát lão giả xà văn. Đại hán áo giáp tím tiếp tục liều mạng phản công và bỏ thân thể để Nguyên Anh ẩn độn.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2371"]},{"id":"dai-luc-loi-dinh","name":"Đại lục Lôi Đình","cn":"","capDo":"chau","parentId":null,"blurb":"Đại lục nơi Lục Dực, Băng Phượng và Tố Âm tộc từng hiện diện trước khi cuộc truy tìm chuyển sang Huyết Thiên.","detail":"Tố Âm tộc từng an cư tại đại lục Lôi Đình từ thời thượng cổ nhưng sau đó chuyển tới Huyết Thiên. Lục Dực và Băng Phượng cũng từ đại lục này truy tìm mục tiêu tới Huyết Thiên.","theLucLienQuan":["Tố Âm tộc"],"nguon":["@c2372"]},{"id":"dai-long-quoc","name":"Đại Long Quốc","cn":"","capDo":"quoc-gia","parentId":"huyet-thien-dai-luc","blurb":"Quốc gia trên Huyết Thiên đại lục bị hung ma dùng huyết hà hủy diệt.","detail":"Toàn bộ dân chúng, sinh linh và hàng chục tông môn trong Đại Long Quốc bị biến thành máu loãng rồi hút vào huyết hà, khiến các đại thế lực quyết định can thiệp.","theLucLienQuan":["Huyết Cốt Môn","Đồ Ma Minh"],"nguon":["@c2373"]},{"id":"lac-trieu-thao-nguyen","name":"Lạc Triều thảo nguyên","cn":"","capDo":"khac","parentId":"huyet-thien-dai-luc","blurb":"Thảo nguyên nơi Hàn Lập cùng một nhóm người đang hoạt động.","detail":"Hàn Lập và đoàn người tìm kiếm một số Thượng Cổ tế đàn ở khu vực xung quanh Lạc Triều thảo nguyên trước khi được triệu tập cho cuộc chiến Cường giả.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2373"]},{"id":"thien-giai-me-cung","name":"Thiên Giai mê cung","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Mê cung trong truyền thuyết mà Huyết Sát đã phá giới tiến vào.","detail":"Huyết Sát đi vào Thiên Giai mê cung từ một năm trước nhưng đến thời điểm Hách Liên Thương Minh triệu tập người cho cuộc chiến Cường giả vẫn chưa quay lại.","theLucLienQuan":[],"nguon":["@c2373"]},{"id":"yeu-thu-chi-dia","name":"Yêu Thú chi địa","cn":"","capDo":"vuc","parentId":"huyet-thien-dai-luc","blurb":"Khu vực nổi danh trên Huyết Thiên đại lục.","detail":"Nhóm Hàn Lập hoạt động tại khu vực này trước khi nhận tín hiệu triệu tập tới cuộc chiến cường giả.","theLucLienQuan":[],"nguon":["@c2374"]},{"id":"thien-ma-thanh","name":"Thiên Mã thành","cn":"","capDo":"thanh","parentId":"huyet-thien-dai-luc","blurb":"Tòa thành lớn nằm ở rìa Lạc Triều thảo nguyên.","detail":"Thành có tường cao trồng cự trúc xanh đen, nhiều tượng phi mã và cấm chế cấm không. Nơi đây không có tu sĩ Đại Thừa trấn thủ mà chỉ có vài tu sĩ Hợp Thể.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2374"]},{"id":"phan-bo-hach-lien-thuong-minh-tai-thien-ma-thanh","name":"Phân bộ Hách Liên Thương Minh tại Thiên Mã thành","cn":"","capDo":"khac","parentId":"thien-ma-thanh","blurb":"Cơ sở của Hách Liên Thương Minh nằm tại trung tâm Thiên Mã thành.","detail":"Bên dưới phân bộ có đại sảnh cơ mật và phá không truyền tống trận dùng để đưa nhóm Hàn Lập tới tiểu giới chiến trường.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2374"]},{"id":"tieu-gioi-chien-truong","name":"Tiểu giới chiến trường","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Tiểu giới được chọn làm nơi tổ chức cuộc chiến cường giả giữa Hách Liên Thương Minh và phía Minh giới.","detail":"Hách Liên Thương Minh bố trí ba mươi sáu cứ điểm lớn tại đây. Khu vực quyết đấu nằm ở biên giới hai bên, nơi đại quân cũng có thể được điều động nếu xảy ra biến cố.","theLucLienQuan":["Hách Liên Thương Minh","Quỷ vật Minh giới"],"nguon":["@c2374"]},{"id":"cu-diem-tien-tuyen-hach-lien-thuong-minh","name":"Cứ điểm tiền tuyến của Hách Liên Thương Minh","cn":"","capDo":"khac","parentId":"tieu-gioi-chien-truong","blurb":"Một trong ba mươi sáu cứ điểm lớn của Hách Liên Thương Minh trong tiểu giới chiến trường.","detail":"Cứ điểm nằm gần địa bàn Minh giới, có hơn trăm tu sĩ trung cao giai, khôi lỗi tuần tra và nhiều tầng cấm chế phòng thủ. Hàn Lập cùng những người đồng hành được bố trí cư trú tại đây trước trận chiến.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2374"]},{"id":"bien-gioi-thuong-minh-minh-gioi","name":"Biên giới Thương Minh – Minh giới","cn":"","capDo":"vuc","parentId":"tieu-gioi-chien-truong","blurb":"Khu vực phân cách địa bàn của Hách Liên Thương Minh và quỷ vật Minh giới.","detail":"Nơi này được chọn làm địa điểm quyết đấu giữa cường giả hai bên. Ngoài những người trực tiếp giao thủ, hai phe còn có thể điều động đại quân để phòng ngừa biến cố.","theLucLienQuan":["Hách Liên Thương Minh","Quỷ vật Minh giới"],"nguon":["@c2374"]},{"id":"son-mach-gioi-dien","name":"Sơn mạch giới diện","cn":"","capDo":"vuc","parentId":null,"blurb":"Sơn mạch nằm trên ranh giới giữa khu vực của hai giới, bị một đường phân cách vô hình chia thành hai cảnh tượng đối lập. Năm ngọn núi hình ngón tay tại đây được chọn làm đấu trường cho cuộc chiến cường giả.","detail":"Một phía sơn mạch xanh tươi, có chim hót và hoa nở, trong khi phía còn lại tràn ngập hắc khí, gió lạnh và tiếng quỷ gào. Hai phe thiết lập cứ điểm và bố trí cấm chế quanh năm ngọn núi dùng làm nơi tranh tài.","theLucLienQuan":["Âm Ti Thập Vương"],"nguon":["@c2375"]},{"id":"nui-xuong-trang","name":"Núi xương trắng","cn":"","capDo":"vuc","parentId":"son-mach-gioi-dien","blurb":"Căn cứ của phe Minh Giới gồm gần trăm ngọn núi trắng cao lớn phiêu phù trong hắc khí. Các ngọn núi do vô số xương trắng chồng chất tạo thành và được ác quỷ mặc giáp xương tuần tra.","detail":"Ma trơi chớp động quanh những ngọn núi xương, trong khi vô số quỷ ảnh và âm hồn tụ tập bên ngoài. Một cung điện đỏ như máu nằm sâu trong căn cứ là nơi năm quỷ vương họp bàn kế hoạch trước cuộc chiến.","theLucLienQuan":["Âm Ti Thập Vương"],"nguon":["@c2375"]},{"id":"tieu-the-gioi-tranh-chap","name":"Tiểu Thế Giới tranh chấp","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Tiểu Thế Giới tình cờ liên thông với hai Chủ Giới Diện sau một lần chấn động.","detail":"Không gian này trở thành mục tiêu tranh đoạt giữa phe Minh giới và phe đối phương, với quyền kiểm soát được phân định thông qua năm cuộc quyết đấu giữa các cường giả.","theLucLienQuan":["Nhóm năm cường giả Minh giới","Phe cường giả Huyết Thiên Đại Lục"],"nguon":["@c2376"]},{"id":"chu-gioi-dien-cua-doi-phuong","name":"Chủ Giới Diện của đối phương","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Chủ Giới Diện thuộc phía đối địch với nhóm cường giả Minh giới.","detail":"Tính chất của Chủ Giới Diện khiến phe Minh giới không thể tùy ý chuyển hóa cửa liên thông để xâm nhập ngược từ Tiểu Thế Giới.","theLucLienQuan":["Phe cường giả Huyết Thiên Đại Lục"],"nguon":["@c2376"]},{"id":"quan-the-gioi-dien-bi-phong-be","name":"Quần Thể Giới Diện bị phong bế","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Quần thể giới diện nhỏ đã bị phong bế và mất liên hệ với Tiên giới từ lâu.","detail":"Nơi đây vẫn bảo lưu hệ thống tu luyện cùng một số bí thuật và công pháp truyền lại từ thời thượng cổ.","theLucLienQuan":["Phe cường giả Huyết Thiên Đại Lục"],"nguon":["@c2376"]},{"id":"minh-gioi","name":"Minh giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Giới diện xuất thân của nhóm cường giả do Minh Hùng phái tới.","detail":"Hung Ty Vương là cường giả nổi danh ngang ngược tại đây; lực lượng Minh giới đang tranh quyền kiểm soát Tiểu Thế Giới với phe đối phương.","theLucLienQuan":["Nhóm năm cường giả Minh giới"],"nguon":["@c2376"]},{"id":"nam-ngon-nui-quyet-dau","name":"Năm ngọn núi quyết đấu","cn":"","capDo":"khac","parentId":"tieu-the-gioi-tranh-chap","blurb":"Năm chiến trường nằm trên đường ranh giới giữa hai phe tranh chấp.","detail":"Mỗi ngọn núi được bố trí cấm chế hai tầng để một cặp cường giả giao chiến độc lập, cách tuyệt thần niệm và sự can thiệp từ những chiến trường khác.","theLucLienQuan":["Nhóm năm cường giả Minh giới","Phe cường giả Huyết Thiên Đại Lục"],"nguon":["@c2376"]},{"id":"ngon-nui-giao-chien-cua-hung-ty-vuong","name":"Ngọn núi giao chiến của Hung Ty Vương","cn":"","capDo":"khac","parentId":"nam-ngon-nui-quyet-dau","blurb":"Ngọn núi nơi Hàn Lập giao chiến và tiêu diệt Hung Ty Vương.","detail":"Chiến trường được quầng sáng hai tầng bao phủ. Hàn Lập là người đầu tiên kết thúc trận đấu tại đây trước khi chuyển sang cứu viện Văn Tâm Phượng.","theLucLienQuan":["Âm Ti Thập Vương"],"nguon":["@c2380"]},{"id":"ngon-nui-cua-van-tam-phuong","name":"Ngọn núi của Văn Tâm Phượng","cn":"","capDo":"khac","parentId":"nam-ngon-nui-quyet-dau","blurb":"Ngọn núi chứa hai chiến trường riêng và được quầng sáng hai tầng bao phủ.","detail":"Một chiến trường là cuộc giao tranh giữa con chồn có cánh với thằn lằn hai đầu. Chiến trường còn lại là cuộc đối kháng sinh diệt giữa Văn Tâm Phượng và Bạch Cốt trên đài sen.","theLucLienQuan":[],"nguon":["@c2380"]},{"id":"cung-dien-mau-den-duoi-long-dat","name":"Cung điện màu đen dưới lòng đất","cn":"","capDo":"khac","parentId":null,"blurb":"Một cung điện đen nằm sâu dưới lòng đất tại thế giới khác.","detail":"Cung điện nằm sâu vạn trượng và chứa quan tài đá xanh. Bóng đen trong quan tài thức tỉnh tại đây sau khi biết bản thể đã bị giết rồi rời đi để chuẩn bị báo thù.","theLucLienQuan":[],"nguon":["@c2380"]},{"id":"the-gioi-hai-cuc-sinh-diet","name":"Thế giới hai cực sinh diệt","cn":"","capDo":"gioi-nho","parentId":"ngon-nui-cua-van-tam-phuong","blurb":"Không gian vô hình tồn tại giữa Văn Tâm Phượng và Bạch Cốt trong cuộc đấu pháp.","detail":"Nơi này thoạt nhìn giống khoảng không trống rỗng. Dưới Linh Mục của Hàn Lập, nó hiện rõ thành một thế giới có hai cực sinh diệt hoàn toàn đối lập.","theLucLienQuan":[],"nguon":["@c2380"]},{"id":"ngon-nui-trung-tam","name":"Ngọn núi trung tâm","cn":"","capDo":"khac","parentId":null,"blurb":"Ngọn núi ở giữa các chiến trường, nơi Bích Ảnh và Chuyển Luân Vương đánh cờ phân thắng bại.","detail":"Phật Cốt Vương chạy tới đây sau khi rời chiến trường. Hàn Lập và Văn Tâm Phượng sau đó cũng xuất hiện, rồi cả ba bị yêu cầu ở lại để không can thiệp hai trận chưa kết thúc.","theLucLienQuan":[],"nguon":["@c2381"]},{"id":"hai-ngon-nui-con-lai","name":"Hai ngọn núi còn lại","cn":"","capDo":"khac","parentId":null,"blurb":"Hai chiến trường vẫn chưa phân định thắng bại khi Hàn Lập tới ngọn núi trung tâm.","detail":"Kết quả tại hai ngọn núi này khiến Chuyển Luân Vương yêu cầu Hàn Lập, Văn Tâm Phượng và Phật Cốt Vương không được rời khỏi núi trung tâm để can thiệp.","theLucLienQuan":[],"nguon":["@c2381"]},{"id":"tieu-the-gioi","name":"Tiểu thế giới","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Tiểu thế giới có nguồn tài nguyên được phía Bích Ảnh và Minh giới tranh chấp thông qua cuộc chiến cường giả.","detail":"Sau năm trận, phía Bích Ảnh nhận sáu phần tài nguyên còn Minh giới nhận bốn phần theo hiệp nghị.","theLucLienQuan":["Bổn Minh của Bích Ảnh","Minh giới"],"nguon":["@c2382"]},{"id":"bach-cot-son","name":"Bạch Cốt Sơn","cn":"","capDo":"khac","parentId":"minh-gioi","blurb":"Ngọn núi nằm gần khu vực tập hợp của các cường giả sau cuộc chiến.","detail":"Chuyển Luân Vương cùng ba Quỷ Vương còn lại tiến vào Bạch Cốt Sơn trước khi mang theo hắc khí trở về quỷ vực.","theLucLienQuan":["Minh giới","Âm Ti Thập Vương"],"nguon":["@c2382"]},{"id":"quy-vuc","name":"Quỷ vực","cn":"","capDo":"vuc","parentId":"minh-gioi","blurb":"Khu vực thuộc Minh giới, nơi các Âm Ti Quỷ Vương rút về sau khi chấp nhận kết quả cuộc chiến.","detail":"Sau khi Chuyển Luân Vương nhận thua và thống nhất tỷ lệ phân chia tài nguyên, bốn Quỷ Vương mang theo hắc khí trở về quỷ vực.","theLucLienQuan":["Minh giới","Âm Ti Thập Vương"],"nguon":["@c2382"]},{"id":"huyet-thien","name":"Huyết Thiên","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực nơi các đại tông môn tổ chức cuộc vây giết Mã Lương.","detail":"Các đại tông môn tại Huyết Thiên quyết định tiêu diệt Mã Lương sau khi hắn giết ba Đại Thừa và huyết tế hàng tỷ sinh linh. Một sa mạc trong khu vực được chọn làm chiến trường mai phục.","theLucLienQuan":["Các đại tông môn Huyết Thiên","Huyết Cốt Môn","Hách Liên Thương Minh"],"nguon":["@c2385"]},{"id":"dai-thanh-co-toa-thap-vang","name":"Đại thành có tòa tháp vàng","cn":"","capDo":"thanh","parentId":"huyet-thien","blurb":"Một đại thành nằm cách chiến trường sa mạc một khoảng không xác định, có tòa tháp vàng dùng làm nơi quan sát trận chiến.","detail":"Trong đại sảnh của tòa tháp vàng, Bích Ảnh cùng ba Đại Thừa khác theo dõi mọi khu vực của sa mạc thông qua một quầng sáng.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2385"]},{"id":"thanh-bich-anh","name":"Thành Bích Ảnh","cn":"","capDo":"thanh","parentId":"huyet-thien-dai-luc","blurb":"Tòa thành trên Huyết Thiên đại lục nơi diễn ra trận chiến diệt Ma kéo dài gần một ngày đêm.","detail":"Cuộc đại chiến tại đây phá hủy khu vực trong bán kính mấy vạn dặm quanh thành. Toàn bộ cường giả Đại Thừa của các đại tông môn do Huyết Cốt Môn cầm đầu đều tử trận, ngoại trừ Linh Vân phu nhân thoát được trong tình trạng trọng thương.","theLucLienQuan":["Huyết Cốt Môn","Vạn Cổ Sơn"],"nguon":["@c2387"]},{"id":"loi-vao-tieu-linh-thien-duoi-day-bien","name":"Lối vào Tiểu Linh Thiên dưới đáy biển","cn":"","capDo":"khac","parentId":"hai-vuc","blurb":"Lối vào Tiểu Linh Thiên được cho là nằm tại một khu vực dưới đáy biển.","detail":"Thượng cổ Tế Đàn lưu lại tọa độ đại khái của lối vào. Dựa trên manh mối này, Đồ Giảo và Hoa Thạch đã thu hẹp phạm vi tìm kiếm tới một khu vực cụ thể, nhưng chưa trực tiếp tìm thấy lối vào.","theLucLienQuan":[],"nguon":["@c2388"]},{"id":"hai-vuc-day-da-san-ho","name":"Hải vực đầy đá san hô","cn":"","capDo":"vuc","parentId":"hai-vuc","blurb":"Hải vực có nhiều đá san hô, nơi đoàn Hàn Lập dừng lại để tìm lối vào Tiểu Linh Thiên.","detail":"Mặc Linh Thánh Chu tới đây sau hai tháng hành trình. Hàn Lập triển khai hàng nghìn Giao khôi lỗi quanh mặt biển, nhiều Ma Tinh khôi lỗi dưới đáy biển, đồng thời để Hoa Thạch và Đồ Giảo dùng thần niệm dò xét; sau đó đại quân Trấn Hải Cung cũng tiến tới khu vực này.","theLucLienQuan":["Trấn Hải Cung"],"nguon":["@c2388"]},{"id":"luc-hai","name":"Lục Hải","cn":"","capDo":"vuc","parentId":"tieu-linh-thien","blurb":"Lục Hải là lãnh địa của Lục Linh Tộc trong Tiểu Linh Thiên. Hàn Lập và Chu Quả Nhi xuất hiện tại đây sau khi vượt qua thông đạo không gian.","detail":"Khu vực Hàn Lập đặt chân tới có rừng rậm và những cây tùng xanh biếc khổng lồ. Bản đồ do Chu Quả Nhi hiển thị xác nhận nơi này thuộc Lục Hải, cách vùng Nhân tộc Tiểu Linh Thiên một khoảng cực xa.","theLucLienQuan":["Lục Linh Tộc","Nhân tộc Tiểu Linh Thiên"],"nguon":["@c2389"]},{"id":"cu-thach-do-tham-day-bien","name":"Cự thạch đỏ thẫm dưới đáy biển","cn":"","capDo":"khac","parentId":"loi-vao-tieu-linh-thien-duoi-day-bien","blurb":"Cự thạch đỏ thẫm là cửa vào thông đạo dẫn tới Tiểu Linh Thiên. Nó nằm dưới đáy biển và bề ngoài trông như một khối đá bình thường.","detail":"Khi có người xâm nhập, bề mặt cự thạch vặn vẹo và dẫn vào một khu vực có lực cấm chế khiến thân thể ngưng trệ. Sâu bên trong xuất hiện quầng sáng bảy màu đóng vai trò thông đạo không gian sang Tiểu Linh Thiên.","theLucLienQuan":[],"nguon":["@c2389"]},{"id":"khu-vuc-cu-tru-cua-nhan-toc","name":"Khu vực cư trú của Nhân tộc","cn":"","capDo":"vuc","parentId":"tieu-linh-thien","blurb":"Địa bàn của Nhân tộc bản địa trong Tiểu Linh Thiên.","detail":"Mặc Linh Thánh Chu tiến vào khu vực này sau khi rời phạm vi khống chế của Lục Linh Tộc. Những điểm giám sát liên tục truyền tin về hậu phương nhưng không có ai ra mặt ngăn cản hoặc tra hỏi đoàn Hàn Lập.","theLucLienQuan":["Nhân tộc Tiểu Linh Thiên"],"nguon":["@c2392"]},{"id":"thach-dien-tren-dinh-nui-van-truong","name":"Thạch điện trên đỉnh núi vạn trượng","cn":"","capDo":"khac","parentId":"khu-vuc-cu-tru-cua-nhan-toc","blurb":"Nơi các cường giả Hợp Thể của Nhân tộc tổ chức hội nghị.","detail":"Tại thạch điện, các cường giả Nhân tộc đánh giá tin tức về vị Đại Thừa mới xuất hiện, bàn cơ hội trở về Linh giới và chuẩn bị phương án đề phòng. Đây cũng là nơi phi kiếm truyền thư của Nam Cung Uyển mang ngọc giản tới.","theLucLienQuan":["Nhân tộc Tiểu Linh Thiên"],"nguon":["@c2392"]},{"id":"mat-that-han-bang","name":"Mật thất hàn băng","cn":"","capDo":"khac","parentId":"tieu-linh-thien","blurb":"Nơi Nam Cung Uyển bế quan tu luyện bí thuật.","detail":"Mật thất nằm tại một nơi bí ẩn trong sơn cốc, có lối ra vào bị hàn băng phong kín. Nam Cung Uyển tĩnh tọa lĩnh hội tại đây, phía trên một vòng Ngân Luân sáng như trăng.","theLucLienQuan":["Nhân tộc Tiểu Linh Thiên"],"nguon":["@c2392"]},{"id":"day-nui-bien-gioi-nhan-toc","name":"Dãy núi biên giới Nhân tộc","cn":"","capDo":"khac","parentId":"khu-vuc-cu-tru-cua-nhan-toc","blurb":"Khu vực biên giới nơi Mặc Linh Thánh Chu xuất hiện công khai trong địa bàn Nhân tộc.","detail":"Sự xuất hiện của cự thuyền màu đen lớn như núi nhỏ khiến các tu sĩ đê giai trong dãy núi kinh ngạc. Tin tức về đoàn Hàn Lập nhanh chóng được truyền về hậu phương.","theLucLienQuan":["Nhân tộc Tiểu Linh Thiên"],"nguon":["@c2392"]},{"id":"day-nui-nho-noi-thach-tiem-van-cu-tru","name":"Dãy núi nhỏ nơi Thạch Tiêm Vân cư trú","cn":"","capDo":"khac","parentId":"khu-vuc-cu-tru-cua-nhan-toc","blurb":"Khu vực cư trú của Thạch Tiêm Vân và người thân của Chu Quả Nhi.","detail":"Dãy núi nằm sau một hồ nước lớn, gồm động phủ của Thạch Tiêm Vân cùng nơi ở của một số thúc bá và tỷ muội của Chu Quả Nhi. Hàn Lập dừng Mặc Linh Thánh Chu tại đây để đưa Chu Quả Nhi về nhà.","theLucLienQuan":["Nhân tộc Tiểu Linh Thiên"],"nguon":["@c2392"]},{"id":"dong-phu-cua-thach-tiem-van","name":"Động phủ của Thạch Tiêm Vân","cn":"","capDo":"khac","parentId":"day-nui-nho-noi-thach-tiem-van-cu-tru","blurb":"Động phủ nằm trong vách núi, là nơi Thạch Tiêm Vân tiếp đón Hàn Lập và chuyển lời xin gặp tới nữ tiền bối bí ẩn.","detail":"Bên trong động phủ có hành lang đá xanh và một đại sảnh được bài trí mộc mạc. Tại đây Hàn Lập giúp Tuyết Nhi khai mở linh trí, truy hỏi nguồn gốc Tố Nữ Luân Hồi Công và nhận được lời hẹn gặp vào sáng hôm sau.","theLucLienQuan":["Nhân tộc Tiểu Linh Thiên"],"nguon":["@c2393"]},{"id":"cong-quang-sang-bay-mau","name":"Cổng quầng sáng bảy màu","cn":"","aliases":["Gốc đại thụ khổng lồ"],"capDo":"khac","parentId":"luc-hai","blurb":"Cổng không gian nằm tại vị trí một gốc đại thụ khổng lồ trên Lục Hải.","detail":"Hàn Lập thi pháp khiến đại thụ biến mất và quầng sáng bảy màu hiện ra. Mặc Linh Thánh Thuyền thu nhỏ rồi xuyên qua cổng này để rời Tiểu Linh Thiên.","theLucLienQuan":["Nhân tộc Tiểu Linh Thiên","Lục Linh Tộc"],"nguon":["@c2395"]},{"id":"thanh-thi-ven-bien-huyet-thien","name":"Thành thị ven biển Huyết Thiên","cn":"","capDo":"thanh","parentId":"huyet-thien-dai-luc","blurb":"Một thành thị ven biển thuộc Huyết Thiên đại lục, nơi có phân minh của Hách Liên thương minh.","detail":"Mặc Linh Thánh Chu dừng tại đây sau vài tháng vượt biển. Hàn Lập gặp người phụ trách phân minh để hỏi về truyền tống trận và thu thập tin tức liên quan đến Bích Ảnh cùng hung ma.","theLucLienQuan":["Hách Liên thương minh"],"nguon":["@c2396"]},{"id":"cam-dia-huyet-ngan-tong","name":"Cấm địa Huyết Ngân tông","cn":"","capDo":"khac","parentId":"huyet-thien-dai-luc","blurb":"Khu cấm địa của Huyết Ngân tông, nơi đặt pháp trận truyền tống vượt đại lục.","detail":"Mã Lương kích phát pháp trận tại đây để rời Huyết Thiên đại lục và tới Lôi Minh đại lục. Hai người đào vong cũng sử dụng pháp trận trong tình thế gấp gáp nên không kịp điều chỉnh đích đến.","theLucLienQuan":["Huyết Ngân tông"],"nguon":["@c2396"]},{"id":"cai-linh-thanh","name":"Cái Linh thành","cn":"","aliases":[],"capDo":"thanh","parentId":"loi-minh-dai-luc","blurb":"Một trong các thành lớn của Giác Xi tộc trên Lôi Minh đại lục.","detail":"Cái Linh thành bị biển máu của Mã Lương bao phủ và huyết tế hoàn toàn. Vô số tộc nhân Giác Xi, hơn trăm tu sĩ cao giai cùng Đại Thừa trấn thủ Thiên Tượng bị giết.","theLucLienQuan":["Giác Xi tộc"],"nguon":["@c2397"]},{"id":"chu-thanh-giac-xi-toc","name":"Chủ thành Giác xi tộc","cn":"","capDo":"thanh","parentId":"loi-minh-dai-luc","blurb":"Một chủ thành của Giác xi tộc, nơi sáu Đại thừa lão tổ bố trí cấm chế mai phục Mã Lương.","detail":"Cuộc giao chiến tại đây kéo dài hơn nửa ngày. Bốn lão tổ Giác xi tộc vẫn lạc, hai người trọng thương bỏ chạy và Mã Lương bị thương bởi nhiều kiện Huyền Thiên Tàn Bảo tự bạo.","theLucLienQuan":["Giác xi tộc"],"nguon":["@c2398"]},{"id":"khong-gian-bi-an","name":"Không gian bí ẩn","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian riêng nơi thanh niên áo đen và ba Chân Linh bị liên kết bởi Xiềng Xích Pháp Tắc.","detail":"Tại đây, thanh niên áo đen dụ hàng ba Chân Linh, dùng huyết sắc đại ấn tiêu diệt Đề Long và để lộ việc Dương Lộc đã sớm quy thuận hắn.","theLucLienQuan":["Giác Xi tộc"],"nguon":["@c2400"]},{"id":"khong-gian-trong-binh-nho","name":"Không gian trong bình nhỏ","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian nằm bên trong bình nhỏ màu xanh, được thanh niên áo đen dùng làm nơi ẩn mình và tĩnh dưỡng.","detail":"Nơi đây còn dấu vết của một trận đại chiến và có sương mù bao phủ. Không gian có thể diễn hóa mây bảy màu, ảo ảnh linh hoa dị thảo và ảo ảnh bình khổng lồ phục vụ quá trình chữa thương của thanh niên áo đen.","theLucLienQuan":[],"nguon":["@c2401"]},{"id":"thanh-nguyen-cung","name":"Thanh Nguyên Cung","cn":"","capDo":"khac","parentId":"nguyen-hop-dao","blurb":"Cung điện của Hàn Lập trên Nguyên Hợp Đảo, gồm nhiều điện phủ và lầu các.","detail":"Nam Cung Uyển chọn một Thiên điện tại đây làm nơi ở và tu luyện. Thanh Nguyên Cung còn có Tàng Kinh Các cùng Vạn Bảo Khố là hai trọng địa lưu giữ tài nguyên.","theLucLienQuan":["Thanh Nguyên Cung"],"nguon":["@c2404"]},{"id":"tang-kinh-cac","name":"Tàng Kinh Các","cn":"","capDo":"khac","parentId":"thanh-nguyen-cung","blurb":"Trọng địa lưu giữ điển tịch và bí thuật của Thanh Nguyên Cung.","detail":"Hàn Lập giao lệnh bài cấm chế cho Nam Cung Uyển, cho phép nàng tự do ra vào nơi này khi cần.","theLucLienQuan":["Thanh Nguyên Cung"],"nguon":["@c2404"]},{"id":"van-bao-kho","name":"Vạn Bảo Khố","cn":"","capDo":"khac","parentId":"thanh-nguyen-cung","blurb":"Kho tàng trọng địa của Thanh Nguyên Cung, lưu giữ pháp khí, tài liệu, đan dược và nhiều bảo vật.","detail":"Nam Cung Uyển được Hàn Lập giao lệnh bài cấm chế để tự do ra vào và lựa chọn tài nguyên cần thiết.","theLucLienQuan":["Thanh Nguyên Cung"],"nguon":["@c2404"]},{"id":"u-coc-heo-lanh","name":"U cốc hẻo lánh","cn":"","capDo":"khac","parentId":"phong-nguyen-dai-luc","blurb":"Một u cốc trên Phong Nguyên đại lục, nơi Lục Dực và Băng Phượng bị chặn lại.","detail":"Bốn Đại Thừa xa lạ phối hợp với đại hình cấm chế bao phủ các hướng quanh u cốc, khiến hai người khó nhanh chóng phá vây.","theLucLienQuan":["Liên minh của Minh Tôn"],"nguon":["@c2404"]},{"id":"cam-dia-giap-don-toc","name":"Cấm địa Giáp Đồn tộc","cn":"","capDo":"khac","parentId":"phong-nguyen-dai-luc","blurb":"Cấm địa của Giáp Đồn tộc trên Phong Nguyên đại lục, nơi đặt Truyền Tống điện và pháp trận xuyên đại lục. Đây là điểm Mã Lương cùng Dương Lộc xâm nhập đại lục.","detail":"Khu vực được lực lượng Giáp Đồn tộc canh phòng nghiêm ngặt nhưng bị Mã Lương và Dương Lộc đột nhập bằng chính pháp trận truyền tống. Cuộc giao tranh khiến nhiều vệ sĩ thiệt mạng và hệ thống cấm chế bị phá hủy.","theLucLienQuan":["Giáp Đồn tộc"],"nguon":["@c2405"]},{"id":"truyen-tong-dien-cua-giap-don-toc","name":"Truyền Tống điện của Giáp Đồn tộc","cn":"","capDo":"khac","parentId":"cam-dia-giap-don-toc","blurb":"Đại điện chứa pháp trận truyền tống xuyên đại lục của Giáp Đồn tộc. Nơi này bị Mã Lương và Dương Lộc công phá sau khi họ truyền tống tới.","detail":"Truyền Tống điện được hơn trăm vệ sĩ bảo vệ. Mã Lương cùng Dương Lộc xuất hiện trong điện, giết lực lượng tiến vào kiểm tra và phá nổ đại điện từ bên trong trước khi vượt qua vòng cấm chế bên ngoài.","theLucLienQuan":["Giáp Đồn tộc"],"nguon":["@c2405"]},{"id":"day-nui-gan-cam-dia-giap-don-toc","name":"Dãy núi gần cấm địa Giáp Đồn tộc","cn":"","capDo":"khac","parentId":"phong-nguyen-dai-luc","blurb":"Dãy núi Mã Lương và Dương Lộc tiếp cận sau khi rời cấm địa Giáp Đồn tộc. Mã Lương bất ngờ dừng lại tại đây vì nhận thấy một dấu hiệu chưa rõ.","detail":"Sau khi vượt qua thảo nguyên, hai kẻ xâm nhập bay đến gần dãy núi. Mã Lương đột ngột dừng độn quang, khiến Dương Lộc phải hỏi nguyên nhân.","theLucLienQuan":[],"nguon":["@c2405"]},{"id":"day-nui-khong-lo","name":"Dãy núi khổng lồ","cn":"","capDo":"khac","parentId":"phong-nguyen-dai-luc","blurb":"Dãy núi nơi Mã Lương dừng lại để thi triển các thủ đoạn truy tung.","detail":"Mã Lương đứng trên đỉnh một ngọn núi lớn trong dãy núi này và thi pháp dưới sự hộ pháp của Dương Lộc.","theLucLienQuan":[],"nguon":["@c2407"]},{"id":"cam-dia-linh-toc","name":"Cấm địa Linh Tộc","cn":"","capDo":"khac","parentId":null,"blurb":"Cấm địa linh thiêng của Linh Tộc, có băng phong cao hơn nghìn trượng.","detail":"Bên dưới băng phong đang giam một thanh niên tuấn mỹ bằng nhiều dây xích bùa chú. Sau khi phong ấn xuất hiện dị động, người trông coi quyết định kiểm tra lại cấm chế và tăng gấp đôi thủ vệ.","theLucLienQuan":["Linh Tộc"],"nguon":["@c2407"]},{"id":"minh-sat-chi-dia","name":"Minh Sát chi địa","cn":"","capDo":"khac","parentId":"thien-ngoai-thien","blurb":"Địa điểm tại Thiên Ngoại Thiên được Minh Tôn chọn làm nơi tập hợp cường giả và giao chiến với Mã Lương.","detail":"Nơi này có tử sát khí dày đặc, thích hợp để Hách Liên Thương Minh triệu hoán những Chân Linh đã được cung phụng lâu năm.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2407"]},{"id":"thien-ngoai-thien","name":"Thiên Ngoại Thiên","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực chứa Minh Sát chi địa và được chọn làm chiến trường dự kiến chống lại Mã Lương.","detail":"Minh Tôn ra lệnh cho các cường giả từng được mời tới tập hợp tại Minh Sát chi địa thuộc khu vực này.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2407"]},{"id":"cung-dien-thanh-nguyen","name":"Cung điện Thanh Nguyên","cn":"","capDo":"khac","parentId":"nguyen-hop-dao","blurb":"Cung điện nơi Hàn Lập triệu tập người thân và đệ tử trước khi lên đường.","detail":"Hàn Lập bàn giao công việc Thanh Nguyên Cung, dặn Ngân Nguyệt tiếp tục tu luyện và lưu lại phương án ứng biến tại đây.","theLucLienQuan":["Thanh Nguyên Cung"],"nguon":["@c2408"]},{"id":"tong-bo-hach-lien-thuong-minh","name":"Tổng bộ Hách Liên Thương Minh","cn":"","capDo":"khac","parentId":"dai-luc-phong-nguyen","blurb":"Tổng bộ đã được Hách Liên Thương Minh di tản hoàn toàn trước khi Mã Lương đến.","detail":"Sinh linh, công trình, cấm chế, trận pháp và linh thạch tại tổng bộ đều đã được dời đi, chỉ còn một khu vực trống rỗng.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2408"]},{"id":"cu-diem-hach-lien-thuong-minh","name":"Cứ điểm Hách Liên Thương Minh","cn":"","capDo":"khac","parentId":"dai-luc-phong-nguyen","blurb":"Cứ điểm nơi Minh Tôn giao nhiệm vụ dẫn dụ Mã Lương cho Lục Dực và Băng Phượng.","detail":"Sau khi người của thương minh phân tán rút đi, Mã Lương đến nơi và dùng một cột sét biến toàn bộ cứ điểm thành tro.","theLucLienQuan":["Hách Liên Thương Minh"],"nguon":["@c2408"]},{"id":"thanh-chinh-te-hoa-toc","name":"Thành chính Tế Hòa Tộc","cn":"","capDo":"thanh","parentId":"dai-luc-phong-nguyen","blurb":"Thành chính của Tế Hòa Tộc tại đại lục Phong Nguyên.","detail":"Hơn mười đám mây máu bao vây thành và luyện hóa hơn trăm nghìn cư dân thành máu loãng.","theLucLienQuan":["Tế Hòa Tộc"],"nguon":["@c2408"]},{"id":"cung-dien-thuong-minh-tai-thien-ngoai-thien","name":"Cung điện thương minh tại Thiên Ngoại Thiên","cn":"","capDo":"khac","parentId":"thien-ngoai-thien","blurb":"Cung điện trắng ngà nằm trên một đảo đá rộng vài dặm trong Thiên Ngoại Thiên, được thương minh dùng làm nơi tiếp đón và hội họp.","detail":"Cung điện được xây trên một khối đá lớn như hòn đảo, trước cửa có hai hàng vệ sĩ mặc trọng giáp. Bên trong là đại sảnh cao vài chục trượng, nơi Minh Tôn cùng các khách mời bàn bạc.","theLucLienQuan":["Thương Minh"],"nguon":["@c2409"]},{"id":"khu-vuc-minh-sat","name":"Khu vực Minh Sát","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực nằm gần phạm vi khống chế của Lưỡng Nghi Diệt Trần. Lục Dực đã dẫn chân tiên tới gần nơi này theo kế hoạch.","detail":"Theo báo cáo của thương minh, mục tiêu dự kiến tiến vào phạm vi khống chế của đại trận sau hai hoặc ba canh giờ.","theLucLienQuan":["Thương minh"],"nguon":["@c2411"]},{"id":"tran-nhan-luong-nghi-vi-tran-tai-minh-sat","name":"Trận nhãn Lưỡng Nghi Vi Trần tại Minh Sát","cn":"","capDo":"khac","parentId":"khu-vuc-minh-sat","blurb":"Một trong hai mắt trận nam và bắc của đại trận tại Minh Sát. Khu vực gồm tế đàn tam giác trắng ngà, tám cột sáng vàng và nhiều tầng cấm chế.","detail":"Trận nhãn được gần một ngàn giáp sĩ bảo vệ, trong đó tám tu sĩ Hợp Thể trấn giữ tám cột sáng. Khi cơ chế hiến tế phát động, sinh linh và bảo vật trong bán kính một trăm dặm quanh mắt trận có thể bị luyện hóa.","theLucLienQuan":["Bổn minh của Minh Tôn"],"nguon":["@c2412"]},{"id":"vung-dat-minh-sat","name":"Vùng đất Minh Sát","cn":"","capDo":"vuc","parentId":null,"blurb":"Vùng đất tràn ngập âm sát khí, được phe Minh Tôn chọn làm chiến trường phục kích Mã Lương.","detail":"Âm sát khí dày đặc tại đây có thể hạn chế thần niệm của Mã Lương. Phe Minh Tôn bố trí Lưỡng Nghi Diệt Trần cùng lực lượng Đại Thừa trong vùng, còn Lục Dực và Băng Phượng phụ trách dẫn mục tiêu tiến sâu vào địa thế phục kích.","theLucLienQuan":["Hách Liên Thương Minh","Bổn minh của Minh Tôn"],"nguon":["@c2413"]},{"id":"hai-mat-tran-cua-dai-tran","name":"Hai mắt trận của đại trận","cn":"","capDo":"khac","parentId":"khu-vuc-minh-sat","blurb":"Hai điểm trọng yếu duy trì đại trận và trở thành mục tiêu công kích đồng thời của phe Mã Lương.","detail":"Mã Lương phái Dương Lộc cùng người tí hon đeo mặt nạ quỷ tới hai hướng khác nhau để phá trận. Minh Tôn đáp lại bằng cách chia Lục Dực, Băng Phượng và Hiên Cửu Linh đi ngăn chặn, trong khi Hàn Lập cùng Vân Đạm Sở đang trấn giữ một mắt trận.","theLucLienQuan":["Bổn minh của Minh Tôn","Thương minh"],"nguon":["@c2415"]},{"id":"vang-trang-tron","name":"Vầng trăng tròn","cn":"","capDo":"khac","parentId":"khu-vuc-minh-sat","blurb":"Vị trí Minh Tôn đứng chủ trì toàn bộ chiến cuộc.","detail":"Từ vầng trăng, Minh Tôn quan sát việc Mã Lương chia quân, phân công lực lượng bảo vệ các mắt trận và vận dụng trận pháp truyền tống viện thủ tới chiến trường.","theLucLienQuan":["Bổn minh của Minh Tôn"],"nguon":["@c2415"]},{"id":"te-dai-mat-tran-cua-han-lap","name":"Tế đài mắt trận của Hàn Lập","cn":"","capDo":"khac","parentId":"hai-mat-tran-cua-dai-tran","blurb":"Tế đài tại mắt trận do Hàn Lập cùng Vân Đạm Sở trấn giữ.","detail":"Hàn Lập ngồi dưỡng thần bên dưới tế đài khi chấn động từ chiến trường xa truyền tới. Các giáp sĩ Thương minh quanh khu vực lập tức chuyển sang trạng thái đề phòng, còn Hàn Lập dùng linh mục quan sát tình hình ngoài mấy ngàn dặm.","theLucLienQuan":["Thương minh","Bổn minh của Minh Tôn"],"nguon":["@c2415"]},{"id":"phap-tran-trang-nga-o-chan-troi-xa","name":"Pháp trận trắng ngà ở chân trời xa","cn":"","capDo":"khac","parentId":"khu-vuc-minh-sat","blurb":"Chiến trường nơi Lục Dực và Băng Phượng duy trì màn sáng vây một bóng đen cao lớn.","detail":"Một bóng đen cao hơn mười trượng liên tục xung kích bên trong màn sáng nhưng chưa thể thoát ra. Lục Dực và Băng Phượng xuất hiện phía trên pháp trận để thực hiện nhiệm vụ trì hoãn đối phương.","theLucLienQuan":["Bổn minh của Minh Tôn"],"nguon":["@c2415"]},{"id":"khu-vuc-may-mau","name":"Khu vực mây máu","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực có đám mây máu truyền ra lượng chân nguyên lớn cho lực lượng của Mã Lương.","detail":"Tám huyết long cùng những người khổng lồ phải lùi về gần khu vực này để tiếp nhận chân nguyên và miễn cưỡng duy trì chiến đấu trước Ngân Cương Tử cùng đàn Hắc Nghê.","theLucLienQuan":[],"nguon":["@c2418"]},{"id":"chien-truong-kim-sac-linh-vuc","name":"Chiến trường trong Kim Sắc Linh Vực","cn":"","capDo":"khac","parentId":"linh-gioi","blurb":"Khu vực chiến trường bị Kim Sắc Linh Vực của Mã Lương bao phủ và biến đổi hoàn toàn. Cuối chương, sức ép trong phạm vi trăm dặm phong tỏa đường tháo chạy của các Đại Thừa.","detail":"Hư không và đại địa trong phạm vi Linh Vực đều chuyển thành màu kim sắc, đồng thời xuất hiện quang đoàn, khe nứt, núi lửa và dung nham. Sau khi Cực Nhạc Phạm Hà Giới bị phá, không khí trong phạm vi trăm dặm trở nên cứng hơn thép tinh, đánh bật những người đang độn thoát.","theLucLienQuan":["Liên minh của Minh Tôn"],"nguon":["@c2420"]},{"id":"phong-nguyen-dai-luc","name":"Phong Nguyên Đại lục","cn":"","capDo":"chau","parentId":null,"blurb":"Đại lục có nhiều cường giả đang tham gia trận chiến chống Mã Lương.","detail":"Trong trận chiến tại khu vực hư không, nhiều cường giả nổi danh của Phong Nguyên Đại lục bị màn tơ máu giết chết, còn nhóm Minh Tôn tiếp tục chống lại Vạn Linh Huyết Tỷ.","theLucLienQuan":[],"nguon":["@c2422"]},{"id":"chien-truong-trong-kiem-tran","name":"Chiến trường trong kiếm trận","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực giao chiến rộng khoảng trăm dặm nằm trong kiếm trận do Hàn Lập duy trì.","detail":"Hàn Lập và Mã Lương liên tục thuấn di trong phạm vi này. Việc Hàn Lập truy kích không ngừng khiến Mã Lương chỉ có thể né tránh và không có thời gian nghỉ.","theLucLienQuan":[],"nguon":["@c2427"]},{"id":"khe-ho-khong-gian","name":"Khe hở không gian","cn":"","capDo":"khac","parentId":null,"blurb":"Không gian nguy hiểm nơi phân hồn của Mã Lương bị Phá Diện Pháp Mục cưỡng ép ném vào.","detail":"Hàn Lập cho rằng phân hồn không có chỗ nương tựa sau khi rơi vào khe hở không gian sẽ chẳng bao lâu bị hủy diệt, nhưng kết quả cuối cùng chưa được chứng kiến trực tiếp.","theLucLienQuan":[],"nguon":["@c2428"]},{"id":"thien-ngoai-ma-vuc","name":"Thiên Ngoại Ma Vực","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Nơi Ma Quang có thể trở về nếu không lựa chọn đi theo Hàn Lập.","detail":"Ma Quang tuyên bố bản thân vẫn có cách trở lại Thiên Ngoại Ma Vực sau khi khế ước với Mã Lương mất hiệu lực.","theLucLienQuan":["Thiên Ngoại Ma Tộc"],"nguon":["@c2429"]},{"id":"linh-vuc-cua-linh-toc","name":"Linh Vực của Linh tộc","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Khu vực được xác định là nơi có khả năng cao nhất đang che giấu chủ nhân Bổn Mệnh Bài.","detail":"Giải Đạo Nhân xác định chủ nhân Bổn Mệnh Bài vẫn ở Linh giới, tại một nơi không xa địa vực Nhân tộc và nhiều khả năng nằm trong Linh Vực của Linh tộc.","theLucLienQuan":["Linh tộc"],"nguon":["@c2432"]},{"id":"khong-gian-ngam-duoi-phuc-linh-son","name":"Không gian ngầm dưới Phục Linh Sơn","cn":"","capDo":"gioi-nho","parentId":"phuc-linh-son","blurb":"Không gian bí mật nơi Linh Vương phong ấn một Chân Tiên dưới khối băng.","detail":"Linh Vương dẫn Hàn Lập vào nơi này sau khi nhận ra khí tức trên Bổn Mệnh Bài. Tại đây có một thanh niên tuấn mỹ bị phong ấn dưới khối băng, đồng thời Linh Vương thu hồi hóa thân màu trắng và hiển lộ khí tức thực sự.","theLucLienQuan":["Linh tộc"],"nguon":["@c2432"]},{"id":"khong-gian-than-bi-o-ma-gioi","name":"Không gian thần bí ở Ma giới","cn":"","capDo":"gioi-nho","parentId":"ma-gioi","blurb":"Không gian ẩn chứa một quang trận có liên hệ với Bình Linh.","detail":"Trong không gian này có một ao nước chứa giọt dịch thủy màu bạc nhạt và một quang trận ẩn. Khi Hàn Lập thi triển bí thuật cảm ứng, quang trận tại đây cộng hưởng với cột sáng do bình nhỏ màu xanh và trận pháp tạo ra.","theLucLienQuan":[],"nguon":["@c2434"]},{"id":"kho-linh-coc","name":"Khổ Linh Cốc","cn":"","capDo":"khac","parentId":"kho-linh-dao","blurb":"Sơn cốc linh khí dồi dào nằm giữa hai ngọn núi xanh trên Khổ Linh Đảo.","detail":"Khổ Linh Cốc vốn được cấm chế và cảnh vật bên ngoài che giấu. Đây là nơi Linh Tiêu Thiên Trụ phóng lên, Chưởng Thiên Bình phát sinh cộng hưởng và Bình Linh hiện thân.","theLucLienQuan":["Ma tộc"],"nguon":["@c2435"]},{"id":"khe-sau-khong-thay-day","name":"Khe sâu không thấy đáy","cn":"","capDo":"khac","parentId":"ma-gioi","blurb":"Khe sâu nổi tiếng tại Ma Giới, được Hàn Lập chọn làm điểm phá giới.","detail":"Sau khi rời Khổ Linh Đảo và đi thêm vài tháng, Hàn Lập cùng Giải Đạo Nhân tới khe sâu này. Hàn Lập xác định có thể phá giới tại đây để tới Ly Long Đảo.","theLucLienQuan":[],"nguon":["@c2435"]},{"id":"ly-long-dao","name":"Ly Long Đảo","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Đích đến của Hàn Lập và Giải Đạo Nhân sau khi phá giới khỏi Ma Giới.","detail":"Ly Long Đảo được xác định là địa điểm gần Ma Kha Giới nhất. Theo chỉ dẫn của Phàn Bào Tử, sứ giả Long đảo sẽ tới tiếp đón hai người tại đây, nhưng vị trí gặp mặt chưa rõ.","theLucLienQuan":["Long đảo"],"nguon":["@c2435"]},{"id":"ma-kha-gioi","name":"Ma Kha Giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Giới diện mà Hàn Lập đang tìm đường tiếp cận thông qua Ly Long Đảo.","detail":"Hàn Lập xác định Ly Long Đảo là địa điểm gần Ma Kha Giới nhất và chuẩn bị phá giới từ một khe sâu tại Ma Giới để tiếp tục hành trình.","theLucLienQuan":[],"nguon":["@c2435"]},{"id":"hem-nui-tai-thanh-gioi","name":"Hẻm núi tại Thánh giới","cn":"","capDo":"khac","parentId":"thanh-gioi","blurb":"Hẻm núi nơi Hàn Lập mở vết nứt không gian để rời Thánh giới.","detail":"Sau khi Hàn Lập và Giải Đạo Nhân xuyên qua khe nứt, Bảo Hoa cùng Niết Bàn hiện thân tại đây và xác nhận họ đã bí mật theo dõi hành trình của hắn.","theLucLienQuan":["Ma tộc"],"nguon":["@c2436"]},{"id":"rung-phong-do-tham","name":"Rừng phong đỏ thẫm","cn":"","capDo":"khac","parentId":"ma-kha-gioi","blurb":"Khu rừng trên sườn núi tại Ma Kha Giới, nơi Hàn Lập dừng chân sau khi vượt giới.","detail":"Một tháng sau khi rời Thánh giới, Hàn Lập và Giải Đạo Nhân dừng tại đây để bàn về những người bám theo và cấm chế trí nhớ của Giải Đạo Nhân. Điền Phi Nhi sau đó tới địa điểm này để nghênh đón Hàn Lập.","theLucLienQuan":["Chân Long tộc"],"nguon":["@c2436"]},{"id":"long-dao","name":"Long Đảo","cn":"","capDo":"khac","parentId":null,"blurb":"Một khối gần giống bán cầu khổng lồ nằm giữa tinh không, được bao phủ bởi màn sáng xanh nhạt.","detail":"Bề mặt Long Đảo có nhiều kiến trúc và hình dạng hiện tại là kết quả cải tạo bằng pháp lực qua nhiều đời tổ tiên. Nơi đây tổ chức Đạo Quả Đại Hội và có những khu cấm địa mà khách dự không được tùy tiện xâm nhập.","theLucLienQuan":["Long Đảo","Chân Long Tộc"],"nguon":["@c2437"]},{"id":"quang-truong-ngoai-cung-dien-long-dao","name":"Quảng trường ngoài cung điện Long Đảo","cn":"","capDo":"khac","parentId":"long-dao","blurb":"Quảng trường đặt bên ngoài một cung điện lớn trên Long Đảo.","detail":"Hàn Lập và Điền Phi Nhi xuất hiện tại đây sau hành trình vượt hư không. Quảng trường có truyền tống pháp trận và bia đá mang lỗ khảm dùng tín vật để kích hoạt.","theLucLienQuan":["Long Đảo"],"nguon":["@c2437"]},{"id":"tieu-tran-tren-long-dao","name":"Tiểu trấn trên Long Đảo","cn":"","capDo":"thanh","parentId":"long-dao","blurb":"Tiểu trấn thương mại có khu vực phía Đông chuyên bán tài liệu.","detail":"Nơi đây có nhiều cửa hàng kín. Hàn Lập mua toàn bộ tám ngàn cân Phong Tinh Kim còn lại tại một cửa hàng trong trấn.","theLucLienQuan":["Tộc Chân Long"],"nguon":["@c2438"]},{"id":"son-mach-do-tham","name":"Sơn mạch đỏ thẫm","cn":"","capDo":"vuc","parentId":"long-dao","blurb":"Vùng sơn mạch đỏ thẫm trên Long Đảo.","detail":"Trong sơn mạch có một sơn cốc cùng bình đài kín, nơi Hàn Lập và sáu người khác tổ chức cuộc trao đổi bảo vật.","theLucLienQuan":["Tộc Chân Long"],"nguon":["@c2438"]},{"id":"ho-nuoc-khong-lo","name":"Hồ nước khổng lồ","cn":"","capDo":"khac","parentId":"long-dao","blurb":"Hồ lớn trên Long Đảo, nơi một chiếc thuyền vàng của tộc Chân Long neo đậu.","detail":"Kim Đại Trưởng lão tiếp Hàn Lập trên chiếc thuyền lớn màu vàng giữa hồ và thương lượng việc trao đổi Chân Hồn Đan.","theLucLienQuan":["Tộc Chân Long"],"nguon":["@c2438"]},{"id":"kim-sac-cu-thuyen","name":"Kim sắc cự thuyền","cn":"","capDo":"khac","parentId":"long-dao","blurb":"Cự thuyền màu vàng trên Long đảo, nơi Hàn Lập gặp Kim trưởng lão trước Đạo Quả Đại Hội.","detail":"Hàn Lập kiểm tra các lân phiến lưu ảnh độ kiếp và hoàn tất giao dịch Chân Hồn Đan với Kim trưởng lão tại đây, sau đó rời thuyền cùng Phàn Bào Tử.","theLucLienQuan":["Chân Long tộc"],"nguon":["@c2439"]},{"id":"khong-gian-cam-che-dao-qua-dai-hoi","name":"Không gian cấm chế Đạo Quả Đại Hội","cn":"","capDo":"gioi-nho","parentId":"long-dao","blurb":"Không gian rộng lớn riêng của Chân Long tộc, nơi cuộc tranh đoạt Đạo Quả chính thức diễn ra.","detail":"Khu vực Hàn Lập tiến vào có rừng cây cao vút và ẩn chứa mai phục. Nhiều đại thụ tại đây hóa thành cự nhân trăm trượng, dùng lôi hỏa và quyền ảnh tấn công hắn.","theLucLienQuan":["Chân Long tộc"],"nguon":["@c2439"]},{"id":"rung-ram-trong-khong-gian-tranh-doat","name":"Rừng rậm trong không gian tranh đoạt","cn":"","capDo":"khac","parentId":"khong-gian-cam-che-dao-qua-dai-hoi","blurb":"Khu rừng nơi Thiên Tượng Tôn Giả ẩn náu và bị Hàn Lập ép hiện thân.","detail":"Bình nhỏ của Hàn Lập hút và nghiền rừng cây cùng đất đá trên phạm vi rộng, biến khu vực thành một thung lũng đen cực lớn có đáy nhẵn bóng.","theLucLienQuan":[],"nguon":["@c2440"]},{"id":"sa-mac-mau-do-tham","name":"Sa mạc màu đỏ thẫm","cn":"","capDo":"khac","parentId":"khong-gian-cam-che-dao-qua-dai-hoi","blurb":"Sa mạc trong không gian tranh đoạt, nơi Hàn Lập săn một cự trùng huyễn thú.","detail":"Hàn Lập hóa thành Cự Viên vàng ba đầu sáu tay, đánh nát cự trùng dài hơn trăm trượng và lấy một Đạo Quả Lệnh Bài từ thi thể nó.","theLucLienQuan":[],"nguon":["@c2440"]},{"id":"hai-duong-menh-mong","name":"Hải dương mênh mông","cn":"","capDo":"khac","parentId":"khong-gian-cam-che-dao-qua-dai-hoi","blurb":"Vùng biển nơi ba người dự hội tranh giành một cự kình huyễn thú đang hấp hối.","detail":"Hàn Lập đối đầu lão giả áo vàng và Hoa Dung phu nhân tại đây. Hai người kia hợp sức dùng cự kiếm, bảo tháp và Phượng Hoàng lửa tấn công hắn.","theLucLienQuan":[],"nguon":["@c2440"]},{"id":"dao-dai-chi-nhan","name":"Đạo Đài Chi Nhân","cn":"","capDo":"khac","parentId":"khong-gian-cam-che-dao-qua-dai-hoi","blurb":"Đài cao ở trung tâm không gian tranh đoạt, nơi Long tộc kiểm đếm Đạo Bài và trao Quảng Linh Đạo Quả.","detail":"Hàn Lập là người đầu tiên đến đây với đủ một trăm lẻ tám Đạo Quả Lệnh Bài. Kim trưởng lão kiểm đếm lệnh bài, còn Phong trưởng lão trao linh quả cho hắn.","theLucLienQuan":["Long tộc"],"nguon":["@c2440"]}]};
